window.ERAS=[{"n": "Prehistory and the Stone Age", "r": "to c. 3300 BCE"}, {"n": "Indus Valley", "r": "Harappan) Civilization and Chalcolithic Cultures (c. 3300 to 1500 BCE"}, {"n": "Vedic Age", "r": "c. 1500 to 600 BCE"}, {"n": "Mahajanapadas, New Religions, and Alexander’s Invasion", "r": "c. 600 to 321 BCE"}, {"n": "Maurya Empire", "r": "321 to 185 BCE"}, {"n": "Post-Mauryan Age", "r": "c. 185 BCE to 319 CE"}, {"n": "Gupta Age and the Classical Era", "r": "c. 319 to 550 CE"}, {"n": "Early Medieval India", "r": "c. 550 to 1205 CE"}, {"n": "Delhi Sultanate and Contemporary Regional Powers", "r": "1205 to 1526"}, {"n": "Mughal Empire, Marathas, Sikhs, and the Arrival of Europeans", "r": "1526 to 1757"}, {"n": "Company Rule", "r": "1757 to 1858"}, {"n": "British Raj and the Freedom Struggle", "r": "1858 to 1947"}, {"n": "Independent India", "r": "1947 to 2026"}];
window.DATA=[{"i":0,"t":"Tribal and folk traditions","d":"Ancient and continuing traditions","g":"undated in the source","y":-2000000,"e":0,"s":[],"b":"<b>Tribal and folk traditions:</b> <b>Sarna</b>, <b>Donyi-Polo</b>, <b>Bon</b>, nature and ancestor worship among the Santhal, Munda, Gond, Bhil, Naga, Khasi, and others. <b>Baul</b> tradition (Bengal), <b>Warkari</b> (Maharashtra), <b>Lingayat</b>, <b>Ayyavazhi</b> (Tamil Nadu), <b>Ramanandi</b>, <b>Kabirpanth</b>, <b>Dadupanth</b>, <b>Sant Mat</b>, <b>Radha Soami</b> (1861)."},{"i":1,"t":"Lower Palaeolithic","d":"c. 2 million years ago","g":"Lower Palaeolithic","y":-2000000,"e":0,"s":["languages"],"b":"Earliest stone tools in the subcontinent, such as Soan Valley (Punjab) and Attirampakkam (Tamil Nadu). Hand-axe cultures (Acheulean)."},{"i":2,"t":"c. 385,000 to 172,000 years ago","d":"c. 385,000 to 172,000 years ago","g":"","y":-385000,"e":0,"s":[],"b":"Attirampakkam shows a shift to Middle Palaeolithic tools, suggesting early populations adapting."},{"i":3,"t":"Middle Palaeolithic","d":"c. 100,000 to 40,000 BCE","g":"Middle Palaeolithic","y":-100000,"e":0,"s":["places"],"b":"Flake tools; sites at Nevasa (Maharashtra), Bhimbetka (Madhya Pradesh)."},{"i":4,"t":"Upper Palaeolithic","d":"c. 40,000 to 10,000 BCE","g":"Upper Palaeolithic","y":-40000,"e":0,"s":["places"],"b":"Modern humans (<i>Homo sapiens</i>) present. Blade tools, bone tools. Bhimbetka rock shelters begin to show early paintings; Belan Valley, Renigunta."},{"i":5,"t":"Mesolithic","d":"c. 10,000 to 6,000 BCE","g":"Mesolithic","y":-10000,"e":0,"s":["places"],"b":"Microliths, hunter-gatherers, early domestication of animals. Rock art at Bhimbetka (a UNESCO World Heritage Site), Adamgarh, Bagor (Rajasthan), Sarai Nahar Rai (Uttar Pradesh)."},{"i":6,"t":"Mehrgarh","d":"c. 7000 BCE","g":"Neolithic begins","y":-7000,"e":0,"s":["places","science"],"b":"<b>Mehrgarh</b> (Balochistan, now Pakistan) shows earliest farming (wheat, barley), herding, mud-brick houses, and later pottery and dentistry (drilled teeth c. 7000 to 5500 BCE). Science and technology: dentistry at <b>Mehrgarh</b>. Era overview: <b>c. 7000 to 1300 BCE</b> covers the Neolithic to the Indus Valley Civilization."},{"i":7,"t":"c. 5000 to 3000 BCE","d":"c. 5000 to 3000 BCE","g":"","y":-5000,"e":0,"s":["kingdoms"],"b":"Neolithic spreads: Burzahom (Kashmir) with pit dwellings; Koldihwa (Uttar Pradesh) with early rice evidence; Chirand (Bihar); Brahmagiri and Maski (Karnataka); Daojali Hading (Assam)."},{"i":8,"t":"Early Harappan","d":"c. 3300 to 2600 BCE","g":"Early Harappan","y":-3300,"e":1,"s":["places"],"b":"Villages and early towns form in the Indus and Ghaggar-Hakra plains; Kot Diji, Amri, early Kalibangan and Rakhigarhi."},{"i":9,"t":"Chalcolithic","d":"c. 3000 to 1500 BCE","g":"Chalcolithic","y":-3000,"e":1,"s":[],"b":"Copper and stone use. Ahar-Banas (Rajasthan), Kayatha, Malwa, Jorwe (Maharashtra), Prabhas and Rangpur cultures."},{"i":10,"t":"Indus Valley (Harappan) Civilization","d":"c. 2600 to 1900 BCE","g":"Mature Harappan","y":-2600,"e":1,"s":["places"],"b":"Peak of the Bronze Age urban civilization of the <b>Indus Valley (Harappan) Civilization</b>, spread across Pakistan, northwest India, and Afghanistan (about 1,500 sites). Major cities: <b>Harappa</b> and <b>Mohenjo-daro</b> (Pakistan), <b>Dholavira</b>, <b>Lothal</b>, <b>Rakhigarhi</b> (Haryana, among the largest), <b>Kalibangan</b>, <b>Banawali</b>, <b>Surkotada</b>, <b>Ganweriwala</b>, <b>Sutkagen Dor</b> (coastal). Features: planned grid streets, standardized baked bricks, covered drains, the Great Bath at Mohenjo-daro, granaries, the Dholavira water reservoirs, dockyard at Lothal, standard weights, undeciphered script (about 400 signs) on seals, soapstone seals with the unicorn bull and Pashupati figure, bronze “Dancing Girl,” cotton cultivation, trade with Mesopotamia (called <i>Meluhha</i> in cuneiform texts)."},{"i":11,"t":"Indus script","d":"c. 2600 to 1900 BCE","g":"Language and script","y":-2600,"e":1,"s":["languages"],"b":"<b>Indus script</b> (undeciphered)."},{"i":12,"t":"Science and technology","d":"c. 2600 BCE","g":"Science and technology","y":-2600,"e":1,"s":["science"],"b":"Standardized weights, bricks, drainage, bead-making, and kiln technology of the Indus cities."},{"i":13,"t":"Architecture","d":"c. 2500 BCE","g":"Architecture","y":-2500,"e":1,"s":["places","architecture"],"b":"Great Bath, Mohenjo-daro; Dholavira’s water system; Lothal dock."},{"i":14,"t":"Late Harappan","d":"c. 1900 to 1300 BCE","g":"Late Harappan","y":-1900,"e":1,"s":["places"],"b":"Decline of urbanism: climate shift and weakening monsoon, drying or shifting of rivers (such as the Ghaggar-Hakra), falling trade. Population shifts east and south toward the Ganga plain and Gujarat."},{"i":15,"t":"Rigveda","d":"c. 1500 to 1000 BCE","g":"Early or Rigvedic Period","y":-1500,"e":2,"s":["religion"],"b":"Composition of the <b>Rigveda</b> (about 1,028 hymns) in the Punjab and Sapta Sindhu region. Gods: Indra, Agni, Varuna, Soma, Ushas. Tribal, pastoral society organized in <i>jana</i>, <i>vish</i>, and <i>kula</i>. Chiefs called <i>rajan</i>. Assemblies: <i>Sabha</i> and <i>Samiti</i>. Key tribes: Bharata, Purus, Yadus, Turvasas, Anus, Druhyus. Debate: the Aryan Migration/Indo-Aryan Migration theory (supported by linguistic and genetic evidence) versus indigenous origin arguments; mainstream scholarship favors gradual migrations from Central Asia during the second millennium BCE. Religion: Vedic religion with nature deities (Indra, Agni, Varuna, Soma), sacrifice (<i>yajna</i>), priestly specialization."},{"i":16,"t":"Vedic Sanskrit","d":"c. 1500 to 1000 BCE","g":"Language","y":-1500,"e":2,"s":["religion","languages"],"b":"<b>Vedic Sanskrit</b> (Rigveda). Oral transmission using elaborate memorization (<i>pathas</i>)."},{"i":17,"t":"Sulba Sutras","d":"c. 1500 to 500 BCE","g":"Science","y":-1500,"e":2,"s":["religion","science"],"b":"<b>Sulba Sutras</b> (Baudhayana, Apastamba) give geometry for altar construction, including a form of the Pythagorean theorem. <b>Vedanga Jyotisha</b> on calendar and astronomy. <b>Iron</b> and <b>wootz steel</b> production begins (later famed as Damascus steel)."},{"i":18,"t":"Battle of the Ten Kings (Dasarajna)","d":"c. 1300 to 1000 BCE","g":"Rigvedic","y":-1300,"e":2,"s":["wars","religion"],"b":"<b>Battle of the Ten Kings (Dasarajna):</b> Sudas of the Bharata tribe defeats a coalition of ten tribes on the Parushni (Ravi) river. Important early event in the Rigveda."},{"i":19,"t":"Ganga-Yamuna Doab","d":"c. 1000 to 600 BCE","g":"Later Vedic Period","y":-1000,"e":2,"s":["kingdoms","religion"],"b":"Shift to the <b>Ganga-Yamuna Doab</b> and eastward. Composition of <b>Samaveda</b>, <b>Yajurveda</b>, <b>Atharvaveda</b>, <b>Brahmanas</b>, <b>Aranyakas</b>, early <b>Upanishads</b>. Larger kingdoms: Kuru, Panchala, Kosala, Kashi, Videha. <b>Kuru</b> capital at Hastinapura. Rise of the four-fold varna system (Brahmin, Kshatriya, Vaishya, Shudra), growth of elaborate rituals (<i>Ashvamedha</i>, <i>Rajasuya</i>, <i>Vajapeya</i>), and gotra and ashrama ideas. Epics’ background: the core story of the <b>Mahabharata</b> (Kurukshetra war between Kauravas and Pandavas) is traditionally set in this period (the <b>Kurukshetra War</b> is a traditional epic event); the <b>Ramayana</b> (Ayodhya, Kosala) is likewise a tradition of the broader age. Composition of the epics as texts happened over many centuries (roughly 400 BCE to 400 CE). Philosophical foundations: Upanishadic thought (Atman, Brahman, karma, reincarnation, moksha) with thinkers like <b>Yajnavalkya</b>, <b>Uddalaka Aruni</b>, <b>Gargi</b>, <b>Maitreyi</b>."},{"i":20,"t":"Iron","d":"c. 1000 BCE onward","g":"","y":-1000,"e":2,"s":[],"b":"<b>Iron</b> (<i>shyama ayas</i>) enters use, allowing forest clearing and settled agriculture; Painted Grey Ware (PGW) culture in the Ganga-Yamuna region."},{"i":21,"t":"Zinc distillation","d":"c. 1st millennium BCE onward","g":"Metallurgy","y":-500,"e":2,"s":["science"],"b":"<b>Zinc distillation</b> in Zawar (Rajasthan) from c. 1st millennium BCE onward."},{"i":22,"t":"Hindu (Sanatana) Traditions","d":"c. 1000 BCE onward","g":"Hindu traditions","y":-1000,"e":2,"s":["religion","languages","leaders"],"b":"<b>Hindu (Sanatana) Traditions</b> develop from Vedic religion through the Upanishadic, epic and Puranic eras to the great acharyas: <b>Shankara</b>, <b>Ramanuja</b>, <b>Madhva</b>, <b>Nimbarka</b>, <b>Vallabha</b>, <b>Chaitanya</b>, <b>Basava</b>, <b>Ramananda</b>, <b>Jnaneshwar</b>, <b>Ramdas</b>."},{"i":23,"t":"Atman, Brahman, karma, samsara, moksha","d":"c. 800 to 500 BCE","g":"Upanishadic era","y":-800,"e":2,"s":["religion"],"b":"<i>Brihadaranyaka</i>, <i>Chandogya</i>, <i>Kena</i>, <i>Katha</i>, <i>Isha</i>, <i>Mundaka</i>, <i>Mandukya</i>; ideas of <b>Atman, Brahman, karma, samsara, moksha</b>; thinkers <b>Yajnavalkya</b>, <b>Gargi</b>, <b>Svetaketu</b>."},{"i":24,"t":"Parshvanatha","d":"c. 8th century BCE","g":"Jainism","y":-750,"e":2,"s":["religion","leaders"],"b":"<b>Parshvanatha</b>, the 23rd Tirthankara, among the <b>24 Tirthankaras</b> (<b>Rishabhanatha</b>, the first, to <b>Mahavira</b>)."},{"i":25,"t":"Second urbanization","d":"c. 600 BCE","g":"The Sixteen Mahajanapadas","y":-600,"e":3,"s":["kingdoms","religion"],"b":"Kashi, Kosala, Anga, Magadha, Vajji (Vriji), Malla, Chedi, Vatsa, Kuru, Panchala, Machchha (Matsya), Surasena, Assaka (Ashmaka), Avanti, Gandhara, Kamboja. (Listed in Buddhist text <i>Anguttara Nikaya</i>.) <b>Second urbanization</b> in the Gangetic plain: Northern Black Polished Ware (NBPW), punch-marked silver coins, guilds (<i>shrenis</i>), cities such as Rajagriha, Vaishali, Shravasti, Kaushambi, Ujjain, Varanasi, Champa, Taxila. Republics (<i>ganasanghas</i>) such as the Vajjis and Mallas, with assemblies, alongside monarchies."},{"i":26,"t":"Samkhya","d":"c. 6th century BCE","g":"heterodox schools, darshanas, medicine","y":-550,"e":3,"s":["religion","science"],"b":"Other heterodox schools: Ajivikas (Makkhali Gosala), Charvaka/Lokayata (materialism), Ajita Kesakambali. Six orthodox schools (<i>darshanas</i>) take shape over time: Samkhya, Yoga, Nyaya, Vaisheshika, Mimamsa, Vedanta (founders by tradition: <b>Samkhya</b> by Kapila, <b>Nyaya</b> by Gautama, <b>Vaisheshika</b> by Kanada, <b>Mimamsa</b> by Jaimini, <b>Vedanta</b> by Badarayana’s <i>Brahma Sutras</i>; <b>Yoga</b> is developed in <b>Patanjali’s Yoga Sutras</b>, c. 2nd century BCE to 4th century CE). <b>Sushruta</b> (surgeon, often placed c. 6th century BCE, text compiled later)."},{"i":27,"t":"Magadha-Kosala-Vajji wars.","d":"6th to 5th century BCE","g":"","y":-450,"e":3,"s":["wars"],"b":"<b>Magadha-Kosala-Vajji wars.</b>"},{"i":28,"t":"Mahavira Vardhamana","d":"c. 599 to 527 BCE","g":"or c. 540 to 468 BCE by other reckoning","y":-599,"e":3,"s":["religion","leaders"],"b":"<b>Mahavira Vardhamana</b>: twenty-fourth <i>Tirthankara</i> of <b>Jainism</b>. Principles: ahimsa, satya, asteya, brahmacharya, aparigraha. Born near Vaishali; attained <i>kevala jnana</i>."},{"i":29,"t":"Siddhartha Gautama, the Buddha","d":"c. 563 to 483 BCE","g":"or c. 480 to 400 BCE by some modern reckonings","y":-563,"e":3,"s":["places","religion","leaders"],"b":"<b>Siddhartha Gautama, the Buddha</b>: Born at Lumbini (Nepal), Shakya clan of Kapilavastu. Left home (the Great Renunciation) at 29. <b>Enlightenment at Bodh Gaya</b> under the Bodhi tree. <b>First sermon at Sarnath</b> (Dhammachakkappavattana Sutta): the Four Noble Truths and the Eightfold Path. Died (Mahaparinirvana) at <b>Kushinagar</b>. Disciples: Sariputta, Moggallana, Ananda, Mahakassapa, and Upali. Four sacred sites: <b>Lumbini</b> (birth), <b>Bodh Gaya</b> (enlightenment), <b>Sarnath</b> (first sermon), <b>Kushinagar</b> (death). <b>Sangha</b> of monks and nuns (<b>Mahapajapati Gotami</b> first nun)."},{"i":30,"t":"Achaemenid Persia","d":"c. 550 to 486 BCE","g":"Achaemenid Persia","y":-550,"e":3,"s":["religion","languages"],"b":"<b>Achaemenid Persia</b>: Cyrus the Great reaches Gandhara region; <b>Darius I</b> annexes Gandhara, Hindush (Indus valley) c. 518 BCE, listed as satrapies. Kharoshthi script (derived from Aramaic) emerges in the northwest."},{"i":31,"t":"Bimbisara","d":"r. c. 544 to 492 BCE","g":"Haryanka dynasty","y":-544,"e":3,"s":["kingdoms","rulers"],"b":"<b>Bimbisara</b> expands through conquests and marriage alliances, annexes Anga; capital Rajagriha."},{"i":32,"t":"Herodotus","d":"c. 5th century BCE","g":"Foreign writers","y":-450,"e":3,"s":["languages","visitors","sources"],"b":"<b>Herodotus</b> and <b>Ctesias</b> (Greek) write about India (gold-digging ants, Indus region) from Persian reports. <b>Scylax</b> of Caryanda explores the Indus for Darius."},{"i":33,"t":"Panini","d":"c. 500 BCE","g":"Panini, Prakrits, Ayurveda","y":-500,"e":3,"s":["places","religion","science","languages"],"b":"<b>Panini</b> (c. 5th to 4th century BCE) codifies Classical Sanskrit: <i>Ashtadhyayi</i>, a systematic Sanskrit grammar, near Gandhara/Taxila. <b>Prakrits</b> (Pali, Magadhi, Ardhamagadhi, Shauraseni) used by Buddhists and Jains. <b>Sushruta Samhita</b> (surgery: cataract, rhinoplasty, over 120 instruments) and <b>Charaka Samhita</b> (internal medicine; <b>Charaka</b>‘s text complete by c. 1st to 2nd century CE) are early foundations of <b>Ayurveda</b>."},{"i":34,"t":"Ajatashatru","d":"c. 492 to 460 BCE","g":"Haryanka dynasty","y":-492,"e":3,"s":["places","kingdoms","religion","rulers"],"b":"<b>Ajatashatru</b> defeats Kosala and the Vajji confederation; fortifies Pataliputra’s precursor (Pataligrama); the first Buddhist Council is held in his reign."},{"i":35,"t":"First Buddhist Council","d":"c. 483 BCE","g":"First Buddhist Council","y":-483,"e":3,"s":["religion"],"b":"<b>First Buddhist Council</b> (Rajagriha): compilation of Dhamma and Vinaya, led by Mahakassapa."},{"i":36,"t":"Shishunaga","d":"After the Haryanka dynasty","g":"Shishunaga dynasty","y":-483,"e":3,"s":["kingdoms","religion","leaders"],"b":"<b>Shishunaga</b> defeats Avanti; the second Buddhist Council at Vaishali under Kalashoka."},{"i":37,"t":"Second Council","d":"c. 383 BCE","g":"Second Buddhist Council","y":-383,"e":3,"s":["religion"],"b":"<b>Second Council</b> (Vaishali): split between Sthaviravada and Mahasanghika."},{"i":38,"t":"Mahapadma Nanda","d":"c. 345 to 321 BCE","g":"Nanda dynasty","y":-345,"e":3,"s":["kingdoms","rulers"],"b":"<b>Mahapadma Nanda</b> founds a vast empire, uprooting Kshatriya dynasties; later called “destroyer of all Kshatriyas” in Puranic tradition. Dhana Nanda, the last ruler, has a huge army and treasury and is overthrown by Chandragupta Maurya with Chanakya’s help."},{"i":39,"t":"Alexander the Great","d":"326 BCE","g":"Alexander’s invasion","y":-326,"e":3,"s":["places","wars","religion"],"b":"<b>Alexander the Great</b> of Macedon, after defeating Persia, crosses the Hindu Kush, takes Taxila (king Ambhi submits). <b>Battle of the Hydaspes (Jhelum):</b> Alexander defeats <b>King Porus (Puru)</b>, but reinstates him as ally. Alexander’s army, exhausted, mutinies at the <b>Beas (Hyphasis)</b> river and refuses to go further east. Alexander’s historians (<b>Nearchus</b>, <b>Onesicritus</b>, <b>Aristobulus</b>, writing c. 326 to 324 BCE) describe the Indus and the sea voyage back. War list: <b>Alexander vs Porus</b>."},{"i":40,"t":"325 to 323 BCE","d":"325 to 323 BCE","g":"","y":-325,"e":3,"s":[],"b":"Alexander retreats via the Indus and Makran desert. His death at Babylon (323 BCE) leaves Greek satrapies in the northwest to quickly collapse. Effects: opened land and sea routes, Greek-Indian cultural exchange, and a political vacuum that Chandragupta Maurya filled."},{"i":41,"t":"321 to 185 BCE","d":"321 to 185 BCE","g":"Maurya Empire begins","y":-321,"e":4,"s":["kingdoms","rulers","leaders"],"b":"Era overview: <b>321 to 185 BCE</b> is the age of the Mauryas. <b>c. 321 BCE:</b> <b>Chandragupta Maurya</b> (ruler lists: c. 321 to 297 BCE), guided by <b>Chanakya (Kautilya/Vishnugupta)</b>, overthrows the Nandas; takes Pataliputra. Chanakya’s text <b>Arthashastra</b> on statecraft. Administration: centralized bureaucracy, spies (<i>gudhapurusha</i>), standing army, provinces (Taxila, Ujjain, Tosali, Suvarnagiri), capital Pataliputra. Economy with royal control of mines and trade."},{"i":42,"t":"Seleucus I Nicator","d":"c. 305 BCE","g":"","y":-305,"e":4,"s":["kingdoms","wars"],"b":"Chandragupta defeats <b>Seleucus I Nicator</b> (Alexander’s general). Treaty: Seleucus cedes territories in Arachosia, Gedrosia, Paropamisadae, and Aria; receives 500 war elephants. War list: <b>Chandragupta vs Seleucus</b>. Greek ambassador <b>Megasthenes</b> lives at Chandragupta’s court, writes <i>Indica</i>."},{"i":43,"t":"Megasthenes","d":"c. 302 to 298 BCE","g":"Foreign writers","y":-302,"e":4,"s":["places","kingdoms","visitors","sources"],"b":"<b>Megasthenes</b> (Seleucid envoy) at Pataliputra writes <i>Indica</i> (survives only in fragments quoted by Arrian, Strabo, Diodorus). Describes seven classes of society, the city administration, and Mauryan spies."},{"i":44,"t":"Brahmi script","d":"3rd century BCE","g":"Language, science, architecture","y":-250,"e":4,"s":["kingdoms","science","architecture","languages","leaders","sources"],"b":"<b>Brahmi script</b> in Ashokan edicts (c. 3rd century BCE); <b>Kharoshthi</b> in the northwest. All later Indian scripts evolve from Brahmi. <b>Pingala</b> works on prosody and binary-like patterns. <b>Mauryan</b> engineering: roads, wells, polished pillars. Architecture: <b>Ashokan pillars</b> and <b>Barabar caves</b> (Ajivika caves, Bihar); <b>Great Stupa at Sanchi</b> (first built by Ashoka; enlarged under the Shungas; gateways under the Satavahanas, 1st century BCE to CE)."},{"i":45,"t":"Council of Pataliputra","d":"c. 300 BCE","g":"Jain council","y":-300,"e":4,"s":["places","religion"],"b":"<b>Council of Pataliputra</b> (c. 300 BCE; <b>Sthulabhadra</b>)."},{"i":46,"t":"Three Tamil kingdoms","d":"c. 300 BCE to 300 CE","g":"Sangam Age and Tamil-Brahmi","y":-300,"e":4,"s":["places","kingdoms","wars","languages"],"b":"<b>Three Tamil kingdoms:</b> <b>Cheras</b> (Vanji, Muziris), <b>Cholas</b> (Uraiyur, Puhar/Kaveripattinam), <b>Pandyas</b> (Madurai, Korkai). Early Chola king <b>Karikala</b> wins the Battle of Venni. Chera king <b>Senguttuvan</b> (Red Chera) is linked to the Pattini (Kannagi) cult. Pandya king <b>Nedunchezhiyan</b> appears in epics. <b>Sangam literature:</b> Tolkappiyam (grammar), Ettuthokai, Pattuppattu, Pathinenkilkanakku, and epics <b>Silappatikaram</b> (Ilango Adigal) and <b>Manimekalai</b> (Sattanar). Poets include <b>Avvaiyar</b>, <b>Kapilar</b>, and <b>Nakkirar</b>. <b>Tamil-Brahmi</b> inscriptions. Trade: Roman gold flows to Muziris, Arikamedu (Puducherry), Poompuhar, Korkai; pepper, pearls, muslin, ivory. Roman coin hoards found across the south. Spiritual: Sangam deities such as Murugan, Mayon (Vishnu), and Korravai; growth of Jain and Buddhist communities in Tamil country."},{"i":47,"t":"Bhadrabahu","d":"c. 298 BCE","g":"","y":-298,"e":4,"s":["kingdoms","religion"],"b":"Chandragupta abdicates and, per Jain tradition, goes with <b>Bhadrabahu</b> to Shravanabelagola (Karnataka) and fasts to death (<i>sallekhana</i>). Bhadrabahu’s migration to Karnataka is linked to the later split between Digambara and Shvetambara Jains."},{"i":48,"t":"Bindusara","d":"c. 298 to 272 BCE","g":"Bindusara","y":-298,"e":4,"s":["kingdoms","visitors","rulers"],"b":"<b>Bindusara</b> (“Amitraghata”) extends the empire to the Deccan; maintains relations with Antiochus I. Ambassador Deimachos. (Ruler lists give Bindusara c. 297 to 273 BCE.)"},{"i":49,"t":"c. 273 BCE","d":"c. 273 BCE","g":"","y":-273,"e":4,"s":["rulers","leaders"],"b":"The reign of Ashoka is sometimes counted from this year (ruler lists)."},{"i":50,"t":"Ashoka the Great","d":"c. 268 to 232 BCE","g":"Ashoka the Great","y":-268,"e":4,"s":["places","kingdoms","architecture","leaders","sources"],"b":"<b>Ashoka the Great</b> (consecration after a succession struggle). Edicts engraved on rocks and pillars (Major and Minor Rock Edicts; pillar edicts at Sarnath, Lauriya Nandangarh, Rampurva, Delhi-Topra), written in Brahmi, Kharoshthi, Greek, and Aramaic. Lion Capital at Sarnath (later India’s national emblem); stupas at Sanchi, Bharhut origins. Welfare: hospitals, roads, shade trees, wells; <i>dhamma mahamattas</i> (officers)."},{"i":51,"t":"Kalinga War","d":"261 BCE","g":"","y":-261,"e":4,"s":["kingdoms","wars","religion","leaders"],"b":"<b>Kalinga War</b> (modern Odisha) causes huge loss of life; Ashoka is remorseful and turns to <b>Buddhism</b> (under Upagupta or Nigrodha, by tradition) and <b>dhamma</b>. War list: Kalinga War."},{"i":52,"t":"Third Buddhist Council","d":"c. 250 BCE","g":"","y":-250,"e":4,"s":["places","kingdoms","religion"],"b":"<b>Third Buddhist Council</b> at Pataliputra under <b>Moggaliputta Tissa</b>. Missionaries sent to Sri Lanka (his son <b>Mahinda</b> and daughter <b>Sanghamitta</b>), Greek kingdoms, Southeast Asia (Suvarnabhumi), and elsewhere. Spread of Buddhism: <b>Ashoka’s</b> missions to Sri Lanka (c. 250 BCE) and Central Asia via Gandhara."},{"i":53,"t":"Schools","d":"c. 250 BCE onward","g":"Buddhist schools","y":-250,"e":4,"s":["religion"],"b":"<b>Schools:</b> <b>Theravada</b> (Sri Lanka, Southeast Asia), <b>Mahayana</b> (<b>Nagarjuna’s</b> Madhyamaka; <b>Asanga</b> and <b>Vasubandhu’s</b> Yogachara), <b>Vajrayana</b> (tantric; Padmasambhava, Atisha). Buddhism spreads to Central Asia via Gandhara, and later to Korea, Japan, Tibet, and Southeast Asia."},{"i":54,"t":"Brihadratha","d":"232 to 185 BCE","g":"","y":-232,"e":4,"s":["kingdoms","rulers"],"b":"Weak successors (Dasharatha, Samprati, and others; ruler list also names Shalishuka, Devavarman, Shatadhanvan). <b>Brihadratha</b>, the last Mauryan, is assassinated by his general <b>Pushyamitra Shunga</b> in 185 BCE."},{"i":55,"t":"Simuka","d":"c. 230 BCE to 220 CE","g":"Satavahana dynasty","y":-230,"e":4,"s":["places","kingdoms","architecture","languages","rulers","leaders"],"b":"Founder <b>Simuka</b>; capital Pratishthana (Paithan), then Amaravati. (Later rulers and achievements are listed at their dates below.) Prakrit language, Karle and Ajanta (early) caves, Amaravati and Nagarjunakonda stupas, trade with Rome."},{"i":56,"t":"Post-Mauryan Age","d":"c. 200 BCE to 300 CE","g":"Post-Mauryan Age","y":-200,"e":4,"s":["kingdoms"],"b":"Era overview: Shungas, Satavahanas, Kushanas, Sangam age."},{"i":57,"t":"Natya Shastra","d":"c. 200 BCE to 200 CE","g":"texts","y":-200,"e":4,"s":["science","languages","sources"],"b":"<b>Natya Shastra</b> of <b>Bharata Muni</b> on drama, music, dance; early <b>Jataka tales</b>; <b>Dhammapada</b>; <b>Milindapanha</b>. <b>Bakhshali manuscript</b> (a mathematical text with an early dot for zero; carbon-dated to a range from the 3rd to 7th centuries CE). <b>Jain mathematics</b> (Bhadrabahu, Umasvati). <b>Manusmriti</b> (Manava Dharmashastra) and <b>Yajnavalkya Smriti</b> are composed. Rise of Bhagavatism (Vaishnavism) and Shaivism as devotional streams."},{"i":58,"t":"Ajanta","d":"2nd century BCE","g":"Ajanta and art","y":-150,"e":4,"s":["places","kingdoms","religion","architecture"],"b":"<b>Ajanta</b> caves (earliest Satavahana-era Buddhist caves c. 2nd century BCE); <b>Karle</b>, <b>Bhaja</b>, <b>Kanheri</b>. <b>Bharhut stupa</b>, <b>Karle chaitya</b>, <b>Bhaja</b> and <b>Bedsa</b>, <b>Udayagiri-Khandagiri</b> caves (Odisha), <b>Amaravati</b> stupa, <b>Gandhara</b> monasteries (Taxila, Takht-i-Bahi), <b>Mathura school</b> sculpture (2nd century BCE to 2nd century CE)."},{"i":59,"t":"Pushyamitra Shunga","d":"c. 185 to 73 BCE","g":"Shunga dynasty","y":-185,"e":5,"s":["places","kingdoms","architecture"],"b":"<b>Pushyamitra Shunga</b> performs Ashvamedha; patronage of Brahmanism; Sanchi and Bharhut stupa railings expanded; <b>Patanjali</b> (author of <i>Mahabhashya</i> and often linked with the Yoga Sutras tradition). <b>Agnimitra</b> (hero of Kalidasa’s <i>Malavikagnimitram</i>). Later <b>Bhagabhadra</b> and the Heliodorus pillar at Besnagar (Vidisha), where a Greek ambassador honors Vasudeva. War list: <b>Pushyamitra’s campaigns</b> and the <b>Greek (Yavana) invasion</b> (2nd century BCE)."},{"i":60,"t":"Demetrius I","d":"c. 180 BCE to 10 CE","g":"Indo-Greeks","y":-180,"e":5,"s":["religion","languages"],"b":"<b>Demetrius I</b> crosses the Hindu Kush. Greek coinage with Greek and Kharoshthi legends; <b>Gandhara art</b> blends Greek and Buddhist styles."},{"i":61,"t":"Menander I (Milinda)","d":"c. 165 to 130 BCE","g":"Menander","y":-165,"e":5,"s":["religion"],"b":"<b>Menander I (Milinda)</b> rules from Sagala (Sialkot); converses with Buddhist monk <b>Nagasena</b> in the <i>Milindapanha</i>."},{"i":62,"t":"Kharavela of Kalinga","d":"1st century BCE","g":"Kharavela, Sakas, Tirukkural","y":-50,"e":5,"s":["kingdoms","wars","religion","languages","sources"],"b":"<b>Kharavela of Kalinga</b>: Jain king, <b>Hathigumpha inscription</b> at Udayagiri (Odisha) records his campaigns; defeats Magadha (war list: Kharavela vs Satavahanas and Magadha). <b>Indo-Scythians (Sakas)</b> (c. 1st century BCE onward): Maues, Azes. <b>Thiruvalluvar’s Tirukkural</b> is traditionally placed in the Sangam period or soon after (c. 1st century BCE to 5th century CE). Satavahana-era gateways at Sanchi (1st century BCE to CE)."},{"i":63,"t":"Vasudeva Kanva","d":"c. 73 to 28 BCE","g":"Kanva dynasty","y":-73,"e":5,"s":["kingdoms","rulers"],"b":"<b>Vasudeva Kanva</b> overthrows Shungas; four rulers."},{"i":64,"t":"Gondophares","d":"c. 20 to 50 CE","g":"Indo-Parthians","y":20,"e":5,"s":[],"b":"<b>Gondophares</b>; tradition connects St. Thomas (apostle) to his court."},{"i":65,"t":"Kujula Kadphises","d":"c. 30 to 375 CE","g":"Kushana Empire","y":30,"e":5,"s":["kingdoms","religion","languages","leaders"],"b":"Founded by <b>Kujula Kadphises</b>; Silk Road trade; gold coins; Gandhara and Mathura art; <b>Mahayana</b> Buddhism patronized. Notable figures: <b>Ashvaghosha</b> (<i>Buddhacharita</i>, also Sanskrit poetry), <b>Nagarjuna</b> (Madhyamaka philosophy), <b>Charaka</b>, Vasumitra."},{"i":66,"t":"St. Thomas","d":"52 CE","g":"Christianity","y":52,"e":5,"s":["religion"],"b":"Tradition holds <b>St. Thomas</b> arrives on the Malabar coast in 52 CE. <b>Jews</b> settle at Cochin (Kerala) in ancient and early medieval periods. (<b>Syrian Christians</b> of Kerala.)"},{"i":67,"t":"Kanishka I","d":"c. 78 to 144 CE","g":"Kanishka I","y":78,"e":5,"s":["kingdoms","rulers"],"b":"<b>Kanishka I</b> (or traditionally 78 CE) is the greatest Kushana ruler, with capitals at Purushapura (Peshawar) and Mathura. The <b>Shaka era (78 CE)</b> is traditionally associated with his accession (though debated). <b>Fourth Buddhist Council</b> at Kundalavana, Kashmir (Vasumitra/Ashvaghosha), in Kanishka’s time. Patronage of <b>Mahayana</b> Buddhism. The Silk Road carries Buddhism to China (1st century CE)."},{"i":68,"t":"Pliny the Elder","d":"c. 1st century CE","g":"Travellers and Western Satraps","y":50,"e":5,"s":["visitors"],"b":"<i>Periplus of the Erythraean Sea</i> (anonymous Greek sailor’s guide to Indian ports, goods, and kings) and <b>Pliny the Elder</b> (complains of Roman gold lost to India) describe the trade. <b>Digambara</b> and <b>Shvetambara</b> Jain split (roughly the 1st to 3rd century CE)."},{"i":69,"t":"Gautamiputra Satakarni","d":"c. 106 to 130 CE","g":"Gautamiputra Satakarni","y":106,"e":5,"s":["kingdoms","wars"],"b":"<b>Gautamiputra Satakarni</b> defeats the Western Satraps (Nahapana) and the Shakas, Yavanas, Pahlavas (war list: c. 120s CE). Later Satavahanas: <b>Vashishthiputra Pulumavi</b> and <b>Yajna Sri Satakarni</b> (coins with ships)."},{"i":70,"t":"Western Satraps (Kshatrapas)","d":"c. 130 to 150 CE","g":"Rudradaman I","y":130,"e":5,"s":["places","kingdoms","religion","languages","sources"],"b":"<b>Western Satraps (Kshatrapas):</b> <b>Rudradaman I</b> rules from Ujjain; his <b>Junagadh rock inscription</b> (c. 150 CE) is the earliest long Sanskrit inscription; repairs <b>Sudarshana Lake</b> built in Mauryan times."},{"i":71,"t":"Ptolemy’s","d":"2nd century CE","g":"","y":150,"e":5,"s":["science","visitors"],"b":"<b>Ptolemy’s</b> <i>Geography</i> maps India’s coasts and cities. <b>Charaka Samhita</b> reaches its present form by c. 1st to 2nd century CE."},{"i":72,"t":"c. 220 CE","d":"c. 220 CE","g":"","y":220,"e":5,"s":["kingdoms"],"b":"End of the Satavahana dynasty (begun c. 230 BCE)."},{"i":73,"t":"Vatsyayana’s Kamasutra","d":"c. 3rd century CE","g":"","y":250,"e":5,"s":[],"b":"<b>Vatsyayana’s Kamasutra</b>."},{"i":74,"t":"Sri Gupta","d":"c. 275 to 319 CE","g":"Early Guptas","y":275,"e":5,"s":["kingdoms"],"b":"<b>Sri Gupta</b> and <b>Ghatotkacha</b>. <b>Pallavas (c. 275 to 897 CE; peak 6th to 9th century)</b> emerge at Kanchipuram."},{"i":75,"t":"end of Sangam Age","d":"c. 300 CE","g":"end of Sangam Age","y":300,"e":5,"s":["kingdoms"],"b":"The Sangam Age (c. 300 BCE to 300 CE) closes; Post-Mauryan era overview ends."},{"i":76,"t":"Chandragupta I","d":"c. 319 to 335 CE","g":"Chandragupta I","y":319,"e":6,"s":["kingdoms"],"b":"<b>Chandragupta I</b> marries the Lichchhavi princess <b>Kumaradevi</b>; begins the <b>Gupta era (320 CE)</b>. Era overview: <b>c. 320 to 550 CE</b> is the Gupta age (the classical era)."},{"i":77,"t":"Samudragupta","d":"c. 335 to 375 CE","g":"Samudragupta","y":335,"e":6,"s":["kingdoms","architecture"],"b":"<b>Samudragupta</b>, “the Napoleon of India” (V. A. Smith’s comparison). The <b>Allahabad Pillar (Prayagraj Prashasti)</b> by <b>Harishena</b> describes his conquests: Aryavarta kings eliminated; Dakshinapatha kings defeated and restored (the <i>grahana-moksha-anugraha</i> policy); frontier kings and tribal republics subdued. He performs the Ashvamedha; coins show him playing the veena; patronizes poets and Buddhist scholar <b>Vasubandhu</b>. War list: <b>Samudragupta’s Digvijaya</b> (4th century). Ramagupta (disputed) is also listed after him."},{"i":78,"t":"Kalidasa","d":"c. 4th to 5th century CE","g":"Language and literature","y":450,"e":6,"s":["kingdoms","languages"],"b":"<b>Kalidasa</b>; <b>Gupta script</b>; <b>Panchatantra</b> (Vishnu Sharma); <b>Amarakosha</b> (Sanskrit thesaurus); <b>Aryabhatiya</b> (499 CE). Literature of the Gupta age: <b>Shudraka’s</b> <i>Mrichchhakatika</i>, <b>Vishakhadatta’s</b> <i>Mudrarakshasa</i>, Puranas compiled, Smritis, <b>Vatsyayana</b>. Chess (<i>Chaturanga</i>) evolves; metallurgy."},{"i":79,"t":"Chandragupta II (Vikramaditya)","d":"c. 375 to 415 CE","g":"Chandragupta II, Vikramaditya","y":375,"e":6,"s":["kingdoms"],"b":"<b>Chandragupta II (Vikramaditya)</b>: defeats the Western Satraps (Rudrasimha III), annexes Malwa and Gujarat, strengthening trade through ports like Bharuch. Court “Navaratnas” traditionally include <b>Kalidasa</b> (<i>Abhijnanashakuntalam</i>, <i>Meghaduta</i>, <i>Raghuvamsha</i>), Amarasimha, Varahamihira, Dhanvantari (traditional). The <b>Iron Pillar of Delhi</b> (Mehrauli) is usually attributed to this reign (c. 4th to 5th century CE: rust-resistant, c. 1,600 years old; shows advanced metallurgy; attribution varies by source). Vakataka dynasty in the Deccan: Pravarasena I, Rudrasena II linked to Prabhavatigupta, Chandragupta II’s daughter."},{"i":80,"t":"Kushana end","d":"c. 375 CE","g":"Kushana end","y":375,"e":6,"s":["kingdoms"],"b":"The Kushana Empire (c. 30 to 375 CE) ends."},{"i":81,"t":"Chinese pilgrim Faxian (Fa-Hien)","d":"399 to 414 CE","g":"Faxian","y":399,"e":6,"s":["places","kingdoms","visitors"],"b":"<b>Chinese pilgrim Faxian (Fa-Hien)</b> visits and describes peaceful, prosperous life; he travels from Chang’an through Gandhara, Mathura, Pataliputra, Bodh Gaya, and Sri Lanka, during Chandragupta II’s reign. Writes <i>Fo-kuo-ki</i>."},{"i":82,"t":"Mahabharata","d":"c. 400 CE","g":"epics and regional powers","y":400,"e":6,"s":["languages"],"b":"<b>Mahabharata</b> (about 100,000 verses, with the <b>Bhagavad Gita</b>) and <b>Ramayana</b> (Valmiki) reach roughly their present form by c. 400 CE (c. 400 BCE to 400 CE). <b>Puranas</b> (18 Mahapuranas) are compiled over the following centuries. <b>Kadambas</b> of Banavasi (Mayurasharman) and <b>Western Gangas</b> (Talakad) in Karnataka. Religion: epic and Puranic era (c. 400 BCE to 1000 CE) with <b>Bhagavata</b> (Vaishnava), <b>Pashupata</b> (Shaiva), <b>Shakta</b> traditions; <b>Trimurti</b> concept; avatars (<b>Dashavatara</b>); temple worship and idol worship spread; <b>Bhagavad Gita’s</b> karma, bhakti, jnana yogas. Gupta-era revival of Brahmanical Hinduism with temple worship; Vaishnavism, Shaivism, Shaktism. Pilgrimage sites: <b>Kashi (Varanasi)</b>, <b>Rameswaram</b>, <b>Dwarka</b>, <b>Badrinath</b> (Char Dham), <b>Kedarnath</b>, <b>Puri</b>, <b>Tirupati</b>, <b>Vaishno Devi</b>, <b>Amarnath</b>, <b>Kumbh Mela</b> (Prayagraj, Haridwar, Ujjain, Nashik), <b>Jyotirlingas</b> (12)."},{"i":83,"t":"Kumaragupta I","d":"c. 415 to 455 CE","g":"Kumaragupta I","y":415,"e":6,"s":["places","kingdoms","religion"],"b":"<b>Kumaragupta I</b> founds <b>Nalanda</b> university (traditional); the Hunas threaten the borders. Nalanda flourishes as a Buddhist university from the 5th to 12th century."},{"i":84,"t":"Ajanta","d":"5th century CE","g":"Arts","y":450,"e":6,"s":["places","architecture"],"b":"<b>Ajanta</b> (Caves 16 and 17 under Vakatakas; paintings of Vakataka patronage under <b>Harishena</b>, c. 5th century CE), <b>Dashavatara Temple, Deogarh</b>, <b>Bhitargaon</b> (brick temple), <b>Udayagiri (Vidisha)</b> caves, <b>Nalanda</b> complex, <b>Mahabodhi temple</b> (earliest structure), Sarnath Buddha images. Buddhist logic (Dignaga, Dharmakirti later), Vasubandhu and Asanga (Yogachara)."},{"i":85,"t":"Eastern Gangas of Odisha","d":"c. 5th to 15th century","g":"Eastern Gangas of Odisha","y":1450,"e":6,"s":["places","architecture","rulers"],"b":"<b>Eastern Gangas of Odisha</b>: <b>Anantavarman Chodagangadeva</b> (1078 to 1147) builds the <b>Jagannath Temple, Puri</b>; <b>Narasimhadeva I</b> builds the <b>Konark Sun Temple</b> (c. 1250). (Listed in this long span; key reigns are repeated at their dates.)"},{"i":86,"t":"Jain councils at Valabhi","d":"c. 453 or 466 CE","g":"Jain council","y":453,"e":6,"s":["religion"],"b":"<b>Jain councils at Valabhi</b> compile Svetambara canon (c. 5th century CE)."},{"i":87,"t":"Skandagupta","d":"c. 455 to 467 CE","g":"Skandagupta","y":455,"e":6,"s":["kingdoms","wars","religion","languages","sources"],"b":"<b>Skandagupta</b> repulses the first Huna invasion (c. 455 to 458 CE) and repairs the Sudarshana Lake (Junagadh inscription). War list: <b>Gupta-Huna wars</b> (c. 455, c. 528). Next Guptas: Purugupta, Kumaragupta II."},{"i":88,"t":"Aryabhata","d":"476 to 550 CE","g":"Aryabhata and Budhagupta","y":476,"e":6,"s":["kingdoms","science"],"b":"<b>Aryabhata</b> (b. 476 CE): <i>Aryabhatiya</i> (499 CE): the earth rotates, explanations of eclipses, sine tables, pi approximately 3.1416, quadratic equations, place value, zero as a placeholder in practice. The decimal place-value system and zero (later transmitted to Arabs and then Europe). <b>Budhagupta</b> (c. 476 to 495 CE)."},{"i":89,"t":"Hunas","d":"c. 500 to 550 CE","g":"Gupta decline","y":500,"e":6,"s":["kingdoms","religion","rulers"],"b":"Gupta decline; <b>Hunas</b> under <b>Toramana</b> and <b>Mihirakula</b> (c. 502 to 530 CE) raid; Mihirakula defeated by Yashodharman of Malwa and Narasimhagupta Baladitya (c. 528 CE). Other later Gupta rulers include Vainyagupta, Kumaragupta III, and <b>Vishnugupta</b> (c. 540 to 550 CE)."},{"i":90,"t":"Cosmas Indicopleustes","d":"6th century CE","g":"Cosmas","y":550,"e":6,"s":["religion"],"b":"<b>Cosmas Indicopleustes</b> (Greek merchant) notes Christian communities in Malabar and Sri Lanka (c. 6th century CE)."},{"i":91,"t":"Varahamihira","d":"505 to 587 CE","g":"Varahamihira","y":505,"e":6,"s":[],"b":"<b>Varahamihira</b>: <i>Brihat Samhita</i>, <i>Panchasiddhantika</i> (<i>Pancha-Siddhantika</i>)."},{"i":92,"t":"Pulakeshin I","d":"c. 543 to 753 CE","g":"Badami or Early Western Chalukyas","y":543,"e":6,"s":["kingdoms","architecture","leaders"],"b":"Founder <b>Pulakeshin I</b>. Temples at <b>Aihole</b>, <b>Badami</b>, <b>Pattadakal</b> (UNESCO)."},{"i":93,"t":"Era overview: c. 550 to 1200 CE","d":"Era overview: c. 550 to 1200 CE","g":"","y":550,"e":7,"s":["kingdoms"],"b":"Harsha, Chalukyas, Pallavas, Rashtrakutas, Palas, Cholas, Rajputs."},{"i":94,"t":"Badami cave temples","d":"c. 6th to 8th century","g":"Architecture","y":750,"e":7,"s":["architecture"],"b":"<b>Badami cave temples</b>, <b>Aihole (Durga temple)</b>, <b>Pattadakal</b> (Virupaksha, Papanatha), <b>Elephanta Caves</b> (Shaiva, near Mumbai), <b>Mamallapuram</b> (Pancha Rathas, Shore Temple, Arjuna’s Penance relief), <b>Kailasanatha at Kanchipuram</b>, <b>Meenakshi</b> (earlier layers)."},{"i":95,"t":"Dandin","d":"c. 6th to 7th century CE","g":"Literature","y":650,"e":7,"s":["languages"],"b":"<b>Dandin</b> (<i>Dashakumaracharita</i>), <b>Banabhatta</b> (<i>Kadambari</i>), <b>Bharavi</b> (<i>Kiratarjuniya</i>), <b>Magha</b>, <b>Bhartrihari</b> (<i>Shatakatraya</i>), <b>Bhavabhuti</b> (<i>Malatimadhava</i>, <i>Uttararamacharita</i>, 8th century)."},{"i":96,"t":"Pandyas","d":"c. 590 CE","g":"Pandyas","y":590,"e":7,"s":["kingdoms"],"b":"<b>Pandyas (c. 6th to 10th centuries; revival 13th century; c. 6th to 14th century in the other list):</b> <b>Kadungon</b> revived them c. 590. Other Pandya names: Maravarman Arikesari."},{"i":97,"t":"Brahmagupta","d":"598 to 668 CE","g":"Brahmagupta","y":598,"e":7,"s":["kingdoms","science"],"b":"<b>Brahmagupta</b>: rules for zero, negative numbers, quadratic solutions, an early treatment of the Brahmagupta identity (7th century)."},{"i":98,"t":"Mahendravarman I","d":"c. 600 to 630 CE","g":"Mahendravarman I","y":600,"e":7,"s":["kingdoms","languages"],"b":"<b>Mahendravarman I</b> of the Pallavas (Sanskrit play <i>Mattavilasa Prahasana</i>); <b>Simhavishnu</b> also listed among the Pallavas."},{"i":99,"t":"Pushyabhuti (Vardhana) dynasty","d":"r. 606 to 647 CE","g":"Harshavardhana","y":606,"e":7,"s":["kingdoms","languages","rulers"],"b":"<b>Pushyabhuti (Vardhana) dynasty:</b> <b>Harshavardhana (Harsha)</b>, capital Kanauj (earlier Thanesar). Poet <b>Banabhatta</b> wrote <i>Harshacharita</i>. Harsha wrote Sanskrit plays (<i>Ratnavali</i>, <i>Nagananda</i>, <i>Priyadarshika</i>). Harsha held the <b>Kanauj assembly</b> and the <b>Prayag Mahamoksha</b> (quinquennial charity). After Harsha’s death (647 CE), no heir; fragmentation."},{"i":100,"t":"Pulakeshin II","d":"r. 610 to 642 CE","g":"Pulakeshin II","y":610,"e":7,"s":["kingdoms","rulers"],"b":"<b>Pulakeshin II</b> of the Badami Chalukyas."},{"i":101,"t":"Pulakeshin II","d":"c. 618 to 619 CE","g":"","y":618,"e":7,"s":["kingdoms","wars"],"b":"Harsha is defeated by the Chalukya king <b>Pulakeshin II</b> on the Narmada. War list: Harsha vs Pulakeshin II (c. 618)."},{"i":102,"t":"Arab traders","d":"7th century CE","g":"Arab traders","y":650,"e":7,"s":["religion"],"b":"Early Arab traders in Malabar (from the 7th century) and early Islam on the coast."},{"i":103,"t":"Brahmagupta’s","d":"628 CE","g":"","y":628,"e":7,"s":["kingdoms","science"],"b":"<b>Brahmagupta’s</b> <i>Brahmasphutasiddhanta</i>."},{"i":104,"t":"Bhaskara I","d":"629 CE","g":"","y":629,"e":7,"s":["kingdoms","religion","science"],"b":"<b>Bhaskara I</b> (commentaries on Aryabhata; 7th to 8th century), along with <b>Lalla</b> and <b>Vagbhata</b> (<i>Ashtanga Hridaya</i>, Ayurveda). <b>Cheraman Juma Masjid</b> (traditionally 629 CE, Kodungallur), early coast community of Arab traders in Malabar."},{"i":105,"t":"Xuanzang (Hiuen Tsang)","d":"630 to 644 CE","g":"Xuanzang","y":630,"e":7,"s":["places","languages","visitors","sources"],"b":"<b>Xuanzang (Hiuen Tsang)</b> visited 630 to 644 CE and studied at <b>Nalanda</b> under <b>Shilabhadra</b>, attending Harsha’s Kanauj assembly; writes <i>Si-Yu-Ki</i>. Brings back hundreds of Sanskrit manuscripts."},{"i":106,"t":"Narasimhavarman I Mamalla","d":"630 to 668 CE","g":"Narasimhavarman I Mamalla","y":630,"e":7,"s":["places","kingdoms","architecture"],"b":"<b>Narasimhavarman I Mamalla</b> (Pallava): Mamallapuram/<b>Mahabalipuram</b> rock-cut Rathas; Shore Temple built later by Narasimhavarman II."},{"i":107,"t":"Aihole inscription","d":"634 CE","g":"","y":634,"e":7,"s":["languages","sources"],"b":"<b>Aihole inscription</b> (Ravikirti)."},{"i":108,"t":"c. 636 to 711 CE","d":"c. 636 to 711 CE","g":"","y":636,"e":7,"s":[],"b":"Early Arab raids (Thane, Bharuch) by sea; naval raids on Debal."},{"i":109,"t":"Narasimhavarman I","d":"642 CE","g":"","y":642,"e":7,"s":["kingdoms","wars"],"b":"Pallava <b>Narasimhavarman I</b> defeats Pulakeshin II and sacks Badami. War list: Pulakeshin II vs Pallavas (642 at Badami)."},{"i":110,"t":"Rajput clans","d":"7th to 8th century","g":"Tibet and Rajputs","y":750,"e":7,"s":["kingdoms","religion"],"b":"<b>Rajput clans</b> rise (Gurjara-Pratiharas, Chauhans, Paramaras, Solankis/Chaulukyas, Chandelas, Guhilas/Sisodias, Tomaras, Kalachuris). Buddhism spreads to Tibet (7th to 8th century)."},{"i":111,"t":"Yijing (I-Tsing)","d":"671 to 695 CE","g":"Yijing","y":671,"e":7,"s":["places","religion","languages","visitors"],"b":"<b>Yijing (I-Tsing)</b> visits Nalanda and Srivijaya; writes about Buddhist monastic practice and Sanskrit studies."},{"i":112,"t":"Muhammad bin Qasim","d":"711 to 713 CE","g":"Arab conquest of Sind","y":711,"e":7,"s":["wars"],"b":"<b>Muhammad bin Qasim</b> conquers <b>Sind</b> (defeating <b>Raja Dahir</b> at Rawar, 712 CE), establishing Arab rule; the first lasting Muslim foothold in India. <i>Chachnama</i> is the source text on the conquest. War list: Arab conquest of Sind."},{"i":113,"t":"Kashmir","d":"c. 724 to 760 CE","g":"Lalitaditya","y":724,"e":7,"s":["kingdoms","architecture"],"b":"<b>Kashmir:</b> <b>Karkota dynasty</b>, <b>Lalitaditya Muktapida</b> builds the Martand Sun Temple (8th century)."},{"i":114,"t":"Nagabhata I","d":"c. 725 to 1036 CE","g":"Gurjara-Pratiharas","y":725,"e":7,"s":[],"b":"<b>Nagabhata I</b> repels Arab raids at Avanti. <b>Mihira Bhoja</b> (c. 836 to 885 CE) is the greatest; capital Kanauj. They resisted early Arab expansion. The <b>Tripartite Struggle for Kanauj</b> (8th to 9th century) occurs between the Gurjara-Pratiharas (west), <b>Palas</b> (east), and <b>Rashtrakutas</b> (Deccan); war list: Rashtrakuta-Pratihara-Pala wars (8th to 10th century)."},{"i":115,"t":"Gopala","d":"c. 750 to 1161 CE","g":"Pala dynasty of Bengal and Bihar","y":750,"e":7,"s":["places","kingdoms","religion"],"b":"<b>Gopala</b> was elected as king; <b>Dharmapala</b> (c. 770 to 810 CE) founded <b>Vikramashila</b> university (8th century) and revived <b>Nalanda</b>; <b>Devapala</b>, and <b>Mahipala I</b>. Strong Mahayana and Vajrayana Buddhism; <b>Somapura Mahavihara</b> (Paharpur)."},{"i":116,"t":"Dantidurga","d":"c. 753 to 982 CE","g":"Rashtrakutas","y":753,"e":7,"s":["places","kingdoms","architecture","visitors"],"b":"<b>Dantidurga</b>, <b>Krishna I</b> (<b>Kailasa temple</b> at <b>Ellora</b>, 8th century, carved from a single rock), <b>Dhruva</b>, <b>Govinda III</b>, <b>Amoghavarsha I</b>. Capital Manyakheta. Arab traveller <b>Sulaiman</b> calls them one of the world’s four great empires. Kannada literature flourishes (poet <b>Pampa</b>, <b>Ponna</b>). <b>Ellora</b> Buddhist, Hindu, Jain caves."},{"i":117,"t":"Adi Shankaracharya","d":"c. 788 to 820 CE","g":"Adi Shankaracharya","y":788,"e":7,"s":["religion","leaders"],"b":"<b>Adi Shankaracharya</b> (c. 8th century; traditionally born at Kaladi), consolidates <b>Advaita Vedanta</b>, establishes four <i>mathas</i> (Sringeri, Dwarka, Puri, Jyotirmath/Joshimath); revitalizes Hindu thought, debates with Buddhists and Mimamsakas (Kumarila Bhatta, Mandana Mishra). Great acharya of Advaita."},{"i":118,"t":"Cheras of Mahodayapuram","d":"c. 800 to 1102 CE","g":"Cheras of Mahodayapuram","y":800,"e":7,"s":["kingdoms"],"b":"<b>Cheras of Mahodayapuram</b>: Kulasekhara Alvar; Kerala traditions."},{"i":119,"t":"Bhakti movement begins in the Tamil south","d":"c. 7th to 9th century CE","g":"Bhakti and Tamil hymns","y":850,"e":7,"s":["religion","languages"],"b":"<b>Bhakti movement begins in the Tamil south:</b> Alvars (12 poet-saints, including <b>Andal</b>, <b>Nammalvar</b>) and Nayanars (63, including <b>Appar</b>, <b>Sambandar</b>, <b>Sundarar</b>, <b>Manikkavasagar</b>, <b>Karaikkal Ammaiyar</b>). Tamil bhakti hymns (<b>Tevaram</b>, <b>Nalayira Divya Prabandham</b>). <b>Malayalam</b> emerges from Tamil-Malayalam."},{"i":120,"t":"Zoroastrians (Parsis)","d":"c. 8th to 10th century","g":"Parsis, Arab rule limited","y":950,"e":7,"s":["religion"],"b":"<b>Zoroastrians (Parsis)</b> arrive in Gujarat (Sanjan), fleeing Arab conquest of Persia (traditionally c. 8th to 10th century). Arab rule remains limited to Sind and Multan (c. 8th to 9th century); Hindu Shahi dynasty in Kabul-Punjab (<b>Jayapala</b>, <b>Anandapala</b>). Parsis later include the <b>Tata</b> and <b>Godrej</b> families, <b>Dadabhai Naoroji</b>, <b>Pherozeshah Mehta</b>, <b>Bhikaji Cama</b>, <b>Field Marshal Sam Manekshaw</b>."},{"i":121,"t":"Amoghavarsha I","d":"r. 814 to 878 CE","g":"Amoghavarsha I","y":814,"e":7,"s":["kingdoms","religion","rulers"],"b":"<b>Amoghavarsha I</b> (Rashtrakuta; Jain; author of <i>Kavirajamarga</i>)."},{"i":122,"t":"Mahavira","d":"c. 820 CE","g":"9th century science","y":850,"e":7,"s":["kingdoms","science","leaders"],"b":"<b>Mahavira</b> (mathematician; <i>Ganita Sara Sangraha</i>); decimal system and zero spread to Arab scholars (<b>Al-Khwarizmi</b> c. 820), then to Europe through <b>Fibonacci’s</b> <i>Liber Abaci</i> (1202)."},{"i":123,"t":"Mihira Bhoja","d":"c. 836 to 885 CE","g":"","y":836,"e":7,"s":["architecture"],"b":"<b>Mihira Bhoja</b> of the Gurjara-Pratiharas. Osian temples (9th to 10th century)."},{"i":124,"t":"Vijayalaya Chola","d":"c. 848 to 1279 CE","g":"Imperial Cholas","y":848,"e":7,"s":["places","kingdoms","languages"],"b":"<b>Vijayalaya Chola</b> captures Thanjavur (c. 848) (ruled c. 848 to 871). Culture: Chola bronzes (Nataraja); Kamban’s <i>Ramavataram</i> (Tamil Ramayana); <b>Sekkizhar’s</b> <i>Periya Puranam</i>; Alvars and Nayanars. Administration: Village assemblies (<i>Sabha</i>, <i>Ur</i>, <i>Nagaram</i>)."},{"i":125,"t":"Kannada","d":"c. 850 CE","g":"Kannada","y":850,"e":7,"s":[],"b":"Early <b>Kannada</b> (<i>Kavirajamarga</i>, c. 850)."},{"i":126,"t":"Sulaiman","d":"c. 851 CE","g":"Sulaiman","y":851,"e":7,"s":["kingdoms"],"b":"<b>Sulaiman</b> (Arab merchant) writes on the Rashtrakutas and Palas."},{"i":127,"t":"Aditya I","d":"871 to 907 CE","g":"Aditya I","y":871,"e":7,"s":["kingdoms"],"b":"<b>Aditya I</b> (Chola) defeats the Pallava Aparajita."},{"i":128,"t":"Kailasanatha temple","d":"c. 897 CE","g":"","y":897,"e":7,"s":["kingdoms","architecture"],"b":"Pallavas (c. 275 to 897 CE) are defeated by the Cholas. Pallava sites include the <b>Kailasanatha temple</b> at Kanchipuram."},{"i":129,"t":"Parantaka I","d":"907 to 955 CE","g":"Parantaka I","y":907,"e":7,"s":["kingdoms","rulers"],"b":"<b>Parantaka I</b> (Chola) is defeated at <b>Takkolam (949)</b> by the Rashtrakutas. Chola ruler list continues: Gandaraditya, Arinjaya."},{"i":130,"t":"Al-Masudi","d":"c. 915 CE","g":"","y":915,"e":7,"s":[],"b":"<b>Al-Masudi</b> visits Gujarat and the Konkan."},{"i":131,"t":"Uttaramerur inscriptions","d":"c. 920 CE","g":"","y":920,"e":7,"s":["languages","sources"],"b":"The <b>Uttaramerur inscriptions</b> describe village elections by lot with qualifications."},{"i":132,"t":"Pampa Bharata","d":"941 CE","g":"10th century","y":950,"e":7,"s":[],"b":"<b>Pampa Bharata</b> (Adikavi <b>Pampa</b>, 941), <b>Ranna</b>, <b>Ponna</b> (the “three gems” of Kannada)."},{"i":133,"t":"Takkolam","d":"949 CE","g":"","y":949,"e":7,"s":["kingdoms","wars"],"b":"Battle of <b>Takkolam</b>: Cholas defeated by the Rashtrakutas."},{"i":134,"t":"Chandela dynasty","d":"c. 950 to 1050 CE","g":"Khajuraho; Chandelas","y":950,"e":7,"s":["places","kingdoms","architecture"],"b":"<b>Chandela dynasty:</b> <b>Khajuraho</b> temples (<b>Lakshmana</b>, <b>Kandariya Mahadeva</b>); <b>Dhanga</b> and <b>Vidyadhara</b>. Also <b>Sas-Bahu</b> temples (Gwalior)."},{"i":135,"t":"Kashmir Shaivism","d":"c. 950 to 1016 CE","g":"Abhinavagupta","y":950,"e":7,"s":["kingdoms"],"b":"<b>Kashmir Shaivism</b> (<b>Vasugupta</b>, <b>Abhinavagupta</b>), Tantra, Vajrayana, Nath Yogis (Gorakhnath), Siddha traditions, Shakti Peethas, Kali and Durga worship, Bengal Tantra."},{"i":136,"t":"Sundara Chola (Parantaka II)","d":"957 to 973 CE","g":"","y":957,"e":7,"s":["kingdoms"],"b":"<b>Sundara Chola (Parantaka II)</b>."},{"i":137,"t":"Taila II","d":"c. 973 to 1189 CE","g":"Later or Western Chalukyas of Kalyani","y":973,"e":7,"s":["kingdoms","languages","leaders"],"b":"<b>Taila II</b>; <b>Vikramaditya VI</b> (1076 to 1126); poet <b>Bilhana</b> (<i>Vikramankadevacharita</i>), jurist <b>Vijnaneshvara</b> (<i>Mitakshara</i>). <b>Basavanna</b> (12th century) founds the <b>Lingayat/Virashaiva</b> reform with Kalyana as base; <b>Anubhava Mantapa</b>, <i>vachanas</i>."},{"i":138,"t":"Uttama Chola","d":"973 to 985 CE","g":"","y":973,"e":7,"s":["kingdoms"],"b":"<b>Uttama Chola</b>."},{"i":139,"t":"Gommateshwara/Bahubali","d":"981 CE","g":"","y":981,"e":7,"s":["religion"],"b":"<b>Gommateshwara/Bahubali</b> statue, Shravanabelagola (Western Gangas; Jain patronage)."},{"i":140,"t":"Rajaraja I","d":"985 to 1014 CE","g":"Rajaraja I","y":985,"e":7,"s":["places","kingdoms","wars","architecture"],"b":"<b>Rajaraja I</b> conquers Cheras, Pandyas, Sri Lanka (northern), the Maldives; builds the <b>Brihadisvara Temple, Thanjavur</b> (completed 1010). Navy and land revenue survey. War list: Chola conquest of Sri Lanka (c. 993 to 1014)."},{"i":141,"t":"Ghaznavids","d":"998 to 1030 CE","g":"Mahmud of Ghazni","y":998,"e":7,"s":["wars"],"b":"<b>Ghaznavids:</b> <b>Mahmud of Ghazni</b> makes about 17 raids (war list: 1000 to 1027). <b>Firdausi</b> (<i>Shahnama</i>)."},{"i":142,"t":"Prambanan","d":"9th to 10th century","g":"Architecture","y":950,"e":7,"s":["places","architecture"],"b":"<b>Prambanan</b>-style influences abroad; <b>Osian</b> temples; <b>Khajuraho</b> begins; <b>Sas-Bahu</b> temples (Gwalior)."},{"i":143,"t":"1008 CE","d":"1008 CE","g":"","y":1008,"e":7,"s":["kingdoms","wars"],"b":"Mahmud defeats Anandapala (Battle of Waihind)."},{"i":144,"t":"Brihadisvara Temple, Thanjavur","d":"1010 CE","g":"","y":1010,"e":7,"s":["places","kingdoms","architecture"],"b":"<b>Brihadisvara Temple, Thanjavur</b> completed. <b>Paramara king Bhoja</b> (c. 1010 to 1055 CE) of Dhar, a scholar-king."},{"i":145,"t":"Rajendra I","d":"1014 to 1044 CE","g":"Rajendra I","y":1014,"e":7,"s":["kingdoms"],"b":"<b>Rajendra I</b>: expedition to the Ganga (founding <b>Gangaikonda Cholapuram</b>, c. 1025), naval raids against <b>Srivijaya</b> (Sumatra, 1025), giving the Cholas control of Southeast Asian trade routes. Trade and temple guilds (<i>Manigramam</i>, <i>Ayyavole</i>)."},{"i":146,"t":"Ramanuja","d":"c. 1017 to 1137 CE","g":"Ramanuja","y":1017,"e":7,"s":["leaders"],"b":"<b>Ramanuja</b>: <b>Vishishtadvaita</b> philosophy; Srirangam. Hoysala king <b>Vishnuvardhana</b> (Bittiga) converted under his influence."},{"i":147,"t":"Mathura","d":"1018 to 1019 CE","g":"","y":1018,"e":7,"s":[],"b":"Mahmud sacks <b>Mathura</b> (1018) and <b>Kanauj</b> (1018 to 1019)."},{"i":148,"t":"Somnath","d":"1025 CE","g":"","y":1025,"e":7,"s":["kingdoms"],"b":"Mahmud sacks <b>Somnath</b> (Somnath rebuilt under <b>Bhima I</b> of the <b>Solankis of Gujarat</b>). Rajendra I’s naval raids on Srivijaya and Gangaikonda Cholapuram. Solankis of Gujarat: <b>Mularaja</b>, <b>Siddharaja Jayasimha</b>; Modhera Sun Temple, Rani ki Vav at Patan. Jain scholar <b>Hemachandra</b>."},{"i":149,"t":"Hoysalas","d":"c. 1026 to 1343 CE","g":"Hoysalas","y":1026,"e":7,"s":["architecture"],"b":"<b>Hoysalas:</b> Capital Belur then Halebidu; temples at <b>Belur</b>, <b>Halebidu</b>, <b>Somanathapura</b>. <b>Sun Temple at Modhera</b> (1026)."},{"i":150,"t":"Al-Biruni","d":"c. 1030 CE","g":"Al-Biruni","y":1030,"e":7,"s":["religion","science","languages","visitors","rulers","sources"],"b":"<b>Al-Biruni</b> (<i>Kitab al-Hind</i>) studies Sanskrit, Hindu astronomy, philosophy, customs; notable account of Indian science and society. Mahmud’s reign ends (1030)."},{"i":151,"t":"c. 1036 CE","d":"c. 1036 CE","g":"","y":1036,"e":7,"s":[],"b":"End of the Gurjara-Pratiharas (c. 725 to 1036)."},{"i":152,"t":"Atisha Dipankara","d":"c. 1042 CE","g":"","y":1042,"e":7,"s":[],"b":"Missionary <b>Atisha Dipankara</b> of the Palas goes to Tibet."},{"i":153,"t":"Rajadhiraja I","d":"1044 to 1070 CE","g":"later Cholas","y":1044,"e":7,"s":["kingdoms"],"b":"<b>Rajadhiraja I</b> (1044 to 1054; killed at Koppam), <b>Rajendra II</b> (1054 to 1063), <b>Virarajendra</b> (1063 to 1070)."},{"i":154,"t":"Telugu","d":"c. 11th century","g":"Telugu, architecture","y":1050,"e":7,"s":["kingdoms","religion","architecture","languages"],"b":"<b>Telugu</b> literature begins with <b>Nannaya’s</b> Mahabharata (c. 11th century). <b>Lingaraja Temple</b>, Bhubaneswar (11th century). <b>Dilwara Jain Temples</b>, Mount Abu (11th to 13th century). <b>Gangaikonda Cholapuram</b> (architecture)."},{"i":155,"t":"Kulottunga I","d":"1070 to 1122 CE","g":"Kulottunga I","y":1070,"e":7,"s":["kingdoms"],"b":"<b>Kulottunga I</b> unites Chola and Eastern Chalukya lines."},{"i":156,"t":"Sena dynasty","d":"c. 1070 to 1230 CE","g":"Sena dynasty","y":1070,"e":7,"s":["kingdoms","languages"],"b":"<b>Sena dynasty</b> in Bengal: Vijayasena, <b>Ballala Sena</b>, <b>Lakshmana Sena</b>; poet <b>Jayadeva</b> (<i>Gita Govinda</i>)."},{"i":157,"t":"Anantavarman Chodagangadeva","d":"1078 to 1147 CE","g":"","y":1078,"e":7,"s":["architecture"],"b":"<b>Anantavarman Chodagangadeva</b> (Eastern Gangas) builds the <b>Jagannath Temple, Puri</b> (begun 12th century)."},{"i":158,"t":"Kalhana","d":"11th to 12th century","g":"Literature","y":1150,"e":7,"s":["languages","leaders"],"b":"<b>Kalhana</b>; <b>Jayadeva’s Gita Govinda</b>; <b>Kamban’s Tamil Ramayana</b> (12th century); <b>Sekkizhar’s Periya Puranam</b>; <b>Basava’s vachanas</b>; <b>Chand Bardai</b> (<i>Prithviraj Raso</i>)."},{"i":159,"t":"Jain patronage","d":"12th century","g":"Jain patronage","y":1150,"e":7,"s":["kingdoms","religion","architecture"],"b":"<b>Jain patronage:</b> <b>Solanki kings</b> (<b>Kumarapala</b> with <b>Hemachandra</b>), <b>Dilwara</b> and <b>Ranakpur</b> temples. Earlier Jain patrons: <b>Chandragupta Maurya</b>, <b>Kharavela</b>, <b>Amoghavarsha</b>, <b>Western Gangas</b>."},{"i":160,"t":"Vikrama Chola","d":"1118 to 1135 CE","g":"","y":1118,"e":7,"s":["kingdoms"],"b":"<b>Vikrama Chola</b>."},{"i":161,"t":"Kulottunga II","d":"1133 to 1150 CE","g":"","y":1133,"e":7,"s":[],"b":"<b>Kulottunga II</b>; also Rajaraja II and Rajadhiraja II."},{"i":162,"t":"Kalhana’s","d":"c. 1148 CE","g":"","y":1148,"e":7,"s":["sources"],"b":"<b>Kalhana’s</b> <i>Rajatarangini</i>, a notable early history chronicle."},{"i":163,"t":"Bhaskara II","d":"1150 CE","g":"","y":1150,"e":7,"s":["places","science","architecture"],"b":"<b>Bhaskara II</b>: <i>Lilavati</i>, <i>Bijaganita</i>, <i>Siddhanta Shiromani</i> (1150 CE); concepts that anticipate calculus (instantaneous motion). 12th to 13th century architecture: Hoysala temples, <b>Ramappa Temple</b>, <b>Konark Sun Temple</b> (c. 1250), <b>Qutb Minar</b> (begun 1199), <b>Quwwat-ul-Islam Mosque</b>, <b>Adhai Din Ka Jhonpra</b> (Ajmer), <b>Iltutmish’s tomb</b>."},{"i":164,"t":"various periods; listed without dates in the source","d":"Indigenous chronicles and texts","g":"various periods; listed without dates in the source","y":1150,"e":7,"s":["sources"],"b":"<i>Rajatarangini</i> (Kalhana), <i>Harshacharita</i> (Banabhatta), <i>Prithviraj Raso</i>, <i>Chachnama</i> (Arab conquest of Sind), <i>Tabaqat-i-Nasiri</i> (Minhaj-i-Siraj), <i>Tarikh-i-Firuz Shahi</i> (Barani), <i>Baburnama</i>, <i>Tuzuk-i-Jahangiri</i>, <i>Akbarnama</i>, <i>Ain-i-Akbari</i>, <i>Padshahnama</i>, <i>Muntakhab-ut-Tawarikh</i> (Badauni), <i>Shivabharata</i>, <i>Buranjis</i> (Ahom chronicles)."},{"i":165,"t":"Kakatiyas","d":"c. 1163 to 1323 CE","g":"Kakatiyas","y":1163,"e":7,"s":["architecture"],"b":"<b>Kakatiyas</b> of Warangal: <b>Ganapati Deva</b>, <b>Rani Rudrama Devi</b>, <b>Prataparudra II</b>; <b>Ramappa Temple</b> (UNESCO)."},{"i":166,"t":"Benjamin of Tudela","d":"1167 to 1173 CE","g":"","y":1167,"e":7,"s":["visitors"],"b":"<b>Benjamin of Tudela</b> (Jewish traveller) describes the Malabar coast Jewish communities."},{"i":167,"t":"Prithviraj Chauhan III","d":"r. 1177 to 1192 CE","g":"","y":1177,"e":7,"s":["rulers"],"b":"<b>Prithviraj Chauhan III</b> of the Chauhans of Ajmer/Delhi."},{"i":168,"t":"Muhammad of Ghor (Shihabuddin)","d":"1178 CE","g":"","y":1178,"e":7,"s":["rulers"],"b":"<b>Muhammad of Ghor (Shihabuddin)</b> first defeated by Bhima II of Gujarat. <b>Kulottunga III</b> (1178 to 1218 CE) also begins his reign."},{"i":169,"t":"Ramachandra","d":"c. 1187 to 1317 CE","g":"Yadavas of Devagiri","y":1187,"e":7,"s":[],"b":"<b>Ramachandra</b> submits to Alauddin Khalji (1296), then fully annexed by 1317."},{"i":170,"t":"First Battle of Tarain","d":"1191 CE","g":"","y":1191,"e":7,"s":["wars"],"b":"<b>First Battle of Tarain:</b> Prithviraj Chauhan defeats Ghori."},{"i":171,"t":"Second Battle of Tarain","d":"1192 CE","g":"","y":1192,"e":7,"s":["wars"],"b":"<b>Second Battle of Tarain:</b> Ghori defeats Prithviraj, opening the path to Delhi."},{"i":172,"t":"Bakhtiyar Khalji","d":"c. 1193 CE","g":"","y":1193,"e":7,"s":["places","religion"],"b":"<b>Bakhtiyar Khalji</b> destroys Nalanda (c. 1193); <b>Qutb ud-Din Aibak</b> takes Delhi (1193). Decline of Buddhism in much of India after 1193: loss of royal patronage, Brahmanical revival, and destruction of monasteries; universities include <b>Takshashila</b> (Taxila), <b>Nalanda</b> (5th to 12th century), <b>Vikramashila</b> (8th century), <b>Odantapuri</b>, <b>Somapura</b>, <b>Vallabhi</b>."},{"i":173,"t":"Decline of Buddhism","d":"After 1193 CE","g":"Decline of Buddhism","y":1193,"e":7,"s":["religion"],"b":"<b>Decline of Buddhism</b> in much of India after the 12th century: loss of patronage, Brahmanical revival, Turkish conquests, and destruction of monasteries after 1193. <b>Revival:</b> <b>Anagarika Dharmapala</b> (Maha Bodhi Society, 1891), <b>Ambedkar’s</b> mass conversion (1956), <b>Tibetan Buddhist</b> exiles from 1959."},{"i":174,"t":"Battle of Chandawar","d":"1194 CE","g":"","y":1194,"e":7,"s":["wars"],"b":"<b>Battle of Chandawar:</b> defeat of Jaichand of Kanauj."},{"i":175,"t":"Qutb Minar","d":"1199 CE","g":"","y":1199,"e":7,"s":["places","architecture"],"b":"<b>Qutb Minar</b> begun."},{"i":176,"t":"Bakhtiyar Khalji","d":"c. 1200 CE","g":"","y":1200,"e":7,"s":[],"b":"<b>Bakhtiyar Khalji</b> destroys Vikramashila (c. 1200). Era ends: c. 550 to 1200 CE."},{"i":177,"t":"Bakhtiyar Khalji","d":"c. 1204 CE","g":"","y":1204,"e":7,"s":[],"b":"<b>Bakhtiyar Khalji</b> raids Bengal (c. 1204)."},{"i":178,"t":"1206 to 1526","d":"c. 1200 to 1526 CE","g":"Delhi Sultanate and regional powers, overview","y":1200,"e":8,"s":["places","kingdoms","religion","architecture","languages","rulers"],"b":"Era overview: <b>1206 to 1526</b>: Delhi Sultanate; Vijayanagara and Bahmani kingdoms. Culture: Indo-Islamic architecture (Qutb complex, Alai Darwaza, Tughlaqabad, Lodi Gardens); Persian and Urdu/Hindavi literature (<b>Amir Khusrau</b>, <b>Ziauddin Barani</b>, <b>Isami</b>, <b>Minhaj-i-Siraj</b>); <b>Sufism</b> (Chishti: <b>Moinuddin Chishti</b> at Ajmer, <b>Nizamuddin Auliya</b>, <b>Baba Farid</b>; Suhrawardi: <b>Bahauddin Zakariya</b>); Hindu-Muslim cultural synthesis; <b>Sangeet</b> development. Sufi orders in India: <b>Chishti</b> (<b>Moinuddin</b>, <b>Bakhtiyar Kaki</b>, <b>Baba Farid</b>, <b>Nizamuddin Auliya</b>, <b>Salim Chishti</b>), <b>Suhrawardi</b>, <b>Qadiri</b>, <b>Naqshbandi</b>, <b>Firdausi</b>. Religious movements: <b>Mahdawi</b> (Jaunpur). Regional Sultanates: Jaunpur (Sharqi, notable architecture), Bengal (Ilyas Shahi, Husain Shahi), Gujarat (Ahmed Shah, Mahmud Begada), Malwa (Mandu), Khandesh. Rajput states: <b>Mewar</b> (<b>Rana Kumbha</b>, <b>Rana Sanga</b>), <b>Marwar</b>, <b>Amber</b>. Kingdoms in the northeast and elsewhere: <b>Gajapatis</b> of Odisha, <b>Reddys</b>, <b>Zamorin of Calicut</b>."},{"i":179,"t":"Mirabai","d":"c. 13th to 17th century","g":"Bhakti and Sufi movements","y":1650,"e":8,"s":["religion","leaders"],"b":"Bhakti and Sufi movements. Bhakti saints include <b>Mirabai</b> (Rajasthan), <b>Surdas</b>, <b>Tulsidas</b>, <b>Tukaram</b>, <b>Namdev</b>, <b>Eknath</b>, <b>Dnyaneshwar</b>, <b>Purandara Dasa</b> (Karnataka), <b>Annamacharya</b>, <b>Narsinh Mehta</b>, <b>Shankaradeva</b> (Assam, Ekasarana), <b>Vallabhacharya</b> (Pushtimarg); dated details are given below. <b>Nimbarka</b> and <b>Vallabha</b> (later) develop Bhakti-Vedanta schools."},{"i":180,"t":"Mamluk (Slave) dynasty","d":"1206 to 1290 CE","g":"Mamluk or Slave dynasty","y":1206,"e":8,"s":["places","kingdoms","religion","architecture"],"b":"<b>Mamluk (Slave) dynasty</b> begins. <b>Qutb ud-Din Aibak</b> (1206 to 1210) begins the <b>Qutb Minar</b> and Quwwat-ul-Islam mosque."},{"i":181,"t":"Aram Shah","d":"1210 to 1211 CE","g":"","y":1210,"e":8,"s":[],"b":"<b>Aram Shah</b>."},{"i":182,"t":"Iltutmish","d":"1211 to 1236 CE","g":"Iltutmish","y":1211,"e":8,"s":[],"b":"<b>Iltutmish</b>: consolidates; receives investiture from the Abbasid caliph (1229); introduces the silver <i>tanka</i> and copper <i>jital</i>; the <b>Iqta system</b>."},{"i":183,"t":"Maravarman Sundara Pandya","d":"1216 to 1238 CE","g":"","y":1216,"e":8,"s":["kingdoms"],"b":"<b>Maravarman Sundara Pandya</b> (Pandya revival)."},{"i":184,"t":"1221 CE","d":"1221 CE","g":"","y":1221,"e":8,"s":["wars"],"b":"Mongols (Genghis Khan) reach the Indus but do not enter. War list: Mongol invasions (1221, 1241 Lahore sacked, 1290s to 1306)."},{"i":185,"t":"Ahom","d":"1228 to 1826 CE","g":"Ahom dynasty","y":1228,"e":8,"s":["kingdoms"],"b":"<b>Ahom</b> dynasty of Assam, founded by <b>Sukaphaa</b>."},{"i":186,"t":"1229 CE","d":"1229 CE","g":"","y":1229,"e":8,"s":[],"b":"Iltutmish receives investiture from the Abbasid caliph."},{"i":187,"t":"Ruknuddin Firuz","d":"1236 to 1240 CE","g":"Razia Sultana","y":1236,"e":8,"s":["kingdoms","rulers"],"b":"<b>Ruknuddin Firuz</b> (1236). <b>Razia Sultana</b> (1236 to 1240): first and only woman ruler of Delhi Sultanate; overthrown by the <i>Chihalgani</i> (Forty)."},{"i":188,"t":"Madhvacharya","d":"c. 1238 to 1317 CE","g":"Madhvacharya","y":1238,"e":8,"s":[],"b":"<b>Madhvacharya</b> (Udupi): <b>Dvaita</b> philosophy."},{"i":189,"t":"Bahram Shah","d":"1240 to 1246 CE","g":"","y":1240,"e":8,"s":[],"b":"<b>Bahram Shah</b> (1240 to 1242), <b>Masud Shah</b> (1242 to 1246)."},{"i":190,"t":"1241 CE","d":"1241 CE","g":"","y":1241,"e":8,"s":["wars"],"b":"Mongols sack Lahore (war list)."},{"i":191,"t":"Nasiruddin Mahmud","d":"1246 to 1266 CE","g":"","y":1246,"e":8,"s":[],"b":"<b>Nasiruddin Mahmud</b>."},{"i":192,"t":"Konark Sun Temple","d":"c. 1250 CE","g":"","y":1250,"e":8,"s":["places","architecture"],"b":"<b>Konark Sun Temple</b> built by <b>Narasimhadeva I</b> of the Eastern Gangas."},{"i":193,"t":"Jatavarman Sundara Pandya","d":"1251 to 1268 CE","g":"","y":1251,"e":8,"s":["kingdoms"],"b":"<b>Jatavarman Sundara Pandya</b> (Pandya revival); later resurgence of the Pandyas."},{"i":194,"t":"Balban","d":"1266 to 1287 CE","g":"Balban","y":1266,"e":8,"s":[],"b":"<b>Balban</b>: strong centralization, theory of kingship, defends against Mongols."},{"i":195,"t":"Maravarman Kulasekhara I","d":"1268 to 1310 CE","g":"","y":1268,"e":8,"s":["kingdoms"],"b":"<b>Maravarman Kulasekhara I</b> (Pandya)."},{"i":196,"t":"Rajendra III","d":"c. 1279 CE","g":"","y":1279,"e":8,"s":["kingdoms"],"b":"End of the Imperial Cholas (c. 848 to 1279 CE); <b>Rajendra III</b> (last, to c. 1279); decline due to Pandyan resurgence (Jatavarman Sundara Pandya). Other late Cholas: <b>Kulottunga III</b> and <b>Rajaraja III</b>."},{"i":197,"t":"Kaiqubad","d":"1287 to 1290 CE","g":"","y":1287,"e":8,"s":["kingdoms"],"b":"<b>Kaiqubad</b> (1287 to 1290), <b>Kayumars</b> (1290). End of the Mamluk dynasty."},{"i":198,"t":"Marco Polo","d":"c. 1288 to 1293 CE","g":"Marco Polo","y":1288,"e":8,"s":["kingdoms","visitors"],"b":"<b>Marco Polo</b> (Venetian) visits Pandya and Chola coasts (c. 1288 and 1293), and describes Mutfili (Kakatiya kingdom) diamonds."},{"i":199,"t":"Dnyaneshwar’s","d":"1290 CE","g":"","y":1290,"e":8,"s":["kingdoms"],"b":"<b>Dnyaneshwar’s</b> <i>Dnyaneshwari</i> (1290). <b>Khalji dynasty (1290 to 1320)</b> begins with <b>Jalaluddin Khalji</b> (1290 to 1296)."},{"i":200,"t":"Alauddin Khalji","d":"1296 to 1316 CE","g":"Alauddin Khalji","y":1296,"e":8,"s":["languages"],"b":"Jalaluddin is murdered by nephew <b>Alauddin Khalji</b>. Reforms: price controls (market regulation), permanent army, land revenue measured and taken directly (<i>kharaj</i>). <b>Amir Khusrau</b> (poet), <b>Alai Darwaza</b>, Siri fort. The Yadava king <b>Ramachandra</b> of Devagiri submits to Alauddin Khalji (1296)."},{"i":201,"t":"Mongol invasions","d":"1297 to 1306 CE","g":"","y":1297,"e":8,"s":["wars"],"b":"Alauddin repulses repeated <b>Mongol invasions</b>."},{"i":202,"t":"Gujarat","d":"1299 CE","g":"","y":1299,"e":8,"s":["wars"],"b":"Alauddin conquers <b>Gujarat</b>."},{"i":203,"t":"Ranthambore","d":"1301 CE","g":"","y":1301,"e":8,"s":["wars"],"b":"Alauddin conquers <b>Ranthambore</b>."},{"i":204,"t":"Chittor","d":"1303 CE","g":"","y":1303,"e":8,"s":["wars"],"b":"Alauddin conquers <b>Chittor</b> (Mewar wars: Chittor sieges 1303, 1535, 1568)."},{"i":205,"t":"Malik Kafur","d":"1307 to 1311 CE","g":"","y":1307,"e":8,"s":["places","wars"],"b":"Alauddin sends <b>Malik Kafur</b> south (Devagiri, Warangal, Dwarasamudra, Madurai). War list: Alauddin’s southern conquests (1307 to 1311)."},{"i":206,"t":"Qutbuddin Mubarak Shah","d":"1316 to 1320 CE","g":"","y":1316,"e":8,"s":["places"],"b":"<b>Qutbuddin Mubarak Shah</b> (1316 to 1320); <b>Khusrau Khan</b> (1320)."},{"i":207,"t":"1317 CE","d":"1317 CE","g":"","y":1317,"e":8,"s":[],"b":"Yadavas of Devagiri fully annexed."},{"i":208,"t":"Ghiyasuddin Tughlaq","d":"1320 to 1414 CE","g":"Tughlaq dynasty","y":1320,"e":8,"s":["kingdoms","architecture"],"b":"<b>Ghiyasuddin Tughlaq</b> (1320 to 1325) founds Tughlaqabad. Tomb of Ghiyasuddin (14th to 15th century)."},{"i":209,"t":"1323 CE","d":"1323 CE","g":"","y":1323,"e":8,"s":[],"b":"End of the Kakatiyas (c. 1163 to 1323 CE)."},{"i":210,"t":"Muhammad bin Tughlaq","d":"1325 to 1351 CE","g":"Muhammad bin Tughlaq","y":1325,"e":8,"s":["kingdoms","wars","architecture","rulers"],"b":"<b>Muhammad bin Tughlaq</b>: token currency (copper/brass coins) failed; Khurasan expedition; Doab taxation and famine; revolts, including the creation of the <b>Bahmani Sultanate (1347)</b> and <b>Vijayanagara (1336)</b>."},{"i":211,"t":"capital from Delhi to Daulatabad","d":"1327 CE","g":"","y":1327,"e":8,"s":[],"b":"Muhammad bin Tughlaq shifts the <b>capital from Delhi to Daulatabad</b>."},{"i":212,"t":"Ibn Battuta","d":"1333 to 1347 CE","g":"Ibn Battuta","y":1333,"e":8,"s":["visitors"],"b":"<b>Ibn Battuta</b> (Moroccan traveler) serves as chief judge (qazi) in Delhi under Muhammad bin Tughlaq (1334 to 1341); later visits Malabar, Maldives, and Bengal. Writes the <i>Rihla</i>."},{"i":213,"t":"Vijayanagara Empire","d":"1336 to c. 1646 CE","g":"Vijayanagara Empire","y":1336,"e":8,"s":["places","kingdoms","architecture"],"b":"<b>Vijayanagara Empire</b> founded by <b>Harihara I and Bukka Raya I</b> (Sangama brothers) with guidance of the sage <b>Vidyaranya</b>; capital <b>Hampi</b>. Four dynasties: Sangama, Saluva, Tuluva, Aravidu. <b>Sangama (1336 to 1485):</b> Harihara I, Bukka I, Harihara II, Deva Raya I. Hampi monuments (14th to 15th century: Virupaksha, Vitthala with the stone chariot, Hazara Rama)."},{"i":214,"t":"Madhava of Sangamagrama","d":"c. 1340 to 1425 CE","g":"","y":1340,"e":8,"s":["kingdoms","science"],"b":"<b>Madhava of Sangamagrama</b> (Kerala School of Astronomy and Mathematics, 14th to 16th century): infinite series for sine, cosine, arctangent and pi."},{"i":215,"t":"1343 CE","d":"1343 CE","g":"","y":1343,"e":8,"s":[],"b":"End of the Hoysalas (c. 1026 to 1343 CE)."},{"i":216,"t":"Bahmani Sultanate","d":"1347 to 1527 CE","g":"Bahmani Sultanate","y":1347,"e":8,"s":["kingdoms","rulers"],"b":"<b>Bahmani Sultanate</b> founded by <b>Alauddin Bahman Shah (Hasan Gangu)</b>, capital Gulbarga then Bidar. <b>Muhammad Shah I</b>, <b>Firuz Shah Bahmani</b>."},{"i":217,"t":"Firuz Shah Tughlaq","d":"1351 to 1388 CE","g":"Firuz Shah Tughlaq","y":1351,"e":8,"s":["architecture","languages","leaders"],"b":"<b>Firuz Shah Tughlaq</b>: canals, Firozabad, Ashokan pillars moved to Delhi, introduced <i>jizya</i> on Brahmins, charitable bureau. Firoz Shah Kotla (14th to 15th century)."},{"i":218,"t":"Ghiyasuddin II","d":"1388 to 1395 CE","g":"","y":1388,"e":8,"s":[],"b":"<b>Ghiyasuddin II</b> (1388 to 1389), <b>Abu Bakr</b> (1389 to 1390), <b>Nasiruddin Muhammad</b> (1390 to 1394), <b>Humayun Khan</b> (1394 to 1395)."},{"i":219,"t":"Nasiruddin Mahmud","d":"1395 to 1412 CE","g":"","y":1395,"e":8,"s":[],"b":"<b>Nasiruddin Mahmud</b> (Tughlaq)."},{"i":220,"t":"Timur (Tamerlane)","d":"1398 CE","g":"Timur","y":1398,"e":8,"s":["wars","leaders"],"b":"<b>Timur (Tamerlane)</b> sacks Delhi, carrying off great wealth and many artisans. War list: Timur’s invasion (1398). <b>Kabir</b> (c. 1398 to 1518, traditional dates): <i>dohas</i>, rejection of ritualism and caste."},{"i":221,"t":"Wodeyars of Mysore","d":"1399 CE","g":"","y":1399,"e":8,"s":[],"b":"<b>Wodeyars of Mysore</b> (1399 to 1947, with an interregnum under Hyder and Tipu 1761 to 1799)."},{"i":222,"t":"Ramananda","d":"c. 14th to 15th century","g":"Bhakti","y":1450,"e":8,"s":["places","kingdoms","religion","languages","leaders"],"b":"<b>Ramananda</b> (Varanasi) preaches in vernacular; disciples include <b>Kabir</b>, <b>Ravidas</b>, <b>Sena</b>, <b>Pipa</b>. Literature (13th to 14th century): <b>Amir Khusrau</b> (Persian, Hindavi), <b>Dnyaneshwar</b> (Marathi), <b>Namdev</b>, <b>Jayadeva</b>, <b>Vidyapati</b> (Maithili), <b>Chandidas</b> (Bengali). Architecture: <b>Tughlaqabad</b>, <b>Atala Masjid</b> (Jaunpur), <b>Mandu</b> (Jahaz Mahal, Hoshang Shah’s tomb)."},{"i":223,"t":"Sayyid dynasty","d":"1414 to 1451 CE","g":"Sayyid dynasty","y":1414,"e":8,"s":["kingdoms"],"b":"<b>Sayyid dynasty:</b> <b>Khizr Khan</b> (1414 to 1421), a vassal of Timur; <b>Mubarak Shah</b> (1421 to 1434), <b>Muhammad Shah</b> (1434 to 1445), <b>Alauddin Alam Shah</b> (1445 to 1451)."},{"i":224,"t":"Niccolo de Conti","d":"1420 CE","g":"","y":1420,"e":8,"s":["kingdoms","architecture"],"b":"<b>Niccolo de Conti</b> (Venetian) visits Vijayanagara. <b>Zain-ul-Abidin</b> (Budshah) of Kashmir (c. 1420 to 1470)."},{"i":225,"t":"Deva Raya II","d":"1424 to 1446 CE","g":"","y":1424,"e":8,"s":["kingdoms","architecture"],"b":"<b>Deva Raya II</b> (Vijayanagara, Sangama)."},{"i":226,"t":"Gajapatis of Odisha","d":"1434 to 1541 CE","g":"Gajapatis of Odisha","y":1434,"e":8,"s":[],"b":"<b>Gajapatis of Odisha</b>: Kapilendra, Purushottama, Prataparudra."},{"i":227,"t":"Ranakpur","d":"1439 CE","g":"","y":1439,"e":8,"s":["religion","architecture"],"b":"<b>Ranakpur</b> Jain temple."},{"i":228,"t":"Chittorgarh Vijay Stambh","d":"c. 1440s CE","g":"","y":1440,"e":8,"s":[],"b":"<b>Chittorgarh Vijay Stambh</b> (Rana Kumbha)."},{"i":229,"t":"Abdur Razzaq","d":"1442 CE","g":"","y":1442,"e":8,"s":["kingdoms","architecture","languages","visitors"],"b":"<b>Abdur Razzaq</b> (Persian ambassador) at Vijayanagara under Deva Raya II."},{"i":230,"t":"Lodi dynasty","d":"1451 to 1526 CE","g":"Lodi dynasty","y":1451,"e":8,"s":["kingdoms"],"b":"<b>Lodi dynasty:</b> <b>Bahlul Lodi</b> (1451 to 1489)."},{"i":231,"t":"Mahmud Gawan","d":"1466 to 1481 CE","g":"Mahmud Gawan","y":1466,"e":8,"s":["kingdoms","rulers"],"b":"Bahmani wazir <b>Mahmud Gawan</b> (reforms; executed). <b>Afanasy Nikitin</b> (Russian merchant) travels in the Bahmani Sultanate (1466 to 1472)."},{"i":232,"t":"Guru Nanak","d":"1469 to 1539 CE","g":"Guru Nanak","y":1469,"e":8,"s":["religion","leaders"],"b":"<b>Guru Nanak</b> founds <b>Sikhism</b>, born at Talwandi (Nankana Sahib), teaches <i>Ik Onkar</i>, <i>langar</i>, <i>sangat</i>, <i>pangat</i>. First of the ten Sikh Gurus; the Guru Granth Sahib tradition begins here."},{"i":233,"t":"Saluva","d":"1485 to 1505 CE","g":"Saluva dynasty","y":1485,"e":8,"s":["kingdoms","architecture"],"b":"<b>Saluva</b> dynasty (Vijayanagara): Narasimha Saluva."},{"i":234,"t":"Chaitanya Mahaprabhu","d":"1486 to 1534 CE","g":"Chaitanya Mahaprabhu","y":1486,"e":8,"s":["leaders"],"b":"<b>Chaitanya Mahaprabhu</b> (Bengal): Gaudiya Vaishnavism, <i>sankirtan</i>."},{"i":235,"t":"Sikandar Lodi","d":"1489 to 1517 CE","g":"","y":1489,"e":8,"s":[],"b":"<b>Sikandar Lodi</b> (founded Agra, 1504)."},{"i":236,"t":"Ahmadnagar (Nizam Shahi)","d":"1490 to 1528 CE","g":"Bahmani splits","y":1490,"e":8,"s":["places","kingdoms","rulers"],"b":"The Bahmani Sultanate splits into five: <b>Ahmadnagar (Nizam Shahi)</b>, <b>Bijapur (Adil Shahi)</b>, <b>Golconda (Qutb Shahi)</b>, <b>Berar (Imad Shahi)</b>, <b>Bidar (Barid Shahi)</b>."},{"i":237,"t":"Vasco da Gama","d":"1498 CE","g":"Vasco da Gama","y":1498,"e":8,"s":[],"b":"<b>Vasco da Gama</b> reaches <b>Calicut</b> (Kerala) via the Cape of Good Hope; Zamorin of Calicut."},{"i":238,"t":"Kabir","d":"c. 15th to 16th century","g":"Literature","y":1550,"e":8,"s":["languages","leaders"],"b":"<b>Kabir</b>, <b>Nanak</b>, <b>Surdas</b> (Braj), <b>Mirabai</b>, <b>Tulsidas</b> (Awadhi), <b>Shankaradeva</b> (Assamese), <b>Chaitanya’s</b> followers (Bengali <i>Chaitanya Charitamrita</i>), <b>Eknath</b>, <b>Allasani Peddana</b>."},{"i":239,"t":"Nilakantha Somayaji","d":"1501 CE","g":"","y":1501,"e":8,"s":[],"b":"<b>Nilakantha Somayaji</b> (<i>Tantrasangraha</i>, 1501)."},{"i":240,"t":"Sikandar Lodi","d":"1504 CE","g":"","y":1504,"e":8,"s":[],"b":"<b>Sikandar Lodi</b> founds Agra."},{"i":241,"t":"Tuluva","d":"1505 to 1570 CE","g":"Tuluva dynasty","y":1505,"e":8,"s":["kingdoms","architecture","rulers"],"b":"<b>Tuluva</b> (Vijayanagara): Vira Narasimha, <b>Krishnadevaraya</b> (1509 to 1529), Achyuta Raya, Sadashiva Raya (<b>Rama Raya</b> as regent). <b>Francisco de Almeida</b> (first Viceroy of the Portuguese, 1505; “blue water policy”)."},{"i":242,"t":"Portuguese","d":"1505 to 1661 CE","g":"Portuguese in India","y":1505,"e":8,"s":["rulers"],"b":"<b>Portuguese:</b> <b>Francisco de Almeida</b> (first Viceroy, 1505; “blue water policy”); <b>Afonso de Albuquerque</b> captures <b>Goa (1510)</b>; Cochin, Diu, Daman, Bassein (Vasai), Bombay (gifted to England 1661). Brought the printing press (Goa, 1556), tobacco, chilli, potato, maize, pineapple, and Inquisition (Goa, 1560). Goa was liberated in <b>1961</b>."},{"i":243,"t":"Krishnadevaraya","d":"1509 to 1529 CE","g":"Krishnadevaraya","y":1509,"e":8,"s":["kingdoms","wars","architecture","languages","rulers"],"b":"<b>Krishnadevaraya</b>, greatest ruler of Vijayanagara: Telugu work <i>Amuktamalyada</i>; court poets, the <i>Ashtadiggajas</i> (e.g. Allasani Peddana, Tenali Rama traditionally); wars against Bahmani successors, Gajapatis of Odisha, and relations with the Portuguese (Domingo Paes, Duarte Barbosa visited)."},{"i":244,"t":"Battle of Diu","d":"1509 CE","g":"","y":1509,"e":8,"s":["wars"],"b":"<b>Battle of Diu</b> against a combined Mamluk and Gujarat fleet (Portuguese victory)."},{"i":245,"t":"Afonso de Albuquerque","d":"1510 CE","g":"","y":1510,"e":8,"s":[],"b":"<b>Afonso de Albuquerque</b> captures <b>Goa</b>."},{"i":246,"t":"Duarte Barbosa","d":"1515 to 1522 CE","g":"","y":1515,"e":8,"s":["places","kingdoms","architecture"],"b":"<b>Duarte Barbosa</b>, <b>Domingo Paes</b> (c. 1520; describes Hampi), <b>Fernao Nuniz</b> (c. 1535) write of Vijayanagara."},{"i":247,"t":"Ibrahim Lodi","d":"1517 to 1526 CE","g":"","y":1517,"e":8,"s":[],"b":"<b>Ibrahim Lodi</b>."},{"i":248,"t":"First Battle of Panipat","d":"1526 CE","g":"First Battle of Panipat","y":1526,"e":9,"s":["kingdoms","wars"],"b":"<b>First Battle of Panipat:</b> <b>Babur</b> (Timurid prince of Fergana, descendant of Timur and Genghis) defeats Ibrahim Lodi using artillery and cavalry tactics (<i>tulughma</i>); founds Mughal rule. Ibrahim Lodi’s Lodi dynasty (1451 to 1526) ends and the Delhi Sultanate ends. Babur wrote the <i>Baburnama</i>. <b>Era overview: 1526 to 1707 (core)</b> is the Mughal Empire, with Marathas, Sikhs, Ahoms as rivals. Mughal emperor list begins: <b>Babur</b> (1526 to 1530)."},{"i":249,"t":"Battle of Khanwa","d":"1527 CE","g":"Battle of Khanwa","y":1527,"e":9,"s":["wars"],"b":"<b>Battle of Khanwa:</b> Babur defeats <b>Rana Sanga</b> of Mewar. (Mewar wars.)"},{"i":250,"t":"Chanderi","d":"1528 CE","g":"","y":1528,"e":9,"s":[],"b":"Babur’s victory at <b>Chanderi</b>."},{"i":251,"t":"Ghaghra","d":"1529 CE","g":"","y":1529,"e":9,"s":[],"b":"Babur’s victory at <b>Ghaghra</b> over Afghans and Bengal."},{"i":252,"t":"Humayun","d":"1530 to 1540 and 1555 to 1556 CE","g":"Humayun","y":1530,"e":9,"s":["kingdoms","rulers"],"b":"<b>Humayun</b> loses to <b>Sher Shah Suri</b> at <b>Chausa (1539)</b> and <b>Kannauj (Bilgram) (1540)</b>; exile in Persia. Mughal ruler list: Humayun (1530 to 1540; 1555 to 1556)."},{"i":253,"t":"Jyeshthadeva","d":"c. 1530 CE","g":"","y":1530,"e":9,"s":["science"],"b":"<b>Jyeshthadeva</b> (<i>Yuktibhasha</i>, in Malayalam), Kerala School of Astronomy and Mathematics."},{"i":254,"t":"Fernao Nuniz","d":"1535 CE","g":"","y":1535,"e":9,"s":["kingdoms","wars","architecture"],"b":"Chittor siege (Mewar wars: Chittor sieges 1303, 1535, 1568). <b>Fernao Nuniz</b> writes of Vijayanagara (c. 1535)."},{"i":255,"t":"Chausa","d":"1539 CE","g":"","y":1539,"e":9,"s":["wars"],"b":"Battle of <b>Chausa</b>: Humayun loses to Sher Shah Suri."},{"i":256,"t":"Kannauj (Bilgram)","d":"1540 CE","g":"","y":1540,"e":9,"s":["wars"],"b":"Battle of <b>Kannauj (Bilgram)</b>: Humayun again loses to Sher Shah Suri. <b>Malik Muhammad Jayasi</b> (<i>Padmavat</i>, 1540)."},{"i":257,"t":"Sher Shah Suri","d":"1540 to 1555 CE","g":"Sur Empire","y":1540,"e":9,"s":["kingdoms","architecture"],"b":"<b>Sher Shah Suri</b> introduces the <i>rupiya</i> silver coin, revenue system (measurement, <i>patta</i> and <i>qabuliyat</i>), the <b>Grand Trunk Road</b> rebuilt, sarais, postal system, Rohtas fort; mausoleum at <b>Sasaram</b> (<b>Sher Shah’s Tomb</b>, 16th century); <b>Purana Qila</b>. Successors weaker."},{"i":258,"t":"1541 CE","d":"1541 CE","g":"","y":1541,"e":9,"s":[],"b":"End of the Gajapatis of Odisha (1434 to 1541)."},{"i":259,"t":"St. Francis Xavier","d":"1542 CE","g":"","y":1542,"e":9,"s":[],"b":"<b>St. Francis Xavier</b> arrives in Goa."},{"i":260,"t":"Mughal","d":"16th to 17th century","g":"Mughal science and engineering","y":1650,"e":9,"s":["kingdoms","science"],"b":"<b>Mughal</b> engineering: gun-casting (<b>Fathullah Shirazi</b> multi-barrel guns), seamless celestial globes (Lahore, <b>Ali Kashmiri</b>), the <b>Zamindar</b> surveying systems; improvements in Kashmir shawl weaving, muslin of Dhaka, and shipbuilding at Surat and Bombay (the <b>Wadia</b> family built ships from 1736). Also <b>Tipu’s</b> iron-cased <b>Mysorean rockets</b> (later)."},{"i":261,"t":"Meenakshi Temple","d":"16th to 17th century","g":"Architecture","y":1650,"e":9,"s":["places","architecture"],"b":"<b>Meenakshi Temple</b>, Madurai (rebuilt by Nayakas, 16th to 17th century)."},{"i":262,"t":"Angad","d":"1552 to 1574 CE","g":"Guru Amar Das","y":1552,"e":9,"s":["religion"],"b":"Second to third Sikh Gurus: <b>Angad</b> (1539 to 1552), <b>Amar Das</b> (1552 to 1574)."},{"i":263,"t":"1555 CE","d":"1555 CE","g":"","y":1555,"e":9,"s":["languages"],"b":"Humayun returns with Persian help and recaptures Delhi."},{"i":264,"t":"Second Battle of Panipat","d":"1556 CE","g":"Second Battle of Panipat","y":1556,"e":9,"s":["wars","rulers"],"b":"<b>Second Battle of Panipat:</b> <b>Akbar</b> (age 13, regent <b>Bairam Khan</b>) defeats <b>Hemu (Hemchandra Vikramaditya)</b>. Akbar’s reign (1556 to 1605) begins."},{"i":265,"t":"Printing","d":"1556 CE","g":"Printing","y":1556,"e":9,"s":[],"b":"First printing press in Goa."},{"i":266,"t":"Mansabdari system","d":"1556 to 1605 CE","g":"Akbar: policies, court and culture","y":1556,"e":9,"s":["places","kingdoms"],"b":"Akbar’s other conquests: Ranthambore, Sindh, Orissa, Khandesh. Policies: Rajput alliances and marriages; <b>Mansabdari system</b> (Todar Mal’s revenue system: <b>Zabt/Dahsala</b>). Capital at <b>Fatehpur Sikri</b> then Lahore and Agra. <b>Navaratnas:</b> Birbal, Todar Mal, Tansen, Abul Fazl (<i>Akbarnama</i>, <i>Ain-i-Akbari</i>), Faizi, Man Singh, Abdur Rahim Khan-i-Khanan, Mulla Do-Piyaza, Fakir Aziao-Din. Art: Mughal miniature (Hamzanama), translation of Mahabharata (<i>Razmnama</i>), <b>Humayun’s Tomb</b> and Buland Darwaza. Also <b>Agra Fort</b>, <b>Akbar’s Tomb</b> (Sikandra), <b>Amber Fort</b> (Jaipur), <b>Golconda Fort</b> (16th century)."},{"i":267,"t":"1560 CE","d":"1560 CE","g":"","y":1560,"e":9,"s":[],"b":"The Inquisition at Goa."},{"i":268,"t":"Malwa","d":"1561 CE","g":"","y":1561,"e":9,"s":["wars"],"b":"Akbar conquers <b>Malwa</b>."},{"i":269,"t":"Gondwana","d":"1564 CE","g":"","y":1564,"e":9,"s":["wars"],"b":"Akbar conquers <b>Gondwana</b> (Rani Durgavati). Abolishes <i>jizya</i> (1564) and pilgrim tax."},{"i":270,"t":"Battle of Talikota (Rakshasa-Tangadi)","d":"1565 CE","g":"Battle of Talikota","y":1565,"e":9,"s":["places","kingdoms","wars","rulers"],"b":"<b>Battle of Talikota (Rakshasa-Tangadi):</b> the Deccan Sultanates’ alliance defeats <b>Rama Raya</b>; Hampi sacked. Remnant moves to Penukonda, Chandragiri."},{"i":271,"t":"Chittor","d":"1568 CE","g":"","y":1568,"e":9,"s":["wars"],"b":"Akbar conquers <b>Chittor</b> (Jaimal and Patta); Chittor sieges. <b>Paradesi Synagogue</b> at Cochin (1568). Also Ranthambore."},{"i":272,"t":"Humayun’s Tomb","d":"1570 CE","g":"","y":1570,"e":9,"s":["kingdoms","architecture","rulers"],"b":"<b>Humayun’s Tomb</b> (Delhi). <b>Aravidu dynasty (1570 to c. 1646)</b> of Vijayanagara begins: Tirumala, Sriranga I, <b>Venkata II</b>, last rulers at Vellore and Chandragiri."},{"i":273,"t":"Fatehpur Sikri","d":"1571 to 1585 CE","g":"","y":1571,"e":9,"s":["places"],"b":"<b>Fatehpur Sikri</b> (Buland Darwaza, Jama Masjid, Panch Mahal, Diwan-i-Khas). Capital at Fatehpur Sikri, then Lahore and Agra."},{"i":274,"t":"Gujarat","d":"1572 to 1573 CE","g":"","y":1572,"e":9,"s":["wars"],"b":"Akbar conquers <b>Gujarat</b>."},{"i":275,"t":"Ram Das","d":"1574 to 1581 CE","g":"Guru Ram Das","y":1574,"e":9,"s":[],"b":"<b>Ram Das</b> (Amritsar). <b>Tulsidas</b> (<i>Ramcharitmanas</i>, c. 1574)."},{"i":276,"t":"Ibadat Khana","d":"1575 CE","g":"","y":1575,"e":9,"s":["places"],"b":"<b>Ibadat Khana</b> (Fatehpur Sikri)."},{"i":277,"t":"Bengal","d":"1576 CE","g":"","y":1576,"e":9,"s":["wars"],"b":"Akbar conquers <b>Bengal</b>. <b>Battle of Haldighati:</b> Rana Pratap vs. Man Singh."},{"i":278,"t":"Mahzar","d":"1579 CE","g":"","y":1579,"e":9,"s":[],"b":"<b>Mahzar</b>."},{"i":279,"t":"Jesuits at Akbar’s court","d":"1580 CE","g":"","y":1580,"e":9,"s":[],"b":"<b>Jesuits at Akbar’s court</b>."},{"i":280,"t":"Arjan","d":"1581 to 1606 CE","g":"Guru Arjan","y":1581,"e":9,"s":["religion"],"b":"<b>Arjan</b> (Sikh Guru)."},{"i":281,"t":"Din-i-Ilahi","d":"1582 CE","g":"","y":1582,"e":9,"s":[],"b":"<b>Din-i-Ilahi</b>; <i>Sulh-i-kul</i> (universal peace)."},{"i":282,"t":"Ralph Fitch","d":"1583 to 1591 CE","g":"","y":1583,"e":9,"s":[],"b":"<b>Ralph Fitch</b> (English) travels in India."},{"i":283,"t":"Kashmir","d":"1586 CE","g":"","y":1586,"e":9,"s":["wars"],"b":"Akbar conquers <b>Kashmir</b>."},{"i":284,"t":"Charminar","d":"1591 CE","g":"","y":1591,"e":9,"s":["architecture"],"b":"<b>Charminar</b> (Hyderabad)."},{"i":285,"t":"1595 to 1600 CE","d":"1595 to 1600 CE","g":"","y":1595,"e":9,"s":[],"b":"Ahmadnagar partly (Chand Bibi defended, 1595 to 1600)."},{"i":286,"t":"East India Company","d":"1600 CE","g":"East India Company","y":1600,"e":9,"s":[],"b":"<b>East India Company</b> chartered (31 December 1600); Charter of the East India Company."},{"i":287,"t":"Ralph Fitch","d":"17th century","g":"Travellers","y":1650,"e":9,"s":["visitors"],"b":"<b>Ralph Fitch</b> (1583 to 1591, English), <b>William Hawkins</b>, <b>Thomas Roe</b>, <b>Peter Mundy</b>, <b>Tavernier</b> (French jeweller; Diamonds), <b>Francois Bernier</b> (French physician; Dara Shikoh’s circle; 1656 to 1668), <b>Niccolao Manucci</b> (Venetian; <i>Storia do Mogor</i>), <b>Jean de Thevenot</b>, <b>Francesco Pelsaert</b> (Dutch; Agra), <b>Peter Della Valle</b>."},{"i":288,"t":"Tukaram","d":"17th to 18th century","g":"Literature and music","y":1750,"e":9,"s":["languages"],"b":"<b>Tukaram</b>, <b>Ramdas</b>, <b>Bhushan</b>, <b>Bihari</b>, <b>Keshavdas</b>, <b>Ghananand</b>; <b>Urdu</b> poets <b>Wali Dakhani</b>, <b>Mir Taqi Mir</b>, <b>Sauda</b>, <b>Dard</b>; <b>Tyagaraja</b>, <b>Muthuswami Dikshitar</b>, <b>Shyama Shastri</b> (Carnatic music trinity, 18th to 19th century)."},{"i":289,"t":"Architecture","d":"16th to 18th century","g":"Culture under the Mughals","y":1750,"e":9,"s":["places","kingdoms","architecture","languages"],"b":"<b>Architecture:</b> Humayun’s Tomb, Fatehpur Sikri, Agra Fort, Taj Mahal, Red Fort, Jama Masjid, Shalimar Gardens (Lahore, Srinagar), Lahore Fort, Badshahi Mosque (Aurangzeb). <b>Language and literature:</b> Persian; Urdu emerges as a syncretic language; <b>Tulsidas</b>, <b>Keshavdas</b>, <b>Bihari</b>; <b>Rahim</b>; <b>Mirza Ghalib</b>, <b>Mir Taqi Mir</b> (18th to 19th century). <b>Music:</b> <b>Tansen</b>, Hindustani classical music, <i>dhrupad</i>, later <i>khayal</i>. Painting: Mughal, <b>Rajput</b>, <b>Pahari</b>, Deccani schools. <b>Kathak</b> evolves. <b>Religion:</b> Naqshbandi revival (<b>Ahmad Sirhindi</b>), <b>Shah Waliullah</b> (1703 to 1762) of Delhi; <b>Sant tradition</b> (Dadu, Malukdas, Tukaram); <b>Ramdas</b> (<i>Dasbodh</i>, Shivaji’s guru). <b>Vaishnava</b> and <b>Shaiva</b> festivals; <b>Kumbh</b> mela traditions."},{"i":290,"t":"English","d":"17th century","g":"other European companies","y":1650,"e":9,"s":[],"b":"<b>English:</b> <b>East India Company</b>; Hawkins at Surat (1608); Roe (1615); Surat (1612); Madras (1639); Bombay (1668); Calcutta (1690); 1717 farman. <b>French:</b> <b>French East India Company</b> (1664); Pondicherry (1674, Francois Martin), Chandernagore, Mahe, Karaikal, Yanam. <b>Danes and Swedes:</b> Tranquebar (Tharangambadi) and Serampore, with minimal impact. <b>Dutch:</b> defeated by Travancore at <b>Colachel (1741)</b> and by British at <b>Bedara (1759)</b>. <b>Sikh Misls</b> later."},{"i":291,"t":"Asirgarh","d":"1601 CE","g":"","y":1601,"e":9,"s":[],"b":"Akbar takes <b>Asirgarh</b>."},{"i":292,"t":"Dutch East India Company (VOC)","d":"1602 CE","g":"","y":1602,"e":9,"s":[],"b":"<b>Dutch East India Company (VOC)</b> arrives; factories at Masulipatnam, Pulicat, Surat, Chinsura, Cochin (took from Portuguese 1663)."},{"i":293,"t":"Arjan","d":"1604 CE","g":"","y":1604,"e":9,"s":[],"b":"<b>Arjan</b> compiles the <i>Adi Granth</i> (<b>Guru Granth Sahib</b> compiled 1604); built <b>Harmandir Sahib</b> (consecrated 1604)."},{"i":294,"t":"Jahangir","d":"1605 to 1627 CE","g":"Jahangir","y":1605,"e":9,"s":["architecture"],"b":"<b>Jahangir</b>: <b>Nur Jahan</b> (wife) holds power; <b>Chain of Justice</b>; painting flourishes (Ustad Mansur, Bishandas). <b>Malik Ambar</b> of Ahmadnagar resists. <b>Jahangir’s Tomb</b>."},{"i":295,"t":"Guru Arjan Dev","d":"1606 CE","g":"","y":1606,"e":9,"s":["kingdoms","religion"],"b":"<b>Guru Arjan Dev</b> executed (martyred 1606); <b>Akal Takht</b> (1606). <b>Hargobind</b> (1606 to 1644; Miri-Piri). Mughal-Sikh conflicts (1606 to 1716)."},{"i":296,"t":"Captain William Hawkins","d":"1608 CE","g":"","y":1608,"e":9,"s":[],"b":"<b>Captain William Hawkins</b> at Surat (1608)."},{"i":297,"t":"Surat","d":"1612 CE","g":"","y":1612,"e":9,"s":[],"b":"<b>Surat</b> factory after Swally (English)."},{"i":298,"t":"Sir Thomas Roe’s","d":"1613 to 1615 CE","g":"","y":1613,"e":9,"s":[],"b":"Trade rights and <b>Sir Thomas Roe’s</b> embassy (1615)."},{"i":299,"t":"Sir Thomas Roe","d":"1615 CE","g":"","y":1615,"e":9,"s":["kingdoms","wars"],"b":"<b>Sir Thomas Roe</b> from England; Mewar submits to Jahangir. Ahom-Mughal wars begin (1615 to 1682)."},{"i":300,"t":"Shah Jahan","d":"1628 to 1658 CE","g":"Shah Jahan","y":1628,"e":9,"s":["wars","architecture"],"b":"<b>Shah Jahan</b>: Golden age of architecture; Peacock Throne; <b>Deccan</b> wars. <b>Itmad-ud-Daulah’s Tomb</b> (1628)."},{"i":301,"t":"Shivaji Bhonsle","d":"1630 to 1680 CE","g":"Shivaji Bhonsle","y":1630,"e":9,"s":["leaders"],"b":"<b>Shivaji Bhonsle</b>: Son of <b>Shahaji</b> and <b>Jijabai</b>. (Events listed at their dates below.) <b>Ramdas</b> (<i>Dasbodh</i>, Shivaji’s guru)."},{"i":302,"t":"Taj Mahal","d":"1632 to 1653 CE","g":"","y":1632,"e":9,"s":["places","architecture"],"b":"<b>Taj Mahal</b> (for Mumtaz Mahal; architect <b>Ustad Ahmad Lahori</b>)."},{"i":303,"t":"1633 CE","d":"1633 CE","g":"","y":1633,"e":9,"s":[],"b":"Ahmadnagar fell."},{"i":304,"t":"Madurai Thirumalai Nayak Palace","d":"1636 CE","g":"","y":1636,"e":9,"s":["places","architecture"],"b":"<b>Madurai Thirumalai Nayak Palace</b> (1636)."},{"i":305,"t":"Madras (Fort St. George, 1639)","d":"1639 CE","g":"","y":1639,"e":9,"s":["places","architecture"],"b":"<b>Madras (Fort St. George, 1639)</b>. <b>Red Fort (Lal Qila)</b> (1639 to 1648) in Shahjahanabad (Delhi)."},{"i":306,"t":"Har Rai","d":"1644 to 1661 CE","g":"","y":1644,"e":9,"s":["religion"],"b":"<b>Har Rai</b> (Sikh Guru)."},{"i":307,"t":"Shivaji","d":"1646 CE","g":"","y":1646,"e":9,"s":["leaders"],"b":"<b>Shivaji</b> captures <b>Torna</b>."},{"i":308,"t":"Jama Masjid, Delhi","d":"1650 to 1656 CE","g":"","y":1650,"e":9,"s":[],"b":"<b>Jama Masjid, Delhi</b>."},{"i":309,"t":"Gol Gumbaz","d":"1656 CE","g":"","y":1656,"e":9,"s":["visitors"],"b":"<b>Gol Gumbaz</b> (Bijapur). <b>Francois Bernier</b> (French physician; Dara Shikoh’s circle) in India (1656 to 1668)."},{"i":310,"t":"Dara Shikoh","d":"1657 to 1658 CE","g":"","y":1657,"e":9,"s":["wars","religion","architecture"],"b":"War of succession between <b>Dara Shikoh</b> and <b>Aurangzeb</b>; Shah Jahan imprisoned at Agra Fort (d. 1666). Dara’s translation of the Upanishads (<i>Sirr-i-Akbar</i>)."},{"i":311,"t":"Aurangzeb (Alamgir)","d":"1658 to 1707 CE","g":"Aurangzeb, Alamgir","y":1658,"e":9,"s":["kingdoms","wars","architecture"],"b":"<b>Aurangzeb (Alamgir)</b>: Expands empire to its greatest extent (via Bijapur, 1686, and Golconda, 1687); orders to destroy some temples; Jat, Satnami, Afghan, and <b>Maratha</b> revolts; <i>Fatwa-i-Alamgiri</i>; death at Ahmadnagar (1707). Imperial overreach and Deccan ulcer helped erode Mughal control. <b>Badshahi Mosque</b>."},{"i":312,"t":"Afzal Khan","d":"1659 CE","g":"","y":1659,"e":9,"s":["leaders"],"b":"Shivaji kills <b>Afzal Khan</b> at <b>Pratapgad</b>."},{"i":313,"t":"Bibi ka Maqbara","d":"c. 1660s CE","g":"","y":1660,"e":9,"s":["architecture"],"b":"<b>Bibi ka Maqbara</b> (Aurangabad). Moti Masjid. Raigad Fort, Pratapgad, Padmanabhapuram Palace (17th century)."},{"i":314,"t":"Bombay","d":"1661 to 1664 CE","g":"","y":1661,"e":9,"s":["religion"],"b":"<b>Bombay</b> gifted to England (1661). <b>Har Krishan</b> (Sikh Guru, 1661 to 1664)."},{"i":315,"t":"Shaista Khan","d":"1663 CE","g":"","y":1663,"e":9,"s":[],"b":"<b>Shaista Khan</b> raid. Dutch take <b>Cochin</b> from the Portuguese."},{"i":316,"t":"Surat sack","d":"1664 CE","g":"","y":1664,"e":9,"s":["leaders"],"b":"<b>Surat sack</b> by Shivaji. <b>French East India Company</b>."},{"i":317,"t":"Treaty of Purandar","d":"1665 CE","g":"","y":1665,"e":9,"s":["religion"],"b":"<b>Treaty of Purandar</b> with <b>Jai Singh I</b>. <b>Tegh Bahadur</b> (1665 to 1675; Sikh Guru)."},{"i":318,"t":"1666 CE","d":"1666 CE","g":"","y":1666,"e":9,"s":["leaders"],"b":"Shivaji’s escape from Agra. Shah Jahan dies."},{"i":319,"t":"Bombay","d":"1668 CE","g":"","y":1668,"e":9,"s":[],"b":"<b>Bombay</b> (Company; 1661 to 1668)."},{"i":320,"t":"Battle of Saraighat","d":"1671 CE","g":"","y":1671,"e":9,"s":["kingdoms","wars"],"b":"<b>Battle of Saraighat</b>: <b>Lachit Borphukan</b> (Ahoms) defeats Mughals."},{"i":321,"t":"Badshahi Mosque","d":"1673 CE","g":"","y":1673,"e":9,"s":["architecture"],"b":"<b>Badshahi Mosque</b> (Lahore)."},{"i":322,"t":"Shivaji’s coronation at Raigad","d":"1674 CE","g":"","y":1674,"e":9,"s":["religion","leaders"],"b":"<b>Shivaji’s coronation at Raigad</b>, taking the title <i>Chhatrapati</i>; <i>Ashtapradhan</i> council; navy under <b>Kanhoji Angre</b> (later). <b>Pondicherry</b> (Francois Martin) French."},{"i":323,"t":"Guru Tegh Bahadur","d":"1675 CE","g":"","y":1675,"e":9,"s":[],"b":"<b>Guru Tegh Bahadur</b> executed by Aurangzeb. <b>Gobind Singh</b> (1675 to 1708)."},{"i":324,"t":"southern expedition","d":"1676 to 1677 CE","g":"","y":1676,"e":9,"s":["leaders"],"b":"Shivaji’s <b>southern expedition</b>."},{"i":325,"t":"Rajput","d":"1679 CE","g":"","y":1679,"e":9,"s":["kingdoms","wars"],"b":"Aurangzeb reimposes <i>jizya</i>; <b>Rajput</b> revolt (Mewar and Marwar, 1679, Durgadas)."},{"i":326,"t":"Sambhaji","d":"1680 CE","g":"","y":1680,"e":9,"s":["leaders"],"b":"Shivaji dies. <b>Sambhaji</b> (1680 to 1689): captured and executed by Aurangzeb."},{"i":327,"t":"1681 to 1707 CE","d":"1681 to 1707 CE","g":"","y":1681,"e":9,"s":["kingdoms","wars"],"b":"Mughal-Maratha wars. Deccan campaign for 25 years (1682 to 1707)."},{"i":328,"t":"Bijapur","d":"1686 CE","g":"","y":1686,"e":9,"s":[],"b":"Aurangzeb takes <b>Bijapur</b>."},{"i":329,"t":"Golconda","d":"1687 CE","g":"","y":1687,"e":9,"s":[],"b":"Aurangzeb takes <b>Golconda</b>."},{"i":330,"t":"Rajaram","d":"1689 CE","g":"","y":1689,"e":9,"s":[],"b":"<b>Rajaram</b> (1689 to 1700) at Jinji; <b>Tarabai</b> leads resistance. Sambhaji executed."},{"i":331,"t":"Calcutta (Fort William, 1690; Job Charnock)","d":"1690 CE","g":"","y":1690,"e":9,"s":["architecture"],"b":"<b>Calcutta (Fort William, 1690; Job Charnock)</b>."},{"i":332,"t":"Rudra Singha","d":"1696 to 1714 CE","g":"","y":1696,"e":9,"s":["kingdoms"],"b":"<b>Rudra Singha</b> (Ahom)."},{"i":333,"t":"Guru Gobind Singh","d":"1699 CE","g":"Khalsa","y":1699,"e":9,"s":[],"b":"<b>Guru Gobind Singh</b> founds the <b>Khalsa</b> at Anandpur Sahib on <b>Baisakhi 1699</b>; the <i>Five Ks</i>; Chamkaur, Sirhind."},{"i":334,"t":"Tarabai","d":"1700 to 1707 CE","g":"","y":1700,"e":9,"s":["leaders"],"b":"<b>Tarabai</b> (regent for Shivaji II)."},{"i":335,"t":"Sikh Gurus","d":"17th to 18th century","g":"Sikh Gurus’ lineage, overview","y":1750,"e":9,"s":["religion","leaders"],"b":"<b>Sikh Gurus:</b> <b>Nanak</b> (1469 to 1539), <b>Angad</b> (1539 to 1552), <b>Amar Das</b> (1552 to 1574), <b>Ram Das</b> (1574 to 1581), <b>Arjan</b> (1581 to 1606), <b>Hargobind</b> (1606 to 1644), <b>Har Rai</b> (1644 to 1661), <b>Har Krishan</b> (1661 to 1664), <b>Tegh Bahadur</b> (1665 to 1675), <b>Gobind Singh</b> (1675 to 1708). Then <b>Guru Granth Sahib</b> as eternal Guru."},{"i":336,"t":"Jats","d":"18th to 19th century","g":"Misc. rulers and peoples","y":1850,"e":9,"s":["kingdoms","rulers"],"b":"<b>Jats</b> (Suraj Mal of Bharatpur); <b>Rohillas</b>; <b>Mahadji Scindia</b>, <b>Ahilyabai Holkar</b>, <b>Nana Phadnavis</b> (Maratha figures); <b>Maratha confederacy:</b> Scindia (Gwalior), Holkar (Indore), Gaekwad (Baroda), Bhonsle (Nagpur). Other Peshwa ministers: Moropant Pingle, Ramchandra Pant Amatya (early ministers); later titular Chhatrapatis at Satara and Kolhapur. <b>Peshwa Baji Rao II</b> pensioned off at Bithoor after 1818. Anglo-Maratha War leaders and Mysore (<b>Hyder Ali</b> and <b>Tipu Sultan</b>)."},{"i":337,"t":"Ziegenbalg","d":"1706 CE","g":"","y":1706,"e":9,"s":[],"b":"<b>Ziegenbalg</b> (Protestant mission), Tranquebar."},{"i":338,"t":"Bahadur Shah I","d":"1707 CE","g":"","y":1707,"e":9,"s":[],"b":"Aurangzeb dies at Ahmadnagar. <b>Bahadur Shah I</b> (1707 to 1712). <b>Shahu</b> (1707 to 1749) becomes Chhatrapati."},{"i":339,"t":"Guru Gobind Singh","d":"1708 CE","g":"","y":1708,"e":9,"s":[],"b":"<b>Guru Gobind Singh</b> dies; the <b>Guru Granth Sahib</b> takes final form (1708) as eternal Guru."},{"i":340,"t":"Banda Singh Bahadur","d":"1709 to 1716 CE","g":"Banda Singh Bahadur","y":1709,"e":9,"s":[],"b":"<b>Banda Singh Bahadur</b> captures Sirhind; executed in Delhi (1716)."},{"i":341,"t":"Jahandar Shah","d":"1712 to 1713 CE","g":"","y":1712,"e":9,"s":[],"b":"<b>Jahandar Shah</b>."},{"i":342,"t":"Farrukhsiyar","d":"1713 to 1719 CE","g":"Farrukhsiyar","y":1713,"e":9,"s":["rulers"],"b":"<b>Farrukhsiyar</b> (granted East India Company a <i>farman</i> in 1717, with the help of <b>William Hamilton</b>). <b>Sayyid Brothers</b> (kingmakers). <b>Balaji Vishwanath</b> (Peshwa, 1713 to 1720)."},{"i":343,"t":"Farrukhsiyar’s farman","d":"1717 CE","g":"","y":1717,"e":9,"s":[],"b":"<b>Farrukhsiyar’s farman</b> to the English Company (duty-free trade in Bengal). <b>Bengal:</b> Murshid Quli Khan (autonomous state, 1717)."},{"i":344,"t":"Rafi ud-Darajat and Rafi ud-Daulah","d":"1719 to 1748 CE","g":"Muhammad Shah Rangila","y":1719,"e":9,"s":[],"b":"<b>Rafi ud-Darajat and Rafi ud-Daulah</b> (1719). <b>Muhammad Shah “Rangila”</b> (1719 to 1748)."},{"i":345,"t":"Baji Rao I","d":"1720 to 1740 CE","g":"Baji Rao I","y":1720,"e":9,"s":["wars","rulers"],"b":"<b>Baji Rao I</b> (Peshwa; never lost a battle). <b>Jantar Mantar</b> (Jaipur, Delhi; <b>Sawai Jai Singh II</b>, 1720s to 1734)."},{"i":346,"t":"Ahom Kings (1228 to 1826)","d":"c. 1720 CE","g":"Pramatta Singha and Ahom kings","y":1720,"e":9,"s":["kingdoms"],"b":"<b>Ahom Kings (1228 to 1826):</b> Sukaphaa, Rudra Singha (1696 to 1714), <b>Pramatta Singha</b>; <b>Lachit Borphukan</b> wins Saraighat (1671)."},{"i":347,"t":"Awadh","d":"1722 CE","g":"","y":1722,"e":9,"s":[],"b":"<b>Awadh</b> (Saadat Khan) becomes autonomous."},{"i":348,"t":"Nizam-ul-Mulk Asaf Jah","d":"1724 CE","g":"","y":1724,"e":9,"s":[],"b":"<b>Nizam-ul-Mulk Asaf Jah</b> founds <b>Hyderabad</b> state (<b>Mir Qamaruddin Asaf Jah I</b>, 1724 to 1748; the Nizam line runs to <b>Mir Osman Ali Khan</b>, 1911 to 1948). <b>Jantar Mantar</b> Delhi (1724)."},{"i":349,"t":"Jaipur","d":"1727 CE","g":"","y":1727,"e":9,"s":[],"b":"<b>Jaipur</b> city."},{"i":350,"t":"Palkhed","d":"1728 CE","g":"","y":1728,"e":9,"s":[],"b":"Baji Rao I wins at <b>Palkhed</b>."},{"i":351,"t":"Marthanda Varma","d":"1729 to 1758 CE","g":"Marthanda Varma","y":1729,"e":9,"s":["religion"],"b":"<b>Marthanda Varma</b> of Travancore (and <b>Dharma Raja</b>)."},{"i":352,"t":"Shaniwar Wada","d":"1732 CE","g":"","y":1732,"e":9,"s":[],"b":"<b>Shaniwar Wada</b> (Pune)."},{"i":353,"t":"Jantar Mantar","d":"1734 CE","g":"","y":1734,"e":9,"s":[],"b":"<b>Jantar Mantar</b>, Jaipur (1734)."},{"i":354,"t":"Wadia","d":"1736 CE","g":"","y":1736,"e":9,"s":[],"b":"The <b>Wadia</b> family builds ships at Bombay (from 1736)."},{"i":355,"t":"Delhi","d":"1737 CE","g":"","y":1737,"e":9,"s":["kingdoms"],"b":"Baji Rao I’s Maratha forces reach <b>Delhi</b>."},{"i":356,"t":"Nadir Shah","d":"1739 CE","g":"","y":1739,"e":9,"s":["wars"],"b":"<b>Nadir Shah</b> of Persia wins at <b>Karnal</b>, sacks Delhi, carries off the <b>Peacock Throne</b> and the <b>Koh-i-Noor</b>. War list: Nadir Shah’s invasion (1739)."},{"i":357,"t":"Balaji Baji Rao (Nana Saheb)","d":"1740 to 1761 CE","g":"Balaji Baji Rao","y":1740,"e":9,"s":["rulers"],"b":"<b>Balaji Baji Rao (Nana Saheb)</b> (Peshwa)."},{"i":358,"t":"Marthanda Varma","d":"1741 CE","g":"","y":1741,"e":9,"s":[],"b":"<b>Marthanda Varma</b> defeats the Dutch at <b>Colachel</b>."},{"i":359,"t":"Dupleix","d":"1742 to 1754 CE","g":"","y":1742,"e":9,"s":[],"b":"<b>Dupleix</b> (French Governor) vs. <b>Robert Clive</b>."},{"i":360,"t":"First Carnatic War","d":"1746 to 1748 CE","g":"","y":1746,"e":9,"s":["wars"],"b":"<b>First Carnatic War</b> (Adyar/St. Thome). Carnatic Wars (1746 to 1763)."},{"i":361,"t":"Ahmad Shah Abdali","d":"1748 to 1767 CE","g":"","y":1748,"e":9,"s":[],"b":"<b>Ahmad Shah Abdali</b> (Durrani) invades eight or more times. <b>Ahmad Shah Bahadur</b> (1748 to 1754)."},{"i":362,"t":"Second Carnatic War","d":"1749 to 1754 CE","g":"","y":1749,"e":9,"s":["wars"],"b":"<b>Second Carnatic War</b> (Arcot, 1751). <b>Shahu</b> dies (1749)."},{"i":363,"t":"Murshidabad","d":"18th century","g":"Architecture","y":1750,"e":9,"s":["architecture"],"b":"<b>Murshidabad</b> buildings (18th century)."},{"i":364,"t":"Awadh","d":"18th century","g":"Autonomous states","y":1750,"e":9,"s":[],"b":"Autonomous states emerge: <b>Awadh</b> (Saadat Khan, 1722), <b>Bengal</b> (Murshid Quli Khan, 1717), <b>Rohilkhand</b>, <b>Mysore</b>."},{"i":365,"t":"1751 CE","d":"1751 CE","g":"","y":1751,"e":9,"s":["wars"],"b":"Arcot (Second Carnatic War)."},{"i":366,"t":"Alamgir II","d":"1754 to 1759 CE","g":"","y":1754,"e":9,"s":["architecture"],"b":"<b>Alamgir II</b>. <b>Safdarjung’s Tomb</b> (1754)."},{"i":367,"t":"Siraj ud-Daulah","d":"1756 CE","g":"","y":1756,"e":9,"s":["architecture"],"b":"<b>Siraj ud-Daulah</b> captures Fort William; the <b>“Black Hole of Calcutta”</b> incident (disputed)."},{"i":368,"t":"23 June 1757, Battle of Plassey","d":"1757 CE","g":"Battle of Plassey","y":1757,"e":10,"s":["wars"],"b":"<b>23 June 1757, Battle of Plassey:</b> <b>Robert Clive</b> defeats Siraj ud-Daulah by conspiracy with <b>Mir Jafar</b>, <b>Rai Durlabh</b>, <b>Jagat Seth</b>, and <b>Omichand</b>. Start of effective British territorial rule (1757 to 1858: East India Company rule); <b>Mir Jafar</b> installed; <b>Mir Qasim</b> replaced him (1760)."},{"i":369,"t":"Third Carnatic War","d":"1758 to 1763 CE","g":"","y":1758,"e":10,"s":["wars"],"b":"<b>Third Carnatic War</b>."},{"i":370,"t":"Shah Alam II","d":"1759 CE","g":"","y":1759,"e":10,"s":[],"b":"<b>Shah Alam II</b> (1759 to 1806). Dutch defeated by the British at <b>Bedara</b> (1759)."},{"i":371,"t":"Battle of Wandiwash","d":"1760 CE","g":"","y":1760,"e":10,"s":["wars"],"b":"<b>Battle of Wandiwash:</b> <b>Eyre Coote</b> defeats Lally. <b>Mir Qasim</b> replaces Mir Jafar."},{"i":372,"t":"Third Battle of Panipat","d":"1761 CE","g":"Third Battle of Panipat","y":1761,"e":10,"s":["kingdoms","wars","rulers"],"b":"<b>Third Battle of Panipat:</b> Abdali defeats the Maratha army under <b>Sadashivrao Bhau</b>; Maratha northern ambitions halted; <b>Peshwa Balaji Bajirao</b> dies soon after. <b>Madhavrao I</b> (Peshwa, 1761 to 1772). <b>Hyder Ali</b> (Mysore, 1761 to 1782)."},{"i":373,"t":"Shah Waliullah","d":"1762 CE","g":"","y":1762,"e":10,"s":[],"b":"<b>Shah Waliullah</b> (1703 to 1762) of Delhi dies."},{"i":374,"t":"Treaty of Paris","d":"1763 CE","g":"","y":1763,"e":10,"s":[],"b":"<b>Treaty of Paris</b> ends French political ambition. <b>Sanyasi-Fakir rebellion (1763 to 1800)</b> begins."},{"i":375,"t":"Battle of Buxar","d":"22 October 1764","g":"Battle of Buxar","y":22,"e":10,"s":["wars"],"b":"<b>Battle of Buxar:</b> Hector Munro defeats <b>Mir Qasim, Shuja-ud-Daulah (Awadh)</b>, and <b>Shah Alam II</b>. Shah Alam II loses at Buxar."},{"i":376,"t":"Treaty of Allahabad","d":"1765 CE","g":"Treaty of Allahabad","y":1765,"e":10,"s":[],"b":"<b>Treaty of Allahabad:</b> The Company receives the <b>Diwani</b> (revenue rights) of Bengal, Bihar, and Orissa; <b>dual government</b> under Clive (1765 to 1772)."},{"i":377,"t":"First Anglo-Mysore War","d":"1767 to 1769 CE","g":"","y":1767,"e":10,"s":["wars"],"b":"<b>First Anglo-Mysore War</b>. Mysore Wars (1767 to 1799)."},{"i":378,"t":"Great Bengal Famine","d":"1770 CE","g":"","y":1770,"e":10,"s":[],"b":"<b>Great Bengal Famine</b> kills perhaps a third of Bengal’s population."},{"i":379,"t":"Warren Hastings","d":"1772 to 1785 CE","g":"Warren Hastings","y":1772,"e":10,"s":["wars"],"b":"<b>Warren Hastings</b>: ends dual system; shifts capital to Calcutta. <b>Raja Ram Mohan Roy</b> (1772 to 1833): “Father of Modern India”; campaign against <b>sati</b>; supports English education. <b>Madhavrao I</b> dies (1772); <b>Narayanrao</b> (Peshwa, 1772 to 1773)."},{"i":380,"t":"Regulating Act of 1773","d":"1773 CE","g":"Regulating Act","y":1773,"e":10,"s":["rulers"],"b":"<b>Regulating Act of 1773</b> (Governor-General of Bengal). <b>Raghunathrao</b> (Peshwa, 1773 to 1774)."},{"i":381,"t":"Supreme Court at Calcutta","d":"1774 CE","g":"","y":1774,"e":10,"s":["wars","rulers"],"b":"<b>Supreme Court at Calcutta</b>. <b>Rohilla War</b>. <b>Madhavrao II</b> (Peshwa, 1774 to 1795)."},{"i":382,"t":"First Anglo-Maratha War","d":"1775 to 1782 CE","g":"","y":1775,"e":10,"s":["kingdoms","wars"],"b":"<b>First Anglo-Maratha War</b> (Treaty of Salbai, 1782)."},{"i":383,"t":"Second Anglo-Mysore War","d":"1780 CE","g":"","y":1780,"e":10,"s":["wars"],"b":"<b>Second Anglo-Mysore War</b> (1780 to 1784). <b>Hicky’s Bengal Gazette</b> (first Indian newspaper in English)."},{"i":384,"t":"1781 CE","d":"1781 CE","g":"","y":1781,"e":10,"s":[],"b":"Amending Act."},{"i":385,"t":"Treaty of Salbai","d":"1782 CE","g":"","y":1782,"e":10,"s":["kingdoms","wars","rulers"],"b":"<b>Treaty of Salbai</b> ends the First Anglo-Maratha War. <b>Tipu Sultan</b> (1782 to 1799; rockets; died at <b>Srirangapatna</b>)."},{"i":386,"t":"Pitt’s India Act","d":"1784 CE","g":"","y":1784,"e":10,"s":["wars"],"b":"<b>Pitt’s India Act</b> (Board of Control). <b>Asiatic Society</b> (1784, William Jones). <b>Lucknow Bara Imambara</b> (1784 to 1791). End of the Second Mysore War."},{"i":387,"t":"John Macpherson","d":"1785 to 1786 CE","g":"","y":1785,"e":10,"s":["rulers"],"b":"<b>John Macpherson</b> (acting Governor-General, 1785 to 1786)."},{"i":388,"t":"Cornwallis","d":"1786 to 1793 CE","g":"Cornwallis","y":1786,"e":10,"s":[],"b":"<b>Cornwallis</b>: civil service reforms; police."},{"i":389,"t":"Third Anglo-Mysore War","d":"1790 to 1792 CE","g":"","y":1790,"e":10,"s":["wars"],"b":"<b>Third Anglo-Mysore War</b>; <b>Treaty of Seringapatam (1792)</b>."},{"i":390,"t":"Permanent Settlement of Bengal","d":"1793 CE","g":"Permanent Settlement","y":1793,"e":10,"s":[],"b":"<b>Permanent Settlement of Bengal</b> with <b>zamindars</b>; <b>Charter Act</b> (1793). <b>William Carey</b> (Protestant missions), Serampore. <b>Sir John Shore</b> (1793 to 1798)."},{"i":391,"t":"1795 CE","d":"1795 CE","g":"","y":1795,"e":10,"s":["rulers"],"b":"Madhavrao II (Peshwa) ends."},{"i":392,"t":"Baji Rao II","d":"1796 to 1818 CE","g":"","y":1796,"e":10,"s":["rulers"],"b":"<b>Baji Rao II</b> (Peshwa)."},{"i":393,"t":"Wellesley","d":"1798 to 1805 CE","g":"Wellesley","y":1798,"e":10,"s":["rulers"],"b":"<b>Wellesley</b>: <b>Subsidiary Alliance</b> (Hyderabad 1798, Mysore, Awadh 1801, Peshwa 1802 at Bassein, Scindia, Bhonsle)."},{"i":394,"t":"Fourth Anglo-Mysore War","d":"1799 CE","g":"","y":1799,"e":10,"s":["wars","rulers"],"b":"<b>Fourth Anglo-Mysore War:</b> Tipu falls (Seringapatam, 1799); Mysore handed to the Wodeyars. <b>Maharaja Ranjit Singh</b> (1799 to 1839): unified Punjab with his capital at Lahore; modern army (<i>Fauj-i-Khas</i>) with European officers (Ventura, Allard); <b>Golden Temple</b> gilded. <b>Hawa Mahal</b> (1799). Sikh Empire: Ranjit Singh (1799 to 1839), Kharak Singh, Sher Singh, Duleep Singh. The <b>Sikh Misls</b> (12). After his death, civil strife."},{"i":395,"t":"Wahhabi movement","d":"19th century","g":"undated reformers and movements","y":1850,"e":10,"s":["leaders"],"b":"<b>Wahhabi movement</b> (Syed Ahmad Barelvi), <b>Faraizi</b> (Haji Shariatullah), <b>Namdhari (Kuka)</b> movement. <b>Narayana Guru</b> (Kerala; “One Caste, One Religion, One God”), <b>Ayyankali</b>; <b>Mahadev Govind Ranade</b> (Prarthana Samaj, 1867), <b>Pandita Ramabai</b>, <b>D. K. Karve</b>. <b>Henry Derozio</b> and <b>Young Bengal</b>. Tribal and peasant revolts: <b>Chuar revolt</b>; <b>Kol</b> and <b>Ho</b> revolts; <b>Moplah revolts</b>."},{"i":396,"t":"Bankim Chandra Chatterjee","d":"19th century","g":"literature","y":1850,"e":10,"s":["kingdoms","languages"],"b":"<b>Bankim Chandra Chatterjee</b> (<i>Durgeshnandini</i>, <i>Anandamath</i>), <b>Michael Madhusudan Dutt</b>, <b>Mirza Ghalib</b>, <b>Bharatendu Harishchandra</b> (modern Hindi), <b>Fakir Mohan Senapati</b> (Odia), <b>Subramania Bharati</b> (c. 1900s)."},{"i":397,"t":"Botanical Survey","d":"19th century","g":"science and technology","y":1850,"e":10,"s":["science","architecture"],"b":"<b>Botanical Survey</b>; <b>Madras Medical College</b>. Colonial architecture: <b>St. Paul’s Cathedral</b> (Kolkata), <b>Madras High Court</b>, <b>Indo-Saracenic</b> style."},{"i":398,"t":"Wahhabi/Tariqah-i-Muhammadiya","d":"19th century","g":"Islam and communities, undated","y":1850,"e":10,"s":["religion"],"b":"<b>Wahhabi/Tariqah-i-Muhammadiya</b>, <b>Barelvi</b>. <b>Judaism:</b> <b>Bene Israel</b> (Konkan), <b>Baghdadi Jews</b> (Kolkata, Mumbai)."},{"i":399,"t":"Great Trigonometrical Survey","d":"1802 CE","g":"","y":1802,"e":10,"s":["rulers"],"b":"<b>Great Trigonometrical Survey</b> (1802 onward; <b>William Lambton</b>, <b>George Everest</b>). Peshwa signs Subsidiary Alliance at Bassein."},{"i":400,"t":"Second Anglo-Maratha War","d":"1803 to 1805 CE","g":"","y":1803,"e":10,"s":["kingdoms","wars"],"b":"<b>Second Anglo-Maratha War</b> (Assaye, Argaon; Treaties of Bassein, Surji-Anjangaon)."},{"i":401,"t":"Cornwallis","d":"1805 to 1807 CE","g":"","y":1805,"e":10,"s":[],"b":"<b>Cornwallis</b> (1805); <b>George Barlow</b> (1805 to 1807)."},{"i":402,"t":"Vellore Mutiny","d":"1806 CE","g":"","y":1806,"e":10,"s":["wars"],"b":"<b>Vellore Mutiny</b>. <b>Akbar II</b> (1806 to 1837)."},{"i":403,"t":"Lord Minto I","d":"1807 to 1813 CE","g":"","y":1807,"e":10,"s":[],"b":"<b>Lord Minto I</b>."},{"i":404,"t":"Treaty of Amritsar","d":"1809 CE","g":"","y":1809,"e":10,"s":[],"b":"<b>Treaty of Amritsar</b> (Ranjit Singh and the British)."},{"i":405,"t":"Hastings (Lord Moira)","d":"1813 to 1823 CE","g":"","y":1813,"e":10,"s":[],"b":"<b>Hastings (Lord Moira)</b>: <b>Charter Act of 1813</b> ends Company monopoly (except China and tea), allows missionaries, and sets aside Rs 1 lakh yearly for education."},{"i":406,"t":"Anglo-Nepal War","d":"1814 to 1816 CE","g":"","y":1814,"e":10,"s":["wars"],"b":"<b>Anglo-Nepal War</b> and <b>Treaty of Sugauli</b>. <b>Indian Museum</b> (1814)."},{"i":407,"t":"Third Anglo-Maratha War","d":"1817 to 1818 CE","g":"","y":1817,"e":10,"s":["kingdoms","wars","rulers"],"b":"<b>Third Anglo-Maratha War</b> ends Peshwa rule; <b>Pindari war</b>; <b>Peshwa Baji Rao II</b> pensioned off at Bithoor. <b>Ryotwari System</b> (Thomas Munro, Madras)."},{"i":408,"t":"Multan","d":"1818 CE","g":"","y":1818,"e":10,"s":[],"b":"Ranjit Singh takes <b>Multan</b>. <i>Samachar Darpan</i> (Serampore)."},{"i":409,"t":"Kashmir","d":"1819 CE","g":"","y":1819,"e":10,"s":[],"b":"Ranjit Singh takes <b>Kashmir</b>."},{"i":410,"t":"Mahalwari System","d":"1822 CE","g":"","y":1822,"e":10,"s":[],"b":"<b>Mahalwari System</b>. <b>Raja Ram Mohan Roy’s</b> <i>Mirat-ul-Akhbar</i>."},{"i":411,"t":"Lord Amherst","d":"1823 to 1828 CE","g":"","y":1823,"e":10,"s":[],"b":"<b>Lord Amherst</b>."},{"i":412,"t":"First Anglo-Burmese War","d":"1824 to 1826 CE","g":"","y":1824,"e":10,"s":["wars"],"b":"<b>First Anglo-Burmese War</b>."},{"i":413,"t":"Treaty of Yandabo","d":"1826 CE","g":"","y":1826,"e":10,"s":["kingdoms"],"b":"<b>Treaty of Yandabo</b>: Assam passes to the British; end of the Ahom dynasty (1228 to 1826)."},{"i":414,"t":"Lord William Bentinck","d":"1828 to 1835 CE","g":"Bentinck","y":1828,"e":10,"s":["leaders"],"b":"<b>Lord William Bentinck</b>: suppressed thuggee (William Sleeman). <b>Brahmo Sabha (1828)</b> founded by Raja Ram Mohan Roy. <b>Debendranath Tagore</b> and <b>Keshub Chandra Sen</b> expand the movement."},{"i":415,"t":"Abolition of sati","d":"1829 CE","g":"","y":1829,"e":10,"s":[],"b":"<b>Abolition of sati</b> (Regulation XVII), with Raja Ram Mohan Roy’s support. <b>Swathi Thirunal</b> (Travancore, 1829 to 1846)."},{"i":416,"t":"Charter Act","d":"1833 CE","g":"","y":1833,"e":10,"s":["rulers"],"b":"<b>Charter Act</b> (end of trade, Governor-General of India, Law Member <b>Macaulay</b>); Bentinck becomes first <b>Governor-General of India</b>. Raja Ram Mohan Roy dies (1833)."},{"i":417,"t":"Peshawar","d":"1834 CE","g":"","y":1834,"e":10,"s":[],"b":"Ranjit Singh takes <b>Peshawar</b>."},{"i":418,"t":"Macaulay’s Minute","d":"1835 CE","g":"","y":1835,"e":10,"s":[],"b":"<b>Macaulay’s Minute</b> and English education; Indian Press freed (<b>Metcalfe</b>). <b>Calcutta Medical College</b>. <b>Sir Charles Metcalfe</b> (1835 to 1836)."},{"i":419,"t":"Lord Auckland","d":"1836 to 1842 CE","g":"","y":1836,"e":10,"s":[],"b":"<b>Lord Auckland</b>."},{"i":420,"t":"Bahadur Shah II “Zafar”","d":"1837 CE","g":"","y":1837,"e":10,"s":["kingdoms","languages","rulers"],"b":"<b>Bahadur Shah II “Zafar”</b> (1837 to 1857) last Mughal emperor. <b>James Prinsep</b> deciphered Brahmi (1837)."},{"i":421,"t":"Times of India","d":"1838 CE","g":"","y":1838,"e":10,"s":[],"b":"<b>Times of India</b>."},{"i":422,"t":"First Anglo-Afghan War","d":"1839 to 1842 CE","g":"","y":1839,"e":10,"s":["wars"],"b":"<b>First Anglo-Afghan War</b> under <b>Auckland</b>. Ranjit Singh dies (1839)."},{"i":423,"t":"Lord Ellenborough","d":"1842 to 1844 CE","g":"","y":1842,"e":10,"s":[],"b":"<b>Lord Ellenborough</b>."},{"i":424,"t":"Sindh annexed","d":"1843 CE","g":"","y":1843,"e":10,"s":[],"b":"<b>Sindh annexed</b> under <b>Ellenborough</b> and <b>Charles Napier</b>; <b>Indian Slavery Act</b>. <b>Duleep Singh</b> (1843 to 1849)."},{"i":425,"t":"Lord Hardinge I","d":"1844 to 1848 CE","g":"","y":1844,"e":10,"s":[],"b":"<b>Lord Hardinge I</b>."},{"i":426,"t":"First Anglo-Sikh War","d":"1845 to 1846 CE","g":"","y":1845,"e":10,"s":["wars","religion"],"b":"<b>First Anglo-Sikh War</b> (Mudki, Ferozeshah, Aliwal, Sobraon; <b>Treaty of Lahore</b>, 1846)."},{"i":427,"t":"Dalhousie","d":"1848 to 1856 CE","g":"Dalhousie","y":1848,"e":10,"s":["wars","religion","leaders"],"b":"<b>Dalhousie</b>: <b>Doctrine of Lapse</b> (Satara 1848, Jhansi 1853, Nagpur 1854, Sambalpur 1849), PWD. <b>Second Anglo-Sikh War</b> (1848 to 1849; Chillianwala, Gujrat). <b>Jyotiba Phule</b> and <b>Savitribai Phule</b> open the first school for girls (Pune, 1848)."},{"i":428,"t":"Punjab annexed","d":"1849 CE","g":"","y":1849,"e":10,"s":["wars","religion"],"b":"<b>Punjab annexed</b> by <b>Dalhousie</b>; <b>Duleep Singh</b> exiled; the Koh-i-Noor is taken to Britain. Battle of Gujrat (Sikh). Sambalpur lapses."},{"i":429,"t":"Telegraph","d":"1851 CE","g":"","y":1851,"e":10,"s":[],"b":"<b>Telegraph</b> (1851 to 1854)."},{"i":430,"t":"Second Anglo-Burmese War","d":"1852 CE","g":"","y":1852,"e":10,"s":["wars"],"b":"<b>Second Anglo-Burmese War</b>."},{"i":431,"t":"railway","d":"1853 CE","g":"","y":1853,"e":10,"s":[],"b":"First <b>railway</b> (Bombay to Thane, <b>16 April 1853</b>). <b>Charter Act</b> (competitive exams for ICS; Law Commission). Jhansi annexed."},{"i":432,"t":"Wood’s Despatch","d":"1854 CE","g":"","y":1854,"e":10,"s":[],"b":"<b>Wood’s Despatch</b>; <b>Post Office Act</b>; postal reforms. Nagpur annexed."},{"i":433,"t":"Santhal Hul","d":"1855 to 1856 CE","g":"","y":1855,"e":10,"s":[],"b":"<b>Santhal Hul</b> (Sidhu and Kanhu)."},{"i":434,"t":"Annexation of Awadh","d":"1856 CE","g":"","y":1856,"e":10,"s":["religion"],"b":"<b>Annexation of Awadh</b>; <b>Widow Remarriage Act</b> (Hindu Widows’ Remarriage Act); <b>Ishwar Chandra Vidyasagar</b>; General Service Enlistment Act. <b>Lord Canning</b> (1856 to 1858)."},{"i":435,"t":"Calcutta, Bombay, Madras (1857)","d":"1857 CE","g":"Universities and Revolt","y":1857,"e":10,"s":["wars","independence"],"b":"Universities of <b>Calcutta, Bombay, Madras (1857)</b>. <b>Mangal Pandey</b> (Barrackpore, March 1857, a precursor). <b>10 May 1857: Revolt of 1857</b> begins at <b>Meerut</b> (greased cartridges for the Enfield rifle, discontent with annexations, taxes, social interference). Sepoys march to Delhi and proclaim <b>Bahadur Shah Zafar</b> emperor. Leaders: <b>Rani Lakshmibai</b> (Jhansi), <b>Nana Saheb</b>, <b>Tantia Tope</b> (Kanpur), <b>Begum Hazrat Mahal</b> (Lucknow), <b>Kunwar Singh</b> (Jagdishpur, Bihar), <b>Maulvi Ahmadullah Shah</b> (Faizabad), <b>Bakht Khan</b> (Delhi), <b>Khan Bahadur Khan</b> (Bareilly). Events: Siege and fall of <b>Delhi</b> (September 1857; <b>John Nicholson</b>), <b>Cawnpore</b> massacre, siege of <b>Lucknow</b> (Residency; <b>Henry Lawrence</b>, <b>Havelock</b>, <b>Colin Campbell</b>). Sikhs, Gurkhas, many princely rulers, and Madras troops stay mostly loyal."},{"i":436,"t":"Government of India Act 1858","d":"1858 CE","g":"End of Company rule","y":1858,"e":11,"s":["rulers","independence"],"b":"<b>Government of India Act 1858</b>; <b>Company rule ends</b>; <b>Crown rule begins</b>; <b>Queen Victoria’s Proclamation (1 November 1858)</b>; <b>Viceroy</b> (Lord Canning first, 1858 to 1862) and <b>Secretary of State for India</b>; reorganization of the army; princely states guaranteed (about 560). Fall of Jhansi (April 1858); Rani Lakshmibai dies at <b>Gwalior</b> (June 1858). <b>Bahadur Shah II Zafar</b> (1837 to 1857, deposed 1858) is the last Mughal emperor, exiled to Rangoon after 1857. Era overview: <b>1757 to 1858</b> East India Company rule; <b>1858 to 1947</b> the British Raj and the freedom movement."},{"i":437,"t":"Drain of wealth","d":"1858 to 1947 CE","g":"Colonial economy and society","y":1858,"e":11,"s":["rulers"],"b":"<b>Drain of wealth</b> theory (<b>Dadabhai Naoroji</b>; <b>R. C. Dutt</b>). <b>De-industrialization</b> of handicrafts (cotton textiles), commercialization of agriculture (indigo, opium, cotton, jute, tea), <b>famines</b>, railway growth, <b>telegraph</b>, <b>Indian Civil Services (ICS)</b>. <b>Opium Wars</b> (China; India as opium source)."},{"i":438,"t":"Indigo Revolt","d":"1859 to 1860 CE","g":"","y":1859,"e":11,"s":["wars","independence"],"b":"<b>Indigo Revolt</b>. <b>Dinabandhu Mitra’s</b> <i>Nil Darpan</i> (1860)."},{"i":439,"t":"Indian Penal Code","d":"1860 CE","g":"","y":1860,"e":11,"s":[],"b":"<b>Indian Penal Code</b> (<b>Macaulay’s</b> draft; in force 1862)."},{"i":440,"t":"Amrita Bazar Patrika","d":"19th century","g":"press, date not given","y":1850,"e":11,"s":[],"b":"<b>Amrita Bazar Patrika</b>."},{"i":441,"t":"Indian Councils Act","d":"1861 CE","g":"","y":1861,"e":11,"s":["religion","independence"],"b":"<b>Indian Councils Act</b> (portfolio system; non-official Indian members nominated); <b>Indian Police Act</b>; <b>High Courts Acts</b>; <b>Archaeological Survey of India</b> (<b>Alexander Cunningham</b>). <b>Radha Soami</b> (1861). Census attempts (1861 to 1872)."},{"i":442,"t":"Lord Elgin I","d":"1862 to 1863 CE","g":"","y":1862,"e":11,"s":["rulers","independence"],"b":"<b>Lord Elgin I</b> (Viceroy)."},{"i":443,"t":"Ramakrishna Paramahamsa","d":"1863 to 1902 CE","g":"Swami Vivekananda","y":1863,"e":11,"s":["kingdoms","leaders"],"b":"<b>Ramakrishna Paramahamsa</b> and <b>Swami Vivekananda</b> (1863 to 1902)."},{"i":444,"t":"Sir John Lawrence","d":"1864 to 1869 CE","g":"","y":1864,"e":11,"s":["rulers","independence"],"b":"<b>Sir John Lawrence</b> (Viceroy)."},{"i":445,"t":"Indian Forest Act","d":"1865 CE","g":"","y":1865,"e":11,"s":["independence"],"b":"<b>Indian Forest Act</b> (1865, 1878). <b>Mount Everest</b> named (1865); <b>Radhanath Sikdar</b> measures Peak XV."},{"i":446,"t":"Deoband","d":"1866 CE","g":"","y":1866,"e":11,"s":["architecture"],"b":"<b>Deoband</b> seminary."},{"i":447,"t":"Mahadev Govind Ranade","d":"1867 CE","g":"","y":1867,"e":11,"s":[],"b":"<b>Mahadev Govind Ranade</b> (Prarthana Samaj, 1867)."},{"i":448,"t":"Lord Mayo","d":"1869 to 1872 CE","g":"","y":1869,"e":11,"s":["rulers","independence"],"b":"<b>Lord Mayo</b> (Viceroy; assassinated at Port Blair, the Andamans). <b>Mayo’s</b> financial decentralization (1870)."},{"i":449,"t":"Native Marriage Act","d":"1872 CE","g":"","y":1872,"e":11,"s":["independence"],"b":"<b>Native Marriage Act</b> (Special Marriage Act). <b>Lord Northbrook</b> (1872 to 1876)."},{"i":450,"t":"Satyashodhak Samaj","d":"1873 CE","g":"","y":1873,"e":11,"s":["wars","religion","leaders","independence"],"b":"<b>Satyashodhak Samaj</b> (Jyotiba Phule and Savitribai Phule). <b>Singh Sabha</b> for Sikh reform. <b>Pabna</b> revolt."},{"i":451,"t":"Arya Samaj","d":"1875 CE","g":"","y":1875,"e":11,"s":["kingdoms","religion","leaders"],"b":"<b>Arya Samaj</b> (Bombay) founded by <b>Dayananda Saraswati</b>, “Back to the Vedas”; <i>Satyarth Prakash</i>; <b>shuddhi</b> movement. <b>Sir Syed Ahmad Khan:</b> <b>Aligarh Movement</b>, <b>Mohammedan Anglo-Oriental College</b>. <b>Theosophical Society</b> (Annie Besant). <b>Deccan Riots</b>."},{"i":452,"t":"Lord Lytton","d":"1876 to 1880 CE","g":"Lord Lytton","y":1876,"e":11,"s":[],"b":"<b>Lord Lytton</b>. <b>Indian Association</b> (Surendranath Banerjee, 1876). <b>Famine of 1876 to 1878</b>."},{"i":453,"t":"Delhi Durbar","d":"1877 CE","g":"","y":1877,"e":11,"s":[],"b":"<b>Delhi Durbar</b>."},{"i":454,"t":"Vernacular Press Act","d":"1878 CE","g":"","y":1878,"e":11,"s":["wars","religion","independence"],"b":"<b>Vernacular Press Act</b>; <b>Arms Act</b>. <b>Indian Forest Act</b> (1878). <b>The Hindu</b> (1878). <b>Anglo-Afghan Wars</b> (second war 1878 to 1880)."},{"i":455,"t":"Lord Ripon","d":"1880 to 1884 CE","g":"Lord Ripon","y":1880,"e":11,"s":["independence"],"b":"<b>Lord Ripon</b>: Vernacular Press Act repealed."},{"i":456,"t":"First Factory Act","d":"1881 CE","g":"","y":1881,"e":11,"s":["leaders","independence"],"b":"<b>First Factory Act</b>. First complete <b>census 1881</b> (<b>W. W. Hunter</b>; last of that British-era series 1941). <b>Kesari</b> (1881). <b>Bal Gangadhar Tilak</b> (“Swaraj is my birthright”; Ganesh and Shivaji festivals, <b>Kesari</b>, <b>Mahratta</b>)."},{"i":457,"t":"Local Self-Government Resolution","d":"1882 CE","g":"","y":1882,"e":11,"s":["kingdoms"],"b":"<b>Local Self-Government Resolution</b>; <b>Hunter Commission</b> (education). <b>Bankim Chandra Chatterjee’s</b> <i>Anandamath</i> (1882)."},{"i":458,"t":"Ilbert Bill","d":"1883 CE","g":"","y":1883,"e":11,"s":[],"b":"<b>Ilbert Bill</b> controversy."},{"i":459,"t":"Lord Dufferin","d":"1884 to 1888 CE","g":"","y":1884,"e":11,"s":["rulers","independence"],"b":"<b>Lord Dufferin</b> (Viceroy)."},{"i":460,"t":"28 December 1885: Indian National Congress founded","d":"1885 CE","g":"Indian National Congress","y":1885,"e":11,"s":["rulers","independence"],"b":"<b>28 December 1885: Indian National Congress founded</b> in Bombay by <b>A. O. Hume</b> with first president <b>W. C. Bonnerjee</b>, 72 delegates; Bombay Presidency Association (1885). <b>Moderate phase (1885 to 1905):</b> <b>Dadabhai Naoroji</b>, <b>Gopal Krishna Gokhale</b>, <b>Pherozeshah Mehta</b>, <b>Surendranath Banerjee</b>, <b>Romesh Chunder Dutt</b>, <b>Justice Ranade</b>; prayers, petitions, and protests. <b>Anglo-Burmese Wars</b> (third, 1885)."},{"i":461,"t":"Dadabhai Naoroji","d":"1886 CE","g":"","y":1886,"e":11,"s":[],"b":"INC session, Calcutta: <b>Dadabhai Naoroji</b>."},{"i":462,"t":"Badruddin Tyabji","d":"1887 CE","g":"","y":1887,"e":11,"s":["rulers","leaders"],"b":"INC session, Madras: <b>Badruddin Tyabji</b> (first Muslim president). <b>Chhatrapati Shivaji Terminus (Victoria Terminus)</b> (1887). <b>Srinivasa Ramanujan</b> born (1887; d. 1920)."},{"i":463,"t":"George Yule","d":"1888 CE","g":"","y":1888,"e":11,"s":["rulers"],"b":"INC session, Allahabad: <b>George Yule</b> (first English president). <b>Lord Lansdowne</b> (1888 to 1894)."},{"i":464,"t":"Sir William Wedderburn","d":"1889 CE","g":"","y":1889,"e":11,"s":[],"b":"INC session, Bombay: <b>Sir William Wedderburn</b>. <b>Ahmadiyya</b> (1889). <b>Chandu Menon’s</b> <i>Indulekha</i> (1889, Malayalam novel)."},{"i":465,"t":"Pherozeshah Mehta","d":"1890 CE","g":"","y":1890,"e":11,"s":[],"b":"INC session, Calcutta: <b>Pherozeshah Mehta</b>."},{"i":466,"t":"Anagarika Dharmapala","d":"1891 CE","g":"","y":1891,"e":11,"s":["religion"],"b":"<b>Anagarika Dharmapala</b> (Maha Bodhi Society, 1891)."},{"i":467,"t":"Indian Councils Act","d":"1892 CE","g":"","y":1892,"e":11,"s":["religion","independence"],"b":"<b>Indian Councils Act</b> (indirect elections)."},{"i":468,"t":"Swami Vivekananda","d":"1893 CE","g":"","y":1893,"e":11,"s":["kingdoms","leaders"],"b":"<b>Swami Vivekananda</b> at the <b>Parliament of Religions, Chicago (1893)</b>. <b>M. K. Gandhi</b> goes to South Africa (1893 to 1914)."},{"i":469,"t":"Natal Indian Congress","d":"1894 CE","g":"","y":1894,"e":11,"s":["leaders","independence"],"b":"<b>Natal Indian Congress</b> (Gandhi). <b>Lord Elgin II</b> (1894 to 1899). <b>Nadwatul Ulama</b> (1894). <b>Indian Famine Commissions</b> (1894 to 1900)."},{"i":470,"t":"Surendranath Banerjee","d":"1895 CE","g":"","y":1895,"e":11,"s":[],"b":"INC session, Poona: <b>Surendranath Banerjee</b>."},{"i":471,"t":"Famine","d":"1896 to 1897 CE","g":"","y":1896,"e":11,"s":[],"b":"<b>Famine</b> of 1896 to 1897."},{"i":472,"t":"C. Sankaran Nair","d":"1897 CE","g":"","y":1897,"e":11,"s":["leaders","independence"],"b":"INC session, Amravati: <b>C. Sankaran Nair</b>. <b>Chapekar brothers</b> assassinate Rand; Tilak jailed for sedition (<b>Sedition law</b>, Section 124A). <b>Epidemic Diseases Act</b>. <b>Ramakrishna Mission</b> (1897). <b>Ronald Ross</b> shows how malaria is transmitted (1897, Secunderabad); <b>Haffkine</b> develops plague vaccine (Bombay, 1897)."},{"i":473,"t":"R. C. Dutt","d":"1899 CE","g":"","y":1899,"e":11,"s":["rulers","independence"],"b":"INC session, Lucknow: <b>R. C. Dutt</b>. <b>Lord Curzon</b> (1899 to 1905). <b>Calcutta Corporation Act</b>. <b>Munda Ulgulan</b> (1899 to 1900, Birsa Munda). <b>Famine of 1899 to 1900</b>."},{"i":474,"t":"Subramania Bharati","d":"c. 1900s CE","g":"","y":1900,"e":11,"s":["kingdoms","religion","languages","leaders"],"b":"<b>Subramania Bharati</b> (literature). <b>Modern spiritual figures:</b> <b>Ramakrishna</b>, <b>Vivekananda</b>, <b>Ramana Maharshi</b> (Arunachala), <b>Sri Aurobindo</b> (Pondicherry), <b>Paramahansa Yogananda</b> (<i>Autobiography of a Yogi</i>, 1946), <b>Sri Sathya Sai Baba</b>, <b>J. Krishnamurti</b>, <b>Swami Sivananda</b>, <b>Sri Narayana Guru</b>, <b>Meher Baba</b>, <b>Anandamayi Ma</b>, <b>Maharishi Mahesh Yogi</b>. Extremists: <b>Bipin Chandra Pal</b>, <b>Lala Lajpat Rai</b> (“Lal-Bal-Pal”); <b>Aurobindo Ghose</b>. Cultural renaissance: <b>Sarat Chandra</b>, <b>Premchand</b>, <b>Muhammad Iqbal</b>, <b>Bengal School of Art</b> (Abanindranath Tagore), <b>Raja Ravi Varma</b>. Women’s participation: <b>Kasturba Gandhi</b>, <b>Kamala Nehru</b>, <b>Sucheta Kriplani</b>, <b>Matangini Hazra</b>, <b>Pritilata Waddedar</b>; earlier resisters <b>Kittur Chennamma</b> and <b>Rani Abbakka</b>. Freedom-struggle revolutionaries (see dated entries)."},{"i":475,"t":"Tagore","d":"20th century","g":"literature","y":1950,"e":11,"s":["languages","rulers","leaders"],"b":"<b>Tagore</b> (<i>Gitanjali</i>), <b>Premchand</b>, <b>Iqbal</b>, <b>Sarat Chandra</b>, <b>Jayashankar Prasad</b>, <b>Nirala</b>, <b>Mahadevi Verma</b>, <b>Kuvempu</b>, <b>Bendre</b>, <b>Vallathol</b>, <b>Faiz</b>, <b>Manto</b>, <b>R. K. Narayan</b>, <b>Mulk Raj Anand</b>, <b>Raja Rao</b>, <b>Amrita Pritam</b>, <b>Mahasweta Devi</b>, <b>Girish Karnad</b>."},{"i":476,"t":"J. C. Bose","d":"Early 20th century","g":"science","y":1950,"e":11,"s":["science","leaders"],"b":"<b>J. C. Bose</b> (<b>Jagadish Chandra Bose</b>) shows plant response and invents millimeter-wave devices; <b>Birbal Sahni</b> (palaeobotany); <b>Visvesvaraya</b> (engineer; <b>Krishna Raja Sagara Dam</b>)."},{"i":477,"t":"Dadabhai Naoroji","d":"1901 CE","g":"","y":1901,"e":11,"s":[],"b":"<b>Dadabhai Naoroji</b>, <i>Poverty and Un-British Rule in India</i> (1901). <b>P. C. Ray</b> founds <b>Bengal Chemicals</b> (1901)."},{"i":478,"t":"Delhi Durbar","d":"1903 to 1904 CE","g":"","y":1903,"e":11,"s":[],"b":"<b>Delhi Durbar</b> (1903). <b>Younghusband expedition to Tibet</b> (1903 to 1904)."},{"i":479,"t":"Indian Universities Act","d":"1904 CE","g":"","y":1904,"e":11,"s":["architecture","independence"],"b":"<b>Indian Universities Act</b>; <b>Ancient Monuments Preservation Act</b>; <b>Official Secrets Act</b>; <b>Cooperative Credit Societies Act</b>."},{"i":480,"t":"16 October 1905: Partition of Bengal","d":"1905 CE","g":"Partition of Bengal","y":1905,"e":11,"s":["leaders","independence"],"b":"<b>16 October 1905: Partition of Bengal</b> by Curzon; <b>Swadeshi and Boycott Movement</b> begins (7 August 1905 Calcutta resolution); “<b>Vande Mataram</b>” becomes the rallying song; <b>Rabindranath Tagore’s</b> <i>Amar Sonar Bangla</i>. INC session, Banaras: <b>G. K. Gokhale</b>. <b>Lord Minto II</b> (1905 to 1910)."},{"i":481,"t":"All India Muslim League","d":"1906 CE","g":"","y":1906,"e":11,"s":["religion","independence"],"b":"<b>All India Muslim League</b> founded at Dhaka (<b>Aga Khan III</b>, <b>Nawab Salimullah</b>). <b>1906 Calcutta Congress</b> adopts Swaraj as goal (<b>Dadabhai Naoroji</b>). <b>National Council of Education</b> (1906)."},{"i":482,"t":"Surat Split","d":"1907 CE","g":"","y":1907,"e":11,"s":[],"b":"<b>Surat Split:</b> Moderates and Extremists divide (INC session at Surat: <b>Rash Behari Ghosh</b>). <b>Madame Bhikaji Cama</b> unfurls an Indian flag at Stuttgart. <b>Shyamji Krishna Varma</b> (India House, London). <b>Tata Steel</b> (1907, Jamshedpur)."},{"i":483,"t":"Khudiram Bose","d":"1908 CE","g":"","y":1908,"e":11,"s":["leaders"],"b":"<b>Khudiram Bose</b> and <b>Prafulla Chaki</b> attempt to kill Kingsford; Tilak jailed in Mandalay (1908 to 1914)."},{"i":484,"t":"Indian Councils Act 1909 (Morley-Minto Reforms)","d":"1909 CE","g":"","y":1909,"e":11,"s":["religion","science","independence"],"b":"<b>Indian Councils Act 1909 (Morley-Minto Reforms)</b> granting separate electorates for Muslims. <b>Madan Lal Dhingra</b> (1909). INC session, Lahore: <b>Madan Mohan Malaviya</b>. <b>Institute of Science, Bangalore</b> (1909; <b>Jamsetji Tata</b>). Revolutionaries: <b>Anushilan Samiti</b> and <b>Jugantar</b> (Bengal), <b>Savarkar</b> and <b>Abhinav Bharat</b>."},{"i":485,"t":"Lord Hardinge II","d":"1910 to 1916 CE","g":"","y":1910,"e":11,"s":[],"b":"<b>Lord Hardinge II</b>."},{"i":486,"t":"Delhi becomes capital (announced 1911)","d":"1911 CE","g":"","y":1911,"e":11,"s":["independence"],"b":"<b>Delhi becomes capital (announced 1911)</b>; <b>Partition of Bengal annulled (1911)</b>. Era of Lutyens and Baker’s New Delhi (1912 to 1931)."},{"i":487,"t":"Lord Hardinge’s","d":"1912 CE","g":"","y":1912,"e":11,"s":["leaders"],"b":"Attempt on <b>Lord Hardinge’s</b> life; <b>Rash Behari Bose</b> (Delhi Conspiracy, 1912). <b>Rashtrapati Bhavan</b> and New Delhi (<b>Edwin Lutyens</b> and <b>Herbert Baker</b>, 1912 to 1931)."},{"i":488,"t":"Rabindranath Tagore","d":"1913 CE","g":"","y":1913,"e":11,"s":["languages","leaders"],"b":"<b>Rabindranath Tagore</b> (Nobel Prize for Literature, 1913; <i>Gitanjali</i>). <b>Ghadar Party</b> (1913, San Francisco; Lala Har Dayal, Sohan Singh Bhakna). <b>Dadasaheb Phalke’s</b> <i>Raja Harishchandra</i> (1913)."},{"i":489,"t":"India Gate (1931)","d":"1914 to 1918 CE","g":"World War I","y":1914,"e":11,"s":["wars"],"b":"About 1.3 million Indian soldiers serve overseas; heavy casualties; <b>India Gate (1931)</b> commemorates them. Indian Army in Europe, Mesopotamia, Gallipoli, East Africa. <b>Komagata Maru incident (1914)</b>."},{"i":490,"t":"M. K. Gandhi","d":"1915 CE","g":"","y":1915,"e":11,"s":["leaders","independence"],"b":"<b>M. K. Gandhi</b> returns to India (January 1915), guided by <b>Gokhale</b>. (<b>Gandhi</b> in South Africa 1893 to 1914: <b>Satyagraha</b>, <b>Phoenix Settlement</b>, <b>Tolstoy Farm</b>.)"},{"i":491,"t":"Lucknow Pact","d":"1916 CE","g":"","y":1916,"e":11,"s":["leaders","independence"],"b":"<b>Lucknow Pact:</b> Congress and Muslim League reunite; Congress accepts separate electorates (INC session, Lucknow: <b>A. C. Majumdar</b>). <b>Home Rule Leagues (1916)</b>: <b>Tilak</b> (Pune) and <b>Annie Besant</b> (Madras). <b>Justice Party (1916)</b>. <b>Lord Chelmsford</b> (1916 to 1921)."},{"i":492,"t":"August Declaration","d":"1917 CE","g":"","y":1917,"e":11,"s":["rulers","independence"],"b":"<b>August Declaration</b> by <b>Edwin Montagu</b> promises “responsible government” (Montagu Declaration). <b>Annie Besant</b> (Congress president, 1917; INC session Calcutta; first woman). <b>Champaran Satyagraha</b> (1917 to 1918; Bihar; indigo; <b>Rajendra Prasad</b>, <b>J. B. Kripalani</b>). <b>Sadler Commission</b> (1917)."},{"i":493,"t":"Ahmedabad mill strike","d":"1918 CE","g":"","y":1918,"e":11,"s":["leaders","independence"],"b":"<b>Ahmedabad mill strike</b>; <b>Kheda Satyagraha</b>. Srinivasa Ramanujan (Fellow of the Royal Society 1918; Trinity College, Cambridge)."},{"i":494,"t":"Rowlatt Act (March)","d":"1919 CE","g":"","y":1919,"e":11,"s":["places","leaders","independence"],"b":"<b>Rowlatt Act (March)</b>; <b>Rowlatt Satyagraha</b>; <b>13 April 1919: Jallianwala Bagh massacre</b> in Amritsar (General <b>Dyer</b>; about 379 officially killed, much higher by Indian estimates); <b>Hunter Committee</b>; <b>Tagore renounces knighthood</b>. <b>Montagu-Chelmsford Reforms</b> and <b>Government of India Act 1919 (dyarchy)</b>; bicameral Centre. INC session, Amritsar: <b>Motilal Nehru</b>. Anglo-Afghan War (1919)."},{"i":495,"t":"Non-Cooperation Movement (1920 to 1922)","d":"1920 CE","g":"","y":1920,"e":11,"s":["religion","leaders","independence"],"b":"<b>Non-Cooperation Movement (1920 to 1922)</b> and <b>Khilafat Movement</b> (<b>Ali brothers</b>, <b>Maulana Azad</b>); boycott of councils, courts, schools. <b>Tilak dies (1 August 1920)</b>. INC special session, Calcutta: <b>Lala Lajpat Rai</b>; Nagpur: <b>C. Vijayaraghavachariar</b> (Non-Cooperation, creed of Swaraj). <b>AITUC (1920)</b>. <b>Communist Party of India</b> (earlier 1920 in Tashkent). <b>Gurdwara Reform Movement</b> and <b>SGPC</b> (1920 to 1925). <b>Srinivasa Ramanujan</b> dies (1920). <b>Meghnad Saha</b> (ionization equation, 1920)."},{"i":496,"t":"Kisan Sabhas","d":"1920s onward","g":"Kisan Sabhas","y":1920,"e":11,"s":[],"b":"<b>Kisan Sabhas</b> (<b>Swami Sahajanand Saraswati</b>), peasant and labour movements of the era."},{"i":497,"t":"Daya Ram Sahni","d":"1920 to 1922 CE","g":"Discovery of the Indus cities","y":1920,"e":11,"s":["places","rulers"],"b":"Discovery of Harappa (<b>Daya Ram Sahni</b>) and Mohenjo-daro (<b>R. D. Banerji</b>). Later excavations by <b>Mortimer Wheeler</b>, and others. (See the Indus Valley Civilization, c. 2600 BCE.)"},{"i":498,"t":"Lord Reading","d":"1921 CE","g":"","y":1921,"e":11,"s":[],"b":"<b>Lord Reading</b> (1921 to 1926). <b>Prince of Wales visit</b> boycotted. <b>Victoria Memorial</b> (completed 1921)."},{"i":499,"t":"5 February 1922: Chauri Chaura incident","d":"1922 CE","g":"","y":1922,"e":11,"s":["rulers","leaders"],"b":"<b>5 February 1922: Chauri Chaura incident</b> (UP; 22 policemen killed); Gandhi suspends the movement. <b>Sedition trial of Gandhi</b>. INC session, Gaya: <b>C. R. Das</b>."},{"i":500,"t":"Swaraj Party","d":"1923 CE","g":"","y":1923,"e":11,"s":["rulers","leaders"],"b":"<b>Swaraj Party</b> (C. R. Das and Motilal Nehru). <b>Lee Commission</b> (1923 to 1924)."},{"i":501,"t":"Hindustan Republican Association","d":"1924 CE","g":"","y":1924,"e":11,"s":["religion","architecture","rulers","leaders","independence"],"b":"<b>Hindustan Republican Association</b> (1924 to 1925); <b>Vaikom Satyagraha</b> (1924 to 1925); <b>Bahishkrit Hitakarini Sabha (1924, B. R. Ambedkar)</b>. <b>Gateway of India</b> (1924). INC session, Belgaum: <b>M. K. Gandhi</b> (only session he presided). <b>S. N. Bose</b> (Bose-Einstein statistics, 1924)."},{"i":502,"t":"Sir John Marshall","d":"1924 CE","g":"Indus Valley announced","y":1924,"e":11,"s":["places"],"b":"<b>Sir John Marshall</b> announces the Indus Valley (Harappan) civilization."},{"i":503,"t":"RSS","d":"1925 CE","g":"","y":1925,"e":11,"s":["rulers","leaders","independence"],"b":"<b>RSS</b> founded (<b>K. B. Hedgewar</b>); <b>Communist Party of India</b> (formally 1925); <b>Kakori Conspiracy (1925)</b>: <b>Ram Prasad Bismil</b>, <b>Ashfaqulla Khan</b>, <b>Roshan Singh</b> hanged. <b>Sarojini Naidu</b> (Congress president, 1925; INC session Kanpur; first Indian woman). <b>Periyar E. V. Ramasamy</b> (<b>Self-Respect Movement, 1925</b>)."},{"i":504,"t":"Lord Irwin","d":"1926 to 1931 CE","g":"","y":1926,"e":11,"s":["independence"],"b":"<b>Lord Irwin</b>. <b>Union Public Service Commission</b> (1926; constitutional 1950)."},{"i":505,"t":"Simon Commission (1927 to 1928)","d":"1927 CE","g":"","y":1927,"e":11,"s":["rulers","leaders","independence"],"b":"<b>Simon Commission (1927 to 1928)</b>. <b>Mahad Satyagraha, 1927</b> (B. R. Ambedkar). All-India States Peoples’ Conference (1927). INC session, Madras: <b>M. A. Ansari</b>."},{"i":506,"t":"Simon Commission","d":"1928 CE","g":"","y":1928,"e":11,"s":["leaders","independence"],"b":"<b>Simon Commission</b> (all-white) boycotted (“Simon Go Back”); <b>Lala Lajpat Rai</b> injured by lathi-charge (dies Nov 1928); <b>Nehru Report (1928)</b>. <b>Bardoli Satyagraha (1928, Vallabhbhai Patel)</b>. INC session, Calcutta: <b>Motilal Nehru</b> (Nehru Report). <b>C. V. Raman</b> (<b>Raman Effect</b>, 1928)."},{"i":507,"t":"Lahore Congress","d":"1929 CE","g":"","y":1929,"e":11,"s":["leaders","independence"],"b":"<b>Lahore Congress</b> (<b>Jawaharlal Nehru</b> presiding) resolves <b>Purna Swaraj</b>; <b>Jinnah’s Fourteen Points (1929)</b>. <b>Bhagat Singh</b> and <b>Batukeshwar Dutt</b> bomb the Central Legislative Assembly."},{"i":508,"t":"26 January 1930","d":"1930 CE","g":"","y":1930,"e":11,"s":["leaders","independence"],"b":"<b>26 January 1930</b> observed as Independence Day. <b>Civil Disobedience Movement (1930 to 1934):</b> <b>Dandi March (12 March to 6 April 1930)</b>, <b>Salt Satyagraha</b>; Dharasana; <b>Frontier Gandhi (Abdul Ghaffar Khan)</b> and <b>Khudai Khidmatgars</b>. <b>Surya Sen</b> leads the <b>Chittagong Armoury Raid (1930)</b>. <b>First Round Table Conference</b> (London, 1930; Round Table Conferences 1930 to 1932). <b>Kalaram temple entry, 1930</b> (Ambedkar). <b>C. V. Raman</b> (Nobel 1930). <b>S. Chandrasekhar</b> (Chandrasekhar limit, 1930)."},{"i":509,"t":"Gandhi-Irwin Pact (March 1931)","d":"1931 CE","g":"","y":1931,"e":11,"s":["leaders"],"b":"<b>Gandhi-Irwin Pact (March 1931)</b>; <b>Second RTC</b> (1931, Gandhi attends). <b>Bhagat Singh</b>, <b>Rajguru</b>, <b>Sukhdev</b> hanged (<b>23 March 1931</b>); <b>Chandra Shekhar Azad</b> dies (1931). INC session, Karachi: <b>Vallabhbhai Patel</b> (Fundamental Rights and economic policy resolution). <b>Alam Ara</b> (first Indian talkie, 1931). <b>Delhi capital inaugurated (1931)</b>; <b>India Gate (1931)</b>. <b>Lord Willingdon</b> (1931 to 1936)."},{"i":510,"t":"Communal Award (1932)","d":"1932 CE","g":"","y":1932,"e":11,"s":["wars","rulers","leaders"],"b":"<b>Communal Award (1932)</b> gives separate electorates to the Depressed Classes; <b>Poona Pact (24 September 1932)</b> between <b>Gandhi</b> and <b>B. R. Ambedkar</b>; <b>Harijan</b> campaign."},{"i":511,"t":"Nellie Sengupta","d":"1933 CE","g":"","y":1933,"e":11,"s":["kingdoms","rulers"],"b":"INC session, Calcutta: <b>Nellie Sengupta</b> (first British-born woman president)."},{"i":512,"t":"Government of India Act 1935","d":"1935 CE","g":"","y":1935,"e":11,"s":["independence"],"b":"<b>Government of India Act 1935:</b> federation (never implemented), provincial autonomy; <b>Federal Court</b>; the longest British-Indian act; basis for much of the Indian Constitution. <b>Reserve Bank of India (1 April 1935)</b> (nationalized 1949)."},{"i":513,"t":"Lord Linlithgow","d":"1936 CE","g":"","y":1936,"e":11,"s":["architecture","leaders"],"b":"<b>Lord Linlithgow</b> (1936 to 1943). <b>Temple Entry Proclamation (1936)</b> under Chithira Thirunal (Travancore). <b>Independent Labour Party, 1936</b> (Ambedkar). INC session, Lucknow: <b>Nehru</b>."},{"i":514,"t":"Provincial elections","d":"1937 CE","g":"","y":1937,"e":11,"s":["leaders","independence"],"b":"<b>Provincial elections:</b> Congress wins 7 of 11 provinces. INC session, Faizpur: <b>Nehru</b>."},{"i":515,"t":"Subhas Chandra Bose","d":"1938 CE","g":"","y":1938,"e":11,"s":["rulers","leaders","independence"],"b":"<b>Subhas Chandra Bose</b> Congress president (Haripura)."},{"i":516,"t":"Rajendra Prasad","d":"1939 CE","g":"","y":1939,"e":11,"s":["wars","leaders","independence"],"b":"Bose re-elected at Tripuri, resigns (<b>Rajendra Prasad</b> took over); founds <b>Forward Bloc</b>. <b>Outbreak of WWII (1939)</b>; Congress ministries resign over India’s entry into WWII. World War II (about 2.5 million Indian soldiers; North Africa, Italy, Burma)."},{"i":517,"t":"Lahore Resolution (Pakistan Resolution)","d":"1940 CE","g":"","y":1940,"e":11,"s":["independence"],"b":"<b>Lahore Resolution (Pakistan Resolution)</b>, 23 March, by the <b>Muslim League</b> (<b>Jinnah’s</b> Two-Nation theory); <b>August Offer</b>; <b>Individual Satyagraha</b> (Vinoba Bhave first). <b>Udham Singh</b> assassinates <b>Michael O’Dwyer</b> (1940). INC session, Ramgarh: <b>Maulana Abul Kalam Azad</b> (continued as president to 1946)."},{"i":518,"t":"1941 CE","d":"1941 CE","g":"","y":1941,"e":11,"s":[],"b":"Last British-era census (1941)."},{"i":519,"t":"Cripps Mission (March)","d":"1942 CE","g":"Cripps Mission and Quit India","y":1942,"e":11,"s":["wars","independence"],"b":"<b>Cripps Mission (March)</b>: offers Dominion status after the war; rejected. <b>8 August 1942: Quit India Movement</b> (“<b>Do or Die</b>”); Congress leaders arrested at once (9 August); <b>Aruna Asaf Ali</b> hoists the flag at Gowalia Tank Maidan; underground radio (Usha Mehta); parallel governments (Ballia, Tamluk, Satara); <b>Jayaprakash Narayan</b> and <b>Ram Manohar Lohia</b>. <b>CSIR</b> (1942)."},{"i":520,"t":"Lord Wavell","d":"1943 CE","g":"","y":1943,"e":11,"s":["architecture","leaders"],"b":"<b>Lord Wavell</b> (1943 to 1947). <b>Bengal Famine of 1943</b> (an estimated 2 to 3 million deaths). <b>Indian National Army (INA):</b> <b>Subhas Chandra Bose</b> (Netaji) forms the <b>Azad Hind Government</b> (Singapore, 21 October 1943) and leads the <b>INA</b> with Japanese support (<b>Rash Behari Bose</b> and <b>Mohan Singh</b> earlier); slogans “<b>Delhi Chalo</b>”, “<b>Jai Hind</b>”; Imphal-Kohima campaign. <b>Howrah Bridge</b> (1943)."},{"i":521,"t":"C. Rajagopalachari","d":"1944 CE","g":"","y":1944,"e":11,"s":["leaders"],"b":"<b>C. Rajagopalachari</b> formula (1944 to 1945); <b>Gandhi-Jinnah talks</b>; <b>Bombay Plan</b> for industrial development. <b>Wavell</b> takes charge."},{"i":522,"t":"Wavell Plan","d":"1945 CE","g":"","y":1945,"e":11,"s":["places","architecture","leaders"],"b":"<b>Wavell Plan</b> and <b>Simla Conference (1945)</b>. <b>British Labour government</b>. <b>Subhas Chandra Bose</b> reportedly dies in air crash at Taipei (<b>18 August 1945</b>, disputed). <b>INA trials (1945 to 1946)</b> at the Red Fort stir the nation. <b>Homi Bhabha</b> founds <b>TIFR</b> (1945)."},{"i":523,"t":"Royal Indian Navy mutiny (February)","d":"1946 CE","g":"","y":1946,"e":11,"s":["wars","independence"],"b":"<b>Royal Indian Navy mutiny (February)</b>; <b>Cabinet Mission (March to June)</b>: <b>Pethick-Lawrence, Stafford Cripps, A. V. Alexander</b>; proposes a loose three-tier federation; <b>16 August 1946: Direct Action Day</b> (Calcutta killings; wider communal violence in <b>Noakhali</b>, <b>Bihar</b>); <b>Interim Government</b> formed (2 September) under <b>Nehru</b>; Constituent Assembly meets on <b>9 December 1946</b>. <b>Telangana</b> peasant struggle (1946 to 1951); <b>Tebhaga</b> movement (1946 to 1947); <b>Punnapra-Vayalar (1946)</b>; <b>Quit Kashmir</b> (<b>Sheikh Abdullah</b>, 1946); movements in <b>Hyderabad</b>, <b>Travancore</b>, <b>Mysore</b>, <b>Kashmir</b>. INC session, Meerut: <b>J. B. Kripalani</b> (also president at Independence). <b>Paramahansa Yogananda’s</b> <i>Autobiography of a Yogi</i> (1946)."},{"i":524,"t":"20 February: Attlee announces","d":"1947 CE","g":"Mountbatten and the Indian Independence Act","y":1947,"e":11,"s":["rulers","independence"],"b":"<b>20 February: Attlee announces</b> British withdrawal by June 1948; <b>Lord Mountbatten</b> Viceroy (March to August 1947), last Viceroy; <b>3 June: Mountbatten Plan</b>; <b>Indian Independence Act (18 July 1947)</b>; <b>Radcliffe Line</b> boundary award."},{"i":525,"t":"14 to 15 August 1947: Independence","d":"1947 CE","g":"Independence and Partition","y":1947,"e":12,"s":["rulers","leaders","independence"],"b":"<b>14 to 15 August 1947: Independence</b> and <b>Partition</b> of India into <b>India</b> and <b>Pakistan</b>. <b>15 August 1947:</b> <b>Jawaharlal Nehru</b> (first Prime Minister) delivers the “<b>Tryst with Destiny</b>” speech; <b>Lord Mountbatten</b> first Governor-General of the Dominion of India (until June 1948); <b>Vallabhbhai Patel</b> (Deputy PM and Home Minister). Era overview: <b>1947 to present</b> is the Republic of India. <b>Partition:</b> one of the largest forced migrations in history; roughly <b>10 to 15 million displaced</b> and an estimated <b>one to two million killed</b> (estimates vary); violence in <b>Punjab</b> and <b>Bengal</b>; refugee settlement. Provinces and princely states merge into Part A, B, C, D states (1947 to 1950)."},{"i":526,"t":"Sardar Patel","d":"1947 to 1949 CE","g":"Integration of Princely States","y":1947,"e":12,"s":["leaders"],"b":"Led by <b>Sardar Patel</b> and <b>V. P. Menon</b> using the <b>Instrument of Accession</b> and <b>Standstill Agreements</b>; <b>Kashmir</b> (accession <b>26 October 1947</b>, after a tribal and Pakistani-backed raid); <b>Junagadh</b> (plebiscite, Feb 1948); <b>Hyderabad</b> (<b>Operation Polo</b>, 13 to 18 September 1948); <b>Travancore</b>, <b>Bhopal</b>, <b>Jodhpur</b>; French enclaves (Chandernagore 1950; Pondicherry 1954); <b>Goa liberated (December 1961, Operation Vijay)</b>; <b>Sikkim</b> joins India (<b>1975</b>)."},{"i":527,"t":"Line of Control","d":"1947 to 1948 CE","g":"First India-Pakistan War","y":1947,"e":12,"s":["wars"],"b":"Ceasefire (1 January 1949) through UN mediation; the <b>Line of Control</b> emerges; Kashmir issue referred to the UN. War list: India-Pakistan (Kashmir)."},{"i":528,"t":"Democracy","d":"c. 1947 onward","g":"Major themes since independence","y":1947,"e":12,"s":["independence"],"b":"<b>Democracy:</b> peaceful transfers of power; <b>Right to Information</b>; <b>Panchayati Raj</b>. <b>Economy:</b> from a mostly agrarian economy to one of the world’s largest; <b>IT and services</b>, <b>pharma</b>, <b>space</b>, <b>digital payments</b>; poverty reduction alongside persistent inequality. <b>Social movements:</b> <b>Narmada Bachao Andolan</b> (<b>Medha Patkar</b>), <b>women’s movements</b>, <b>Mandal and OBC politics</b>, <b>LGBTQ rights</b>, <b>tribal rights</b>. <b>Security:</b> wars with Pakistan (<b>1947, 1965, 1971, 1999 Kargil</b>) and China (<b>1962</b>); insurgencies in <b>Punjab</b>, <b>Kashmir</b>, <b>Northeast</b> (<b>Nagaland</b>, <b>Mizoram</b>, <b>Manipur</b>, <b>Assam</b>), and <b>Maoist/Naxal</b> violence; nuclear power (<b>1974, 1998</b>)."},{"i":529,"t":"30 January 1948","d":"1948 CE","g":"","y":1948,"e":12,"s":["leaders"],"b":"<b>30 January 1948:</b> <b>Mahatma Gandhi assassinated</b> by <b>Nathuram Godse</b> in Delhi (Birla House). <b>Atomic Energy Commission (1948; Homi Bhabha)</b>. <b>Operation Polo</b> (Hyderabad); the Nizam <b>Mir Osman Ali Khan</b> (1911 to 1948). <b>C. Rajagopalachari</b> (1948 to 1950), the only Indian Governor-General; Mountbatten’s term as Governor-General ends (June 1948). INC session, Jaipur: <b>Pattabhi Sitaramayya</b>."},{"i":530,"t":"26 November 1949","d":"1949 CE","g":"","y":1949,"e":12,"s":["rulers","leaders","independence"],"b":"<b>26 November 1949:</b> Constitution adopted (<b>Constituent Assembly</b>; Drafting Committee chaired by <b>Dr. B. R. Ambedkar</b>; <b>B. N. Rau</b> adviser). <b>Reserve Bank of India</b> nationalized (1949). Ceasefire in Kashmir (1 January 1949)."},{"i":531,"t":"Constitution came into force 26 January 1950","d":"1950 CE","g":"Republic","y":1950,"e":12,"s":["rulers","independence"],"b":"<b>Constitution came into force 26 January 1950</b> (Republic Day); <b>Rajendra Prasad</b> first President (1950 to 1962); 28 states (A, B, C) and union territories. <b>Election Commission (1950)</b>, <b>Supreme Court (1950)</b>, <b>Planning Commission (1950)</b>, <b>Nehru-Liaquat Pact (1950)</b>; <b>Union Public Service Commission</b> constitutional (1950). <b>Chandernagore</b> (French enclave) joins India. <b>Mother Teresa</b> (<b>Missionaries of Charity</b>, 1950). <b>Eighth Schedule</b> originally had 14 languages (1950). <b>Abolition of Zamindari</b> (1950s). <b>Chandigarh</b> (Le Corbusier, from 1950s). Words ‘Socialist’ and ‘Secular’ later added to the Preamble by the <b>42nd Amendment (1976)</b>."},{"i":532,"t":"First General Elections (1951 to 1952)","d":"1951 CE","g":"","y":1951,"e":12,"s":["rulers","leaders"],"b":"<b>First General Elections (1951 to 1952):</b> the largest democratic exercise at the time (about 173 million voters); Congress wins; <b>Nehru</b> Prime Minister. <b>First Five-Year Plan (1951 to 1956)</b> (agriculture and irrigation; Harrod-Domar). <b>Bhoodan Movement</b> by <b>Vinoba Bhave</b> (1951, Pochampally). <b>IITs</b> (Kharagpur 1951). <b>1st Amendment (1951):</b> Reasonable restrictions on free speech; Ninth Schedule."},{"i":533,"t":"Potti Sriramulu","d":"1952 CE","g":"","y":1952,"e":12,"s":[],"b":"<b>Potti Sriramulu</b> fasts to death for <b>Andhra</b>."},{"i":534,"t":"Andhra State","d":"1953 CE","g":"","y":1953,"e":12,"s":[],"b":"<b>Andhra State</b> (from Madras). <b>Sangeet Natak Akademi</b> (1953). <b>Sahitya Akademi</b>."},{"i":535,"t":"Panchsheel (1954)","d":"1954 CE","g":"","y":1954,"e":12,"s":[],"b":"<b>Panchsheel (1954)</b> with China; <b>Pondicherry</b> (1954 de facto, 1962 de jure); <b>Dadra and Nagar Haveli</b> (1954); <b>Atomic Energy Dept.</b>; <b>Special Marriage Act (1954)</b>."},{"i":536,"t":"Bharat Ratna and Honours","d":"1954 CE","g":"Bharat Ratna, first recipients","y":1954,"e":12,"s":["leaders"],"b":"<b>Bharat Ratna and Honours:</b> First recipients (<b>1954</b>): <b>C. Rajagopalachari</b>, <b>S. Radhakrishnan</b>, <b>C. V. Raman</b>. Others include <b>Gandhi (not awarded)</b>."},{"i":537,"t":"Bandung Conference (1955)","d":"1955 CE","g":"","y":1955,"e":12,"s":["religion"],"b":"<b>Bandung Conference (1955)</b>. <b>Hindu Code Bills (1955 to 1956)</b>; <b>Hindu Marriage Act (1955)</b>; <b>Citizenship Act (1955)</b>. <b>Sahitya Akademi Awards</b> from 1955."},{"i":538,"t":"Nehru (1955)","d":"1955 CE","g":"Bharat Ratna","y":1955,"e":12,"s":["leaders"],"b":"<b>Nehru (1955)</b> receives the Bharat Ratna."},{"i":539,"t":"States Reorganisation Act (1956)","d":"1956 CE","g":"","y":1956,"e":12,"s":[],"b":"<b>States Reorganisation Act (1956)</b> creates 14 states and 6 union territories; <b>Kerala</b>, <b>Karnataka (Mysore)</b>, <b>Madhya Pradesh</b>, <b>Andhra Pradesh</b> (with Telangana), etc.; <b>7th Amendment (1956)</b>. <b>Second Five-Year Plan (1956 to 1961)</b> (P. C. Mahalanobis; heavy industry; <b>Industrial Policy Resolution 1956</b>); Bhilai, Rourkela, Durgapur steel plants; <b>Bhakra Nangal</b> dam. <b>AIIMS (1956)</b>. <b>Apsara</b> (first reactor in Asia). <b>Hindu Succession Act (1956)</b>. <b>Andaman and Nicobar</b> and <b>Lakshadweep</b> UTs (1956). <b>Ambedkar’s Buddhist conversion</b> with followers (14 October 1956, Nagpur); Ambedkar died 6 December 1956; mass conversion revives Buddhism."},{"i":540,"t":"DRDO","d":"1958 CE","g":"","y":1958,"e":12,"s":[],"b":"<b>DRDO</b> (1958)."},{"i":541,"t":"Tibetan Buddhist","d":"1959 CE","g":"","y":1959,"e":12,"s":["religion"],"b":"<b>Tibetan Buddhist</b> exiles from 1959 (<b>Dalai Lama</b> at <b>Dharamsala</b>)."},{"i":542,"t":"Bombay","d":"1960 CE","g":"","y":1960,"e":12,"s":[],"b":"<b>Bombay</b> split into <b>Maharashtra</b> and <b>Gujarat (1960)</b>. <b>Indus Waters Treaty (1960)</b>."},{"i":543,"t":"Goa liberated (December 1961, Operation Vijay)","d":"1961 CE","g":"","y":1961,"e":12,"s":[],"b":"<b>Goa liberated (December 1961, Operation Vijay)</b>; Goa, Daman and Diu UT (1961 to 1987). <b>NAM</b> (founded <b>Belgrade 1961</b>, with <b>Tito</b>, <b>Nasser</b>, <b>Sukarno</b>, <b>Nkrumah</b>); <b>Non-Alignment</b>. <b>Third Five-Year Plan (1961 to 1966)</b>: self-reliance; ended with wars and drought."},{"i":544,"t":"Sino-Indian War (October to November 1962)","d":"1962 CE","g":"","y":1962,"e":12,"s":["wars","leaders"],"b":"<b>Sino-Indian War (October to November 1962):</b> China attacks in NEFA (Arunachal) and Ladakh; Indian forces suffer a heavy defeat; unilateral Chinese ceasefire; a deep setback for Nehru’s policy. <b>S. Radhakrishnan</b> President (1962 to 1967). <b>INCOSPAR (1962)</b>."},{"i":545,"t":"Nagaland","d":"1963 CE","g":"","y":1963,"e":12,"s":[],"b":"<b>Nagaland</b>. First rocket from Thumba. <b>CBI</b> (1963)."},{"i":546,"t":"Nehru dies on 27 May 1964","d":"1964 CE","g":"","y":1964,"e":12,"s":["kingdoms","leaders"],"b":"<b>Nehru dies on 27 May 1964</b>. <b>Lal Bahadur Shastri</b> (1964 to 1966): “<b>Jai Jawan Jai Kisan</b>”. <b>Gulzarilal Nanda</b> (acting PM, 1964 and 1966)."},{"i":547,"t":"Second Indo-Pakistani War (August to September 1965)","d":"1965 CE","g":"","y":1965,"e":12,"s":["wars"],"b":"<b>Second Indo-Pakistani War (August to September 1965)</b> (Operation Gibraltar, Haji Pir, Asal Uttar, Chawinda; ceasefire). <b>Jnanpith Award</b> from 1965."},{"i":548,"t":"Tashkent Declaration (10 January 1966)","d":"1966 CE","g":"","y":1966,"e":12,"s":["leaders"],"b":"<b>Tashkent Declaration (10 January 1966)</b>; Shastri dies in Tashkent the next day. <b>Indira Gandhi</b> PM (January 1966; 1966 to 1977). <b>Devaluation of the rupee (1966)</b>. <b>Green Revolution (from 1966 to 1967):</b> HYV wheat and rice, <b>M. S. Swaminathan</b>, <b>Norman Borlaug</b>, <b>C. Subramaniam</b>. <b>Punjab</b> split (<b>1966</b>) into Punjab, Haryana, Himachal; <b>Haryana</b> and <b>Chandigarh (UT)</b>. <b>Plan holiday</b> (1966 to 1969)."},{"i":549,"t":"1967 elections","d":"1967 CE","g":"","y":1967,"e":12,"s":["rulers"],"b":"<b>1967 elections</b>: Congress weakened in several states; <b>Naxalbari uprising (1967)</b>. <b>Zakir Husain</b> President (1967 to 1969). <b>Nathu La and Cho La</b> clashes with China. <b>Sindhi</b> added to Eighth Schedule (1967)."},{"i":550,"t":"Har Gobind Khorana","d":"1968 CE","g":"","y":1968,"e":12,"s":[],"b":"<b>Har Gobind Khorana</b> (Nobel, 1968)."},{"i":551,"t":"Congress split (1969)","d":"1969 CE","g":"","y":1969,"e":12,"s":["science"],"b":"<b>Congress split (1969)</b>; <b>bank nationalization (14 banks, 1969)</b>. <b>V. V. Giri</b> (1969 to 1974; with acting terms for <b>Hidayatullah</b>). <b>ISRO (1969)</b>. <b>MRTP Act (1969)</b>. <b>Fourth Five-Year Plan (1969 to 1974)</b>."},{"i":552,"t":"White Revolution/Operation Flood (1970)","d":"1970 CE","g":"","y":1970,"e":12,"s":[],"b":"<b>White Revolution/Operation Flood (1970)</b> by <b>Verghese Kurien</b> (Amul, NDDB); Blue Revolution, Yellow Revolution (oilseeds), Golden Revolution (horticulture)."},{"i":553,"t":"Privy Purses abolished (1971)","d":"1971 CE","g":"Bangladesh War","y":1971,"e":12,"s":["wars"],"b":"<b>Privy Purses abolished (1971)</b>; “<b>Garibi Hatao</b>” (1971 landslide). <b>1971 Bangladesh Liberation War:</b> After the Pakistani crackdown (Operation Searchlight, March 1971) and millions of refugees; war from <b>3 to 16 December 1971</b>; <b>Pakistani army surrenders at Dhaka (16 December)</b> (about 93,000 prisoners); <b>Bangladesh</b> is created; <b>Sam Manekshaw</b> and <b>Jagjit Singh Aurora</b>. <b>Indo-Soviet Treaty (August 1971)</b>. <b>24th and 25th Amendments (1971)</b>: Parliament’s power to amend; right to property curbed. <b>Himachal Pradesh</b> state (1971)."},{"i":554,"t":"Simla Agreement (July 1972)","d":"1972 CE","g":"","y":1972,"e":12,"s":[],"b":"<b>Simla Agreement (July 1972)</b>. <b>Meghalaya</b>, <b>Manipur</b>, <b>Tripura</b> (1972). <b>Dalit Panthers (1972)</b>. <b>Wildlife Protection Act (1972)</b>."},{"i":555,"t":"Basic Structure doctrine","d":"1973 CE","g":"","y":1973,"e":12,"s":["kingdoms"],"b":"<b>Basic Structure doctrine</b> (<i>Kesavananda Bharati</i>, <b>1973</b>). <b>Anandpur Sahib Resolution (1973)</b>. <b>FERA (1973)</b>."},{"i":556,"t":"Pokhran-I","d":"1974 CE","g":"","y":1974,"e":12,"s":["religion","science","leaders"],"b":"<b>Pokhran-I</b> (Smiling Buddha, 18 May) nuclear test; <b>railway strike</b>; <b>Jayaprakash Narayan’s Total Revolution</b> and the Bihar movement; <b>Chipko movement</b> (<b>Sunderlal Bahuguna</b>, <b>Gaura Devi</b>, Reni 1974). <b>Fakhruddin Ali Ahmed</b> (President 1974 to 1977). <b>Fifth Five-Year Plan (1974 to 1978; ended early by Janata)</b>."},{"i":557,"t":"Allahabad High Court","d":"1975 CE","g":"Emergency","y":1975,"e":12,"s":["science","leaders"],"b":"<b>Allahabad High Court</b> (12 June) sets aside Indira Gandhi’s 1971 election; <b>The Emergency declared 25 June 1975</b>; press censorship; mass arrests; forced sterilization drives. <b>Aryabhata</b> satellite launched (<b>April 1975</b>). <b>Sikkim</b> becomes the 22nd state (1975)."},{"i":558,"t":"42nd Amendment (1976)","d":"1976 CE","g":"","y":1976,"e":12,"s":[],"b":"<b>42nd Amendment (1976)</b>: “mini-Constitution”; Preamble words (‘Socialist&#x27;, ‘Secular&#x27;); Fundamental Duties."},{"i":559,"t":"March 1977","d":"1977 CE","g":"","y":1977,"e":12,"s":["rulers"],"b":"<b>March 1977:</b> Emergency lifted; <b>first non-Congress government</b> (<b>Janata Party</b>) under <b>Morarji Desai</b> (1977 to 1979). <b>N. Sanjiva Reddy</b> President (1977 to 1982)."},{"i":560,"t":"44th Amendment (1978)","d":"1978 CE","g":"","y":1978,"e":12,"s":[],"b":"<b>44th Amendment (1978):</b> Removed right to property from Fundamental Rights; safeguards against Emergency. <b>Rolling Plan</b> (1978 to 1980)."},{"i":561,"t":"Charan Singh","d":"1979 CE","g":"","y":1979,"e":12,"s":[],"b":"<b>Charan Singh</b> briefly PM (1979 to 1980). <b>Mandal Commission (1979)</b>. <b>Mother Teresa</b> (Peace Nobel, 1979)."},{"i":562,"t":"January 1980","d":"1980 CE","g":"","y":1980,"e":12,"s":["science","leaders"],"b":"Congress returns (<b>January 1980</b>); Indira Gandhi PM (1980 to 1984). <b>Rohini</b> satellite launched by <b>SLV-3</b> (1980). <b>Bank nationalization</b> (1980). <b>Sixth Five-Year Plan (1980 to 1985)</b>. <b>Punjab crisis</b>: <b>Bhindranwale</b>."},{"i":563,"t":"Mother Teresa (1980)","d":"1980 CE","g":"Bharat Ratna","y":1980,"e":12,"s":[],"b":"<b>Mother Teresa (1980)</b> receives the Bharat Ratna."},{"i":564,"t":"INSAT","d":"1982 CE","g":"","y":1982,"e":12,"s":["rulers"],"b":"<b>INSAT</b> (1982). <b>Zail Singh</b> President (1982 to 1987)."},{"i":565,"t":"S. Chandrasekhar","d":"1983 CE","g":"","y":1983,"e":12,"s":["places","architecture"],"b":"<b>S. Chandrasekhar</b> (Nobel, 1983). <b>UNESCO World Heritage Sites in India:</b> 40+ properties, including <b>Ajanta</b>, <b>Ellora</b>, <b>Agra Fort</b>, <b>Taj Mahal</b> (all four inscribed in 1983), <b>Sun Temple Konark</b>, <b>Mahabalipuram</b>, <b>Kaziranga</b>, <b>Hampi</b>, <b>Khajuraho</b>, <b>Sanchi</b>, <b>Humayun’s Tomb</b>, <b>Qutb Minar</b>, <b>Red Fort</b>, <b>Jantar Mantar</b>, <b>Rani ki Vav</b>, <b>Great Living Chola Temples</b>, <b>Mountain Railways of India</b>."},{"i":566,"t":"Operation Meghdoot","d":"1984 CE","g":"","y":1984,"e":12,"s":["places","architecture","leaders"],"b":"<b>Operation Meghdoot</b> (Siachen, April). <b>Rakesh Sharma</b> becomes first Indian in space (Soyuz T-11). <b>Operation Blue Star (June 1984)</b> at the Golden Temple; <b>31 October 1984: Indira Gandhi assassinated</b> by her bodyguards; <b>anti-Sikh riots</b> (about 3,000 killed in Delhi). <b>Rajiv Gandhi</b> (1984 to 1989): landslide win (1984). <b>Bhopal gas tragedy (2 to 3 December 1984, Union Carbide)</b>."},{"i":567,"t":"Anti-defection law (1985)","d":"1985 CE","g":"","y":1985,"e":12,"s":[],"b":"<b>Anti-defection law (1985)</b>, <b>52nd Amendment</b> (Tenth Schedule); <b>Punjab Accord</b> and <b>Assam Accord (1985)</b>; <b>Shah Bano case (1985)</b>. <b>Seventh Five-Year Plan (1985 to 1990)</b>. Computer and telecom push."},{"i":568,"t":"National Education Policy 1986","d":"1986 CE","g":"","y":1986,"e":12,"s":["architecture"],"b":"<b>National Education Policy 1986</b>; <b>Mizo Accord (1986)</b>; <b>Babri Masjid</b> locks opened (1986); <b>Environment Protection Act (1986)</b>; <b>Consumer Protection Act (1986; replaced 2019)</b>; <b>Lotus Temple</b> (1986). <b>Bofors scandal</b> (Rajiv era)."},{"i":569,"t":"IPKF in Sri Lanka (1987 to 1990)","d":"1987 CE","g":"","y":1987,"e":12,"s":["rulers"],"b":"<b>IPKF in Sri Lanka (1987 to 1990)</b>. <b>Mizoram</b>, <b>Arunachal Pradesh</b>, <b>Goa</b> become states (1987). <b>R. Venkataraman</b> President (1987 to 1992)."},{"i":570,"t":"Operation Cactus","d":"1988 CE","g":"","y":1988,"e":12,"s":[],"b":"<b>Operation Cactus</b> (Maldives). <b>61st Amendment (1988):</b> Voting age lowered to 18. <b>SEBI</b> (1988; statutory 1992). <b>IRS</b> (1988)."},{"i":571,"t":"V. P. Singh","d":"1989 CE","g":"","y":1989,"e":12,"s":[],"b":"<b>V. P. Singh</b> (National Front; PM 1989 to 1990). <b>Shilanyas (1989)</b> at Ayodhya. <b>Kashmir insurgency</b> and <b>exodus of Kashmiri Pandits</b> (1989 to 1990). <b>SC/ST (Prevention of Atrocities) Act (1989)</b>."},{"i":572,"t":"Mandal Commission","d":"1990 CE","g":"","y":1990,"e":12,"s":[],"b":"<b>Mandal Commission</b> recommendations implemented (<b>27% OBC reservation, August 1990</b>), sparking protests; <b>L. K. Advani’s Rath Yatra</b> (1990). <b>Chandra Shekhar</b> (PM 1990 to 1991). Annual plans (1990 to 1992)."},{"i":573,"t":"Ambedkar (1990)","d":"1990 CE","g":"Bharat Ratna","y":1990,"e":12,"s":["leaders"],"b":"<b>Ambedkar (1990)</b> receives the Bharat Ratna."},{"i":574,"t":"Rajiv Gandhi assassinated by an LTTE suicide bomber at Sriperumbudur, 21 May 1991","d":"1991 CE","g":"","y":1991,"e":12,"s":["visitors","leaders"],"b":"<b>Rajiv Gandhi assassinated by an LTTE suicide bomber at Sriperumbudur, 21 May 1991</b>. <b>1991 economic crisis and reforms:</b> foreign exchange nearly exhausted; <b>P. V. Narasimha Rao</b> (PM, 1991 to 1996) with <b>Manmohan Singh</b> (Finance Minister): <b>liberalization, privatization, globalization</b>: devaluation, delicensing, trade liberalization. <b>Delhi</b> UT with legislature (1991 under the 69th Amendment)."},{"i":575,"t":"Sardar Patel (1991)","d":"1991 CE","g":"Bharat Ratna","y":1991,"e":12,"s":["leaders"],"b":"<b>Sardar Patel (1991)</b> receives the Bharat Ratna."},{"i":576,"t":"6 December 1992","d":"1992 CE","g":"","y":1992,"e":12,"s":["languages"],"b":"<b>6 December 1992:</b> <b>Babri Masjid demolished</b> at Ayodhya; communal riots. <b>73rd and 74th Amendments (1992)</b> institutionalize Panchayati Raj and municipalities. <b>Konkani, Manipuri, Nepali</b> added to the Eighth Schedule (1992). <b>NCW (1992)</b>. <b>Eighth Five-Year Plan (1992 to 1997; liberalization)</b>. <b>Shankar Dayal Sharma</b> President (1992 to 1997)."},{"i":577,"t":"1993 Mumbai bombings","d":"1993 CE","g":"","y":1993,"e":12,"s":[],"b":"<b>1993 Mumbai bombings</b> (12 March). <b>PSLV</b> (1993 first launch). <b>NHRC (1993)</b>."},{"i":578,"t":"Vajpayee","d":"1996 CE","g":"","y":1996,"e":12,"s":[],"b":"Unstable coalitions: <b>Vajpayee</b> (13 days, 1996), <b>H. D. Deve Gowda</b> (1996 to 1997)."},{"i":579,"t":"I. K. Gujral","d":"1997 CE","g":"","y":1997,"e":12,"s":["rulers"],"b":"<b>I. K. Gujral</b> (1997 to 1998). <b>K. R. Narayanan</b> President (1997 to 2002). <b>Ninth Five-Year Plan (1997 to 2002)</b>."},{"i":580,"t":"Atal Bihari Vajpayee","d":"1998 CE","g":"","y":1998,"e":12,"s":[],"b":"<b>Atal Bihari Vajpayee</b> (NDA; PM 1998 to 2004). <b>Pokhran-II (May 1998)</b>. <b>Amartya Sen</b> (Nobel, 1998)."},{"i":581,"t":"Lahore bus diplomacy (1999)","d":"1999 CE","g":"","y":1999,"e":12,"s":["wars"],"b":"<b>Lahore bus diplomacy (1999)</b>; <b>Kargil War (May to July 1999)</b> (<b>Operation Vijay</b>); <b>IC-814 hijacking (December 1999)</b>."},{"i":582,"t":"Creation of Chhattisgarh, Uttarakhand, Jharkhand (2000)","d":"2000 CE","g":"","y":2000,"e":12,"s":[],"b":"<b>Creation of Chhattisgarh, Uttarakhand, Jharkhand (2000)</b>; <b>Golden Quadrilateral</b>, <b>PMGSY</b>; <b>telecom and IT boom</b> (Vajpayee era)."},{"i":583,"t":"Agra Summit (2001)","d":"2001 CE","g":"","y":2001,"e":12,"s":[],"b":"<b>Agra Summit (2001)</b>; <b>2001 Parliament attack (13 December)</b>."},{"i":584,"t":"Lata Mangeshkar (2001)","d":"2001 CE","g":"Bharat Ratna","y":2001,"e":12,"s":[],"b":"<b>Lata Mangeshkar (2001)</b> receives the Bharat Ratna."},{"i":585,"t":"2002 Gujarat violence","d":"2002 CE","g":"","y":2002,"e":12,"s":["rulers"],"b":"<b>2002 Gujarat violence</b> (Godhra train burning, 27 February, and subsequent riots). <b>A. P. J. Abdul Kalam</b> President (2002 to 2007). <b>86th Amendment (2002):</b> Right to education (Article 21A). <b>Tenth Five-Year Plan (2002 to 2007)</b>."},{"i":586,"t":"Bodo, Dogri, Maithili, Santhali","d":"2003 CE","g":"","y":2003,"e":12,"s":[],"b":"<b>Bodo, Dogri, Maithili, Santhali</b> added to the Eighth Schedule (2003). <b>91st Amendment (2003):</b> limits on ministers."},{"i":587,"t":"Manmohan Singh","d":"2004 CE","g":"","y":2004,"e":12,"s":["languages","leaders"],"b":"<b>Manmohan Singh</b> PM (2004 to 2014); <b>Sonia Gandhi</b>. <b>Tamil</b> granted classical language status (2004)."},{"i":588,"t":"MGNREGA (2005)","d":"2005 CE","g":"","y":2005,"e":12,"s":["science","languages"],"b":"<b>MGNREGA (2005)</b> (NREGA 2005), <b>Right to Information Act (2005)</b>, <b>Indo-US Civil Nuclear Deal (2005 to 2008)</b>. <b>Sanskrit</b> classical language status (2005). <b>CIC (2005)</b>. <b>Akshardham</b> (Delhi, 2005)."},{"i":589,"t":"Forest Rights Act (2006)","d":"2006 CE","g":"","y":2006,"e":12,"s":[],"b":"<b>Forest Rights Act (2006)</b>."},{"i":590,"t":"Pratibha Patil","d":"2007 CE","g":"","y":2007,"e":12,"s":["rulers"],"b":"<b>Pratibha Patil</b> President (2007 to 2012; first woman). <b>Eleventh Five-Year Plan (2007 to 2012)</b>."},{"i":591,"t":"2008 Mumbai terror attacks (26/11)","d":"2008 CE","g":"","y":2008,"e":12,"s":["science","languages"],"b":"<b>2008 Mumbai terror attacks (26/11)</b>; <b>Chandrayaan-1 (2008)</b> (and <b>Moon Impact Probe</b>). <b>Telugu and Kannada</b> classical language status (2008)."},{"i":592,"t":"Right to Education Act (2009)","d":"2009 CE","g":"","y":2009,"e":12,"s":["kingdoms"],"b":"<b>Right to Education Act (2009)</b>; <b>Aadhaar (from 2009; Nandan Nilekani)</b>. <b>Venkatraman Ramakrishnan</b> (Nobel, 2009)."},{"i":593,"t":"National Green Tribunal (2010)","d":"2010 CE","g":"","y":2010,"e":12,"s":[],"b":"<b>National Green Tribunal (2010)</b>. <b>2G spectrum, Commonwealth Games, Coalgate</b> scandals (UPA era)."},{"i":594,"t":"India Against Corruption","d":"2011 CE","g":"","y":2011,"e":12,"s":[],"b":"<b>India Against Corruption</b> movement (<b>Anna Hazare</b>, 2011)."},{"i":595,"t":"Pranab Mukherjee","d":"2012 CE","g":"","y":2012,"e":12,"s":["rulers"],"b":"<b>Pranab Mukherjee</b> President (2012 to 2017). <b>Twelfth Five-Year Plan (2012 to 2017)</b>."},{"i":596,"t":"Mangalyaan (Mars Orbiter Mission)","d":"2013 CE","g":"","y":2013,"e":12,"s":["languages"],"b":"<b>Mangalyaan (Mars Orbiter Mission)</b> launched November 2013. <b>Malayalam</b> classical language status (2013). <b>National Food Security Act (2013)</b>; <b>Lokpal Act (2013)</b>."},{"i":597,"t":"Narendra Modi","d":"2014 CE","g":"","y":2014,"e":12,"s":[],"b":"<b>Narendra Modi</b> (BJP) becomes PM after a majority win (2014 onward); <b>Make in India</b>, <b>Swachh Bharat</b>, <b>Jan Dhan Yojana</b>, <b>Digital India</b>. <b>Telangana</b> state formed (2014). Mangalyaan reaches Mars <b>24 September 2014</b>. <b>Odia</b> classical language status (2014). <b>GSLV Mk III</b> (2014). <b>Kailash Satyarthi</b> (Nobel, 2014)."},{"i":598,"t":"Sachin Tendulkar (2014)","d":"2014 CE","g":"Bharat Ratna","y":2014,"e":12,"s":[],"b":"<b>Sachin Tendulkar (2014)</b> receives the Bharat Ratna."},{"i":599,"t":"NITI Aayog (2015)","d":"2015 CE","g":"","y":2015,"e":12,"s":[],"b":"Planning Commission replaced by <b>NITI Aayog (2015)</b> (1 January 2015)."},{"i":600,"t":"Atal Bihari Vajpayee (2015)","d":"2015 CE","g":"Bharat Ratna","y":2015,"e":12,"s":[],"b":"<b>Atal Bihari Vajpayee (2015)</b> receives the Bharat Ratna."},{"i":601,"t":"Demonetization","d":"2016 CE","g":"","y":2016,"e":12,"s":[],"b":"<b>Demonetization</b> (8 November); <b>Surgical strikes</b> across the LoC (September) after the Uri attack; <b>Insolvency and Bankruptcy Code</b> (IBC); <b>UPI</b> launched. <b>101st Amendment (2016):</b> GST. <b>RERA (2016)</b>. <b>NavIC</b> and <b>INS Arihant</b> (nuclear submarine, 2016). <b>Nalanda Mahavihara</b> (UNESCO, 2016)."},{"i":602,"t":"Goods and Services Tax (GST)","d":"2017 CE","g":"","y":2017,"e":12,"s":[],"b":"<b>Goods and Services Tax (GST)</b> launched (1 July) (GST Act 2017); <b>Triple Talaq</b> declared unconstitutional by the Supreme Court; <b>Right to Privacy</b> recognized as a fundamental right (<b>Puttaswamy</b>). <b>Ram Nath Kovind</b> President (2017 to 2022). <b>104 satellites in one launch</b> (2017). <b>Ahmedabad’s Historic City</b> (UNESCO, 2017)."},{"i":603,"t":"Section 377","d":"2018 CE","g":"","y":2018,"e":12,"s":[],"b":"<b>Section 377</b> read down by the Supreme Court (decriminalizing consensual same-sex relations). <b>Statue of Unity</b> (2018)."},{"i":604,"t":"Pulwama attack (14 February)","d":"2019 CE","g":"","y":2019,"e":12,"s":[],"b":"<b>Pulwama attack (14 February)</b> and <b>Balakot airstrike (26 February)</b>; Modi re-elected with a larger majority (May); <b>Article 370</b> provisions abrogated (<b>5 August</b>) and <b>Jammu and Kashmir</b> reorganized into two Union Territories (<b>Jammu and Kashmir</b> with legislature, and <b>Ladakh</b>); <b>Supreme Court Ayodhya verdict (9 November)</b>; <b>Citizenship Amendment Act (December)</b> and nationwide protests. <b>103rd Amendment (2019):</b> 10% reservation for economically weaker sections. <b>104th (2019):</b> Anglo-Indian seats ended. <b>Transgender Persons Act (2019)</b>; <b>Triple Talaq Act (2019)</b>. <b>Chandrayaan-2</b> orbiter (2019). <b>Abhijit Banerjee</b> (Nobel, 2019). <b>Jaipur City</b> (UNESCO, 2019)."},{"i":605,"t":"COVID-19 pandemic","d":"2020 CE","g":"","y":2020,"e":12,"s":[],"b":"<b>COVID-19 pandemic</b>, nationwide lockdown (from 25 March 2020); <b>Galwan Valley clash with China (June 2020)</b>; <b>farm laws protests</b> (2020 to 2021); <b>National Education Policy 2020</b>. <b>Dadra and Nagar Haveli and Daman and Diu</b> merged (2020). Current total: <b>28 states and 8 Union Territories</b>."},{"i":606,"t":"Covishield","d":"2021 CE","g":"","y":2021,"e":12,"s":["places","architecture"],"b":"Vaccine drive (from 16 January 2021) with <b>Covishield</b> and <b>Covaxin</b> (COVID vaccines); farm laws protests end with repeal (November 2021). <b>Dholavira</b> and <b>Ramappa Temple</b> (UNESCO, 2021)."},{"i":607,"t":"Droupadi Murmu","d":"2022 CE","g":"","y":2022,"e":12,"s":["rulers"],"b":"<b>Droupadi Murmu</b> becomes the first tribal and second woman President (July; President 2022 onward); <b>Azadi Ka Amrit Mahotsav</b> (75 years of independence); India becomes the world’s fifth-largest economy by nominal GDP."},{"i":608,"t":"G20 presidency","d":"2023 CE","g":"","y":2023,"e":12,"s":["science"],"b":"<b>G20 presidency</b> and <b>New Delhi Summit (September)</b>; <b>Chandrayaan-3</b> lands near the lunar south pole (<b>23 August</b>), India the fourth country to soft-land on the Moon; <b>Aditya-L1</b> solar mission launched (September); <b>Nari Shakti Vandan Adhiniyam</b> (women’s reservation, September; <b>106th Amendment</b>: women’s reservation in Lok Sabha and state assemblies); new <b>Parliament building</b> inaugurated (May) (<b>New Parliament Building</b>, 2023); <b>Manipur ethnic violence</b> begins (May); India’s population estimated to overtake China’s. <b>Digital Personal Data Protection Act (2023)</b>. <b>Santiniketan</b> and <b>Hoysala temples</b> (UNESCO, 2023). <b>Gaganyaan</b> program (human spaceflight preparation); <b>Agni</b> and <b>Prithvi</b> missile families; <b>Tejas</b> fighter."},{"i":609,"t":"Ram Mandir","d":"2024 CE","g":"","y":2024,"e":12,"s":[],"b":"<b>Ram Mandir</b> consecration at Ayodhya (22 January); <b>general elections (April to June)</b>: BJP-led <b>NDA</b> forms the government, <b>Narendra Modi</b> sworn in for a third term (9 June), though BJP falls short of a single-party majority; new criminal law codes (<b>Bharatiya Nyaya Sanhita</b> and others) come into effect (July); <b>Jammu and Kashmir assembly elections</b> (first since 2014). <b>Marathi, Pali, Prakrit, Assamese, and Bengali</b> granted classical language status (2024). <b>Moidams of Assam</b> (UNESCO, 2024)."},{"i":610,"t":"Bharat Ratna","d":"2024 CE","g":"Bharat Ratna","y":2024,"e":12,"s":[],"b":"Bharat Ratna conferred on <b>Karpoori Thakur, L. K. Advani, P. V. Narasimha Rao, Charan Singh, M. S. Swaminathan (2024)</b>."},{"i":611,"t":"Maha Kumbh Mela at Prayagraj","d":"2025 CE","g":"","y":2025,"e":12,"s":[],"b":"<b>Maha Kumbh Mela at Prayagraj</b> (January to February); <b>Pahalgam terror attack (22 April)</b>; <b>Operation Sindoor</b> (7 May) strikes on terror sites in Pakistan and Pakistan-held Kashmir, followed by a brief military exchange and ceasefire (10 May); India places the Indus Waters Treaty “in abeyance”; Indian astronaut <b>Shubhanshu Shukla</b> visits the International Space Station (Axiom-4 mission, June to July)."},{"i":612,"t":"2026 CE","d":"2026 CE","g":"","y":2026,"e":12,"s":[],"b":"Reliable details thin out after mid-2026. For recent events (state elections, census and delimitation debates, trade and diplomatic developments), please check current news sources."}];
